import isAction from '@internal/utils/isAction'

describe('isAction', () => {
  it('should only return true for plain objects with a string type property', () => {
    const actionCreator = () => ({ type: 'anAction' })
    class Action {
      type = 'totally an action'
    }
    const testCases: [action: unknown, expected: boolean][] = [
      [{ type: 'an action' }, true],
      [{ type: 'more props', extra: true }, true],
      [{ type: 0 }, false],
      [actionCreator(), true],
      [actionCreator, false],
      [Promise.resolve({ type: 'an action' }), false],
      [new Action(), false],
      ['a string', false]
    ]
    for (const [action, expected] of testCases) {
      expect(isAction(action)).toBe(expected)
    }
  })
})

/* eslint-disable no-console */
import { vi } from 'vitest'
import warning from '@internal/utils/warning'

describe('Utils', () => {
  describe('warning', () => {
    it('calls console.error when available', () => {
      const preSpy = console.error
      const spy = vi.fn()
      console.error = spy
      try {
        warning('Test')
        expect(spy.mock.calls[0][0]).toBe('Test')
      } finally {
        spy.mockClear()
        console.error = preSpy
      }
    })

    it('does not throw when console.error is not available', () => {
      const realConsole = global.console
      Object.defineProperty(global, 'console', { value: {} })
      try {
        expect(() => warning('Test')).not.toThrow()
      } finally {
        Object.defineProperty(global, 'console', { value: realConsole })
      }
    })

    it('does not throw when console is not available', () => {
      const realConsole = global.console
      Object.defineProperty(global, 'console', { value: undefined })
      try {
        expect(() => warning('Test')).not.toThrow()
      } finally {
        Object.defineProperty(global, 'console', { value: realConsole })
      }
    })
  })
})

import isPlainObject from '@internal/utils/isPlainObject'
import vm from 'vm'

describe('isPlainObject', () => {
  it('returns true only if plain object', () => {
    const sandbox = { fromAnotherRealm: false }
    vm.runInNewContext('fromAnotherRealm = {}', sandbox)

    expect(isPlainObject(sandbox.fromAnotherRealm)).toBe(true)
    expect(isPlainObject(new Date())).toBe(false)
    expect(isPlainObject([1, 2, 3])).toBe(false)
    expect(isPlainObject(null)).toBe(false)
    expect(isPlainObject(undefined)).toBe(false)
    expect(isPlainObject({ x: 1, y: 2 })).toBe(true)
    expect(isPlainObject(Object.create(null))).toBe(true)
  })
})

import {
  ADD_TODO,
  DISPATCH_IN_MIDDLE,
  GET_STATE_IN_MIDDLE,
  SUBSCRIBE_IN_MIDDLE,
  UNSUBSCRIBE_IN_MIDDLE,
  THROW_ERROR
} from './actionTypes'

function id(state: { id: number }[]) {
  return (
    state.reduce((result, item) => (item.id > result ? item.id : result), 0) + 1
  )
}

export interface Todo {
  id: number
  text: string
}
export type TodoAction = { type: 'ADD_TODO'; text: string }

export function todos(state: Todo[] = [], action: TodoAction): Todo[] {
  switch (action.type) {
    case ADD_TODO:
      return [
        ...state,
        {
          id: id(state),
          text: action.text
        }
      ]
    default:
      return state
  }
}

export function todosReverse(state: Todo[] = [], action: TodoAction) {
  switch (action.type) {
    case ADD_TODO:
      return [
        {
          id: id(state),
          text: action.text
        },
        ...state
      ]
    default:
      return state
  }
}

export function dispatchInTheMiddleOfReducer(
  state = [],
  action: { type: 'DISPATCH_IN_MIDDLE'; boundDispatchFn: () => void }
) {
  switch (action.type) {
    case DISPATCH_IN_MIDDLE:
      action.boundDispatchFn()
      return state
    default:
      return state
  }
}

export function getStateInTheMiddleOfReducer(
  state = [],
  action: { type: 'GET_STATE_IN_MIDDLE'; boundGetStateFn: () => void }
) {
  switch (action.type) {
    case GET_STATE_IN_MIDDLE:
      action.boundGetStateFn()
      return state
    default:
      return state
  }
}

export function subscribeInTheMiddleOfReducer(
  state = [],
  action: { type: 'SUBSCRIBE_IN_MIDDLE'; boundSubscribeFn: () => void }
) {
  switch (action.type) {
    case SUBSCRIBE_IN_MIDDLE:
      action.boundSubscribeFn()
      return state
    default:
      return state
  }
}

export function unsubscribeInTheMiddleOfReducer(
  state = [],
  action: { type: 'UNSUBSCRIBE_IN_MIDDLE'; boundUnsubscribeFn: () => void }
) {
  switch (action.type) {
    case UNSUBSCRIBE_IN_MIDDLE:
      action.boundUnsubscribeFn()
      return state
    default:
      return state
  }
}

export function errorThrowingReducer(
  state = [],
  action: { type: 'THROW_ERROR' }
) {
  switch (action.type) {
    case THROW_ERROR:
      throw new Error()
    default:
      return state
  }
}

import {
  ADD_TODO,
  DISPATCH_IN_MIDDLE,
  GET_STATE_IN_MIDDLE,
  SUBSCRIBE_IN_MIDDLE,
  UNSUBSCRIBE_IN_MIDDLE,
  THROW_ERROR,
  UNKNOWN_ACTION
} from './actionTypes'
import type { TodoAction } from './reducers'
import type { Dispatch } from 'redux'

export function addTodo(text: string): TodoAction {
  return { type: ADD_TODO, text }
}

export function addTodoAsync(text: string) {
  return (dispatch: Dispatch): Promise<void> =>
    new Promise(resolve =>
      setImmediate(() => {
        dispatch(addTodo(text))
        resolve()
      })
    )
}

export function addTodoIfEmpty(text: string) {
  return (dispatch: Dispatch, getState: () => any) => {
    if (!getState().length) {
      dispatch(addTodo(text))
    }
  }
}

export function dispatchInMiddle(boundDispatchFn: () => void) {
  return {
    type: DISPATCH_IN_MIDDLE,
    boundDispatchFn
  } as const
}

export function getStateInMiddle(boundGetStateFn: () => void) {
  return {
    type: GET_STATE_IN_MIDDLE,
    boundGetStateFn
  } as const
}

export function subscribeInMiddle(boundSubscribeFn: () => void) {
  return {
    type: SUBSCRIBE_IN_MIDDLE,
    boundSubscribeFn
  } as const
}

export function unsubscribeInMiddle(boundUnsubscribeFn: () => void) {
  return {
    type: UNSUBSCRIBE_IN_MIDDLE,
    boundUnsubscribeFn
  } as const
}

export function throwError() {
  return {
    type: THROW_ERROR
  } as const
}

export function unknownAction() {
  return {
    type: UNKNOWN_ACTION
  } as const
}

