import resolve from '@rollup/plugin-node-resolve';
import commonjs from '@rollup/plugin-commonjs';
import terser from '@rollup/plugin-terser';
import json from '@rollup/plugin-json';
import { babel } from '@rollup/plugin-babel';
import bundleSize from 'rollup-plugin-bundle-size';
import aliasPlugin from '@rollup/plugin-alias';
import path from 'path';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const lib = require('./package.json');
const outputFileName = 'axios';
const name = 'axios';
const namedInput = './index.js';
const defaultInput = './lib/axios.js';

const buildConfig = ({ es5, browser = true, minifiedVersion = true, alias, ...config }) => {
  const { file } = config.output;
  const ext = path.extname(file);
  const basename = path.basename(file, ext);
  const extArr = ext.split('.');
  extArr.shift();

  const build = ({ minified }) => ({
    input: namedInput,
    ...config,
    output: {
      ...config.output,
      file: `${path.dirname(file)}/${basename}.${(minified ? ['min', ...extArr] : extArr).join('.')}`,
    },
    plugins: [
      aliasPlugin({
        entries: alias || [],
      }),
      json(),
      resolve({ browser }),
      commonjs(),

      minified &&
        terser({
          maxWorkers: 1,
        }),
      minified && bundleSize(),
      ...(es5
        ? [
            babel({
              babelHelpers: 'bundled',
              presets: ['@babel/preset-env'],
            }),
          ]
        : []),
      ...(config.plugins || []),
    ],
  });

  const configs = [build({ minified: false })];

  if (minifiedVersion) {
    configs.push(build({ minified: true }));
  }

  return configs;
};

const nodeCjsExternal = (id) => {
  if (id === 'proxy-from-env') {
    return false;
  }

  if (id.startsWith('.') || path.isAbsolute(id) || id.startsWith('\0')) {
    return false;
  }

  return true;
};

export default async () => {
  const year = new Date().getFullYear();
  const banner = `/*! Axios v${lib.version} Copyright (c) ${year} ${lib.author} and contributors */`;

  return [
    // browser ESM bundle for CDN
    ...buildConfig({
      input: namedInput,
      output: {
        file: `dist/esm/${outputFileName}.js`,
        format: 'esm',
        exports: 'named',
        banner,
      },
    }),

    // Browser UMD bundle for CDN
    ...buildConfig({
      input: defaultInput,
      es5: true,
      output: {
        file: `dist/${outputFileName}.js`,
        name,
        format: 'umd',
        exports: 'default',
        banner,
      },
    }),

    // Browser CJS bundle
    ...buildConfig({
      input: defaultInput,
      es5: false,
      minifiedVersion: false,
      output: {
        file: `dist/browser/${name}.cjs`,
        name,
        format: 'cjs',
        exports: 'default',
        banner,
      },
    }),

    // Node.js commonjs bundle (transpiled for Node 12)
    {
      input: defaultInput,
      external: nodeCjsExternal,
      output: {
        file: `dist/node/${name}.cjs`,
        format: 'cjs',
        exports: 'default',
        banner,
      },
      plugins: [
        resolve(),
        commonjs(),
        babel({
          babelHelpers: 'bundled',
          presets: [['@babel/preset-env', { targets: { node: '12' } }]],
        }),
      ],
    },
  ];
};

import gulp from 'gulp';
import fs from 'fs-extra';
import axios from './scripts/axios-build-instance.js';
import minimist from 'minimist';

const argv = minimist(process.argv.slice(2));

gulp.task('default', async function () {
  console.log('hello!');
});

const clear = gulp.task('clear', async function () {
  await fs.emptyDir('./dist/');
});

async function getContributors(user, repo, maxCount = 1) {
  const contributors = (
    await axios.get(
      `https://api.github.com/repos/${encodeURIComponent(user)}/${encodeURIComponent(repo)}/contributors`,
      { params: { per_page: maxCount } }
    )
  ).data;

  return Promise.all(
    contributors.map(async (contributor) => {
      return {
        ...contributor,
        ...(
          await axios.get(`https://api.github.com/users/${encodeURIComponent(contributor.login)}`)
        ).data,
      };
    })
  );
}

const packageJSON = gulp.task('package', async function () {
  const CONTRIBUTION_THRESHOLD = 3;

  const npm = JSON.parse(await fs.readFile('package.json'));

  try {
    const contributors = await getContributors('axios', 'axios', 15);

    npm.contributors = contributors
      .filter(
        ({ type, contributions }) =>
          type.toLowerCase() === 'user' && contributions >= CONTRIBUTION_THRESHOLD
      )
      .map(({ login, name, _ }) => `${name || login} (https://github.com/${login})`);

    await fs.writeFile('package.json', JSON.stringify(npm, null, 2));
  } catch (err) {
    if (axios.isAxiosError(err) && err.response && err.response.status === 403) {
      throw Error(`GitHub API Error: ${err.response.data && err.response.data.message}`);
    }
    throw err;
  }
});

const env = gulp.task('env', async function () {
  var npm = JSON.parse(await fs.readFile('package.json'));

  const envFilePath = './lib/env/data.js';

  await fs.writeFile(
    envFilePath,
    Object.entries({
      VERSION: (argv.bump || npm.version).replace(/^v/, ''),
    })
      .map(([key, value]) => {
        return `export const ${key} = ${JSON.stringify(value)};`;
      })
      .join('\n')
  );
});

const version = gulp.series('env', 'package');

export { env, clear, version, packageJSON };

