/**
 * Combined regression tests (issues 4999, 5028, 7364 + SSRF SNYK-1038255, SNYK-7361793).
 */
import { describe, it, beforeEach, afterEach, vi } from 'vitest';
import assert from 'assert';
import http from 'http';
import axios from '../../index.js';
import platform from '../../lib/platform/index.js';

describe('regression', () => {
  describe('issues', () => {
    describe('4999', () => {
      // Depends on network: https://postman-echo.com
      it('should not fail with query parsing', async () => {
        const { data } = await axios.get('https://postman-echo.com/get?foo1=bar1&foo2=bar2');

        assert.strictEqual(data.args.foo1, 'bar1');
        assert.strictEqual(data.args.foo2, 'bar2');
      });
    });

    describe('5028', () => {
      it('should handle set-cookie headers as an array', async () => {
        const cookie1 =
          'something=else; path=/; expires=Wed, 12 Apr 2023 12:03:42 GMT; samesite=lax; secure; httponly';
        const cookie2 =
          'something-ssr.sig=n4MlwVAaxQAxhbdJO5XbUpDw-lA; path=/; expires=Wed, 12 Apr 2023 12:03:42 GMT; samesite=lax; secure; httponly';

        const server = http
          .createServer((req, res) => {
            res.setHeader('Set-Cookie', [cookie1, cookie2]);
            res.writeHead(200);
            res.write('Hi there');
            res.end();
          })
          .listen(0);

        const request = axios.create();

        request.interceptors.response.use((res) => {
          assert.deepStrictEqual(res.headers['set-cookie'], [cookie1, cookie2]);
        });

        try {
          await request({ url: `http://localhost:${server.address().port}` });
        } finally {
          server.close();
        }
      });
    });

    describe('7364', () => {
      it('fetch: should have status code in axios error', async () => {
        const isFetchSupported = typeof fetch === 'function';
        if (!isFetchSupported) {
          vi.skip();
        }

        const server = http
          .createServer((req, res) => {
            res.statusCode = 400;
            res.end();
          })
          .listen(0);

        const instance = axios.create({
          baseURL: `http://localhost:${server.address().port}`,
          adapter: 'fetch',
        });

        try {
          await instance.get('/status/400');
        } catch (error) {
          assert.equal(error.name, 'AxiosError');
          assert.equal(error.isAxiosError, true);
          assert.equal(error.status, 400);
        } finally {
          server.close();
        }
      });

      it('http: should have status code in axios error', async () => {
        const server = http
          .createServer((req, res) => {
            res.statusCode = 400;
            res.end();
          })
          .listen(0);

        const instance = axios.create({
          baseURL: `http://localhost:${server.address().port}`,
          adapter: 'http',
        });

        try {
          await instance.get('/status/400');
        } catch (error) {
          assert.equal(error.name, 'AxiosError');
          assert.equal(error.isAxiosError, true);
          assert.equal(error.status, 400);
        } finally {
          server.close();
        }
      });
    });
  });

  // https://snyk.io/vuln/SNYK-JS-AXIOS-1038255
  // https://github.com/axios/axios/issues/3407
  // https://github.com/axios/axios/issues/3369
  describe('SSRF SNYK-JS-AXIOS-1038255', () => {
    let fail = false;
    let proxy;
    let server;
    let location;
    let evilPort;
    let proxyPort;

    beforeEach(() => {
      fail = false;
      server = http
        .createServer((req, res) => {
          fail = true;
          res.end('rm -rf /');
        })
        .listen(0);
      evilPort = server.address().port;

      proxy = http
        .createServer((req, res) => {
          if (
            new URL(req.url, 'http://' + req.headers.host).toString() ===
            'http://localhost:' + evilPort + '/'
          ) {
            return res.end(
              JSON.stringify({
                msg: 'Protected',
                headers: req.headers,
              })
            );
          }
          res.writeHead(302, { location });
          res.end();
        })
        .listen(0);
      proxyPort = proxy.address().port;
      location = 'http://localhost:' + evilPort;
    });

    afterEach(() => {
      server.close();
      proxy.close();
    });

    it('obeys proxy settings when following redirects', async () => {
      const response = await axios({
        method: 'get',
        url: 'http://www.google.com/',
        proxy: {
          host: 'localhost',
          port: proxyPort,
          auth: {
            username: 'sam',
            password: 'password',
          },
        },
      });

      assert.strictEqual(fail, false);
      assert.strictEqual(response.data.msg, 'Protected');
      assert.strictEqual(response.data.headers.host, 'localhost:' + evilPort);
      assert.strictEqual(
        response.data.headers['proxy-authorization'],
        'Basic ' + Buffer.from('sam:password').toString('base64')
      );

      return response;
    });
  });

  // https://security.snyk.io/vuln/SNYK-JS-AXIOS-7361793
  // https://github.com/axios/axios/issues/6463
  describe('SSRF SNYK-JS-AXIOS-7361793', () => {
    let goodServer;
    let badServer;
    let goodPort;
    let badPort;

    beforeEach(() => {
      goodServer = http
        .createServer((req, res) => {
          res.write('good');
          res.end();
        })
        .listen(0);
      goodPort = goodServer.address().port;

      badServer = http
        .createServer((req, res) => {
          res.write('bad');
          res.end();
        })
        .listen(0);
      badPort = badServer.address().port;
    });

    afterEach(() => {
      goodServer.close();
      badServer.close();
    });

    it('should not fetch in server-side mode', async () => {
      const ssrfAxios = axios.create({
        baseURL: 'http://localhost:' + String(goodPort),
      });

      const userId = '/localhost:' + String(badPort);

      try {
        await ssrfAxios.get(`/${userId}`);
      } catch (error) {
        assert.ok(error.message.startsWith('Invalid URL'));
        return;
      }
      assert.fail('Expected an error to be thrown');
    });

    describe('client-side mode', () => {
      let savedHasBrowserEnv;
      let savedOrigin;

      beforeEach(() => {
        assert.ok(platform.hasBrowserEnv !== undefined);
        savedHasBrowserEnv = platform.hasBrowserEnv;
        savedOrigin = platform.origin;
        platform.hasBrowserEnv = true;
        platform.origin = 'http://localhost:' + String(goodPort);
      });

      afterEach(() => {
        platform.hasBrowserEnv = savedHasBrowserEnv;
        platform.origin = savedOrigin;
      });

      it('resolves URL relative to origin and returns bad server body', async () => {
        const ssrfAxios = axios.create({
          baseURL: 'http://localhost:' + String(goodPort),
        });

        const userId = '/localhost:' + String(badPort);

        const response = await ssrfAxios.get(`/${userId}`);
        assert.strictEqual(response.data, 'bad');
        assert.strictEqual(response.config.baseURL, 'http://localhost:' + String(goodPort));
        assert.strictEqual(response.config.url, '//localhost:' + String(badPort));
        assert.strictEqual(
          response.request.res.responseUrl,
          'http://localhost:' + String(badPort) + '/'
        );
      });
    });
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import estimateDataURLDecodedBytes from '../../lib/helpers/estimateDataURLDecodedBytes.js';

describe('estimateDataURLDecodedBytes', () => {
  it('should return 0 for non-data URLs', () => {
    assert.strictEqual(estimateDataURLDecodedBytes('http://example.com'), 0);
  });

  it('should calculate length for simple non-base64 data URL', () => {
    const url = 'data:,Hello';
    assert.strictEqual(estimateDataURLDecodedBytes(url), Buffer.byteLength('Hello', 'utf8'));
  });

  it('should calculate decoded length for percent-encoded non-base64 data URL', () => {
    const url = 'data:text/plain,%E2%82%AC';
    assert.strictEqual(estimateDataURLDecodedBytes(url), Buffer.byteLength('\u20ac', 'utf8'));
  });

  it('should count percent-encoded ASCII as one decoded byte', () => {
    const url = 'data:text/plain,hello%20world';
    assert.strictEqual(estimateDataURLDecodedBytes(url), Buffer.byteLength('hello world', 'utf8'));
  });

  it('should calculate decoded length for base64 data URL', () => {
    const str = 'Hello';
    const b64 = Buffer.from(str, 'utf8').toString('base64');
    const url = `data:text/plain;base64,${b64}`;
    assert.strictEqual(estimateDataURLDecodedBytes(url), str.length);
  });

  it('should handle base64 with = padding', () => {
    const url = 'data:text/plain;base64,TQ==';
    assert.strictEqual(estimateDataURLDecodedBytes(url), 1);
  });

  it('should handle base64 with %3D padding', () => {
    const url = 'data:text/plain;base64,TQ%3D%3D';
    assert.strictEqual(estimateDataURLDecodedBytes(url), 1);
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import fromDataURI from '../../lib/helpers/fromDataURI.js';

describe('helpers::fromDataURI', () => {
  it('should return buffer from data uri', () => {
    const buffer = Buffer.from('123');

    const dataURI = 'data:application/octet-stream;base64,' + buffer.toString('base64');

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should parse data URI with no mediatype and base64', () => {
    const buffer = Buffer.from('123');
    const dataURI = 'data:;base64,' + buffer.toString('base64');

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should parse data URI with mediatype and no base64', () => {
    const buffer = Buffer.from('123');
    const dataURI = 'data:application/octet-stream,123';

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should parse full form data URI with text/plain and base64', () => {
    const buffer = Buffer.from('hello');
    const dataURI = 'data:text/plain;base64,' + buffer.toString('base64');

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should parse minimal valid data URI', () => {
    const buffer = Buffer.from('');
    const dataURI = 'data:,';

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should parse data URI with spaces in data', () => {
    const buffer = Buffer.from('hello world');
    const dataURI = 'data:text/plain,hello world';

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should parse canonical RFC example with charset parameter', () => {
    const buffer = Buffer.from('123');
    const dataURI = 'data:text/plain;charset=US-ASCII,123';

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should decode URL-encoded body', () => {
    const buffer = Buffer.from('hello world');
    const dataURI = 'data:text/plain,hello%20world';

    assert.deepStrictEqual(fromDataURI(dataURI, false), buffer);
  });

  it('should preserve full content type with parameters in Blob', () => {
    const dataURI = 'data:text/plain;charset=utf-8;base64,' + Buffer.from('hello').toString('base64');
    const blob = fromDataURI(dataURI, true, { Blob });

    assert.strictEqual(blob.type, 'text/plain;charset=utf-8');
  });

  it('should normalize omitted mediatype to text/plain per RFC 2397', () => {
    const dataURI = 'data:;charset=UTF-8,hello';
    const blob = fromDataURI(dataURI, true, { Blob });

    assert.strictEqual(blob.type, 'text/plain;charset=utf-8');
  });

  it('should reject data URI with unsupported protocol prefix', () => {
    assert.throws(() => {
      fromDataURI('datax:,hi', false);
    }, (err) => err.code === 'ERR_NOT_SUPPORT' && err.message.includes('Unsupported protocol'));
  });

  it('should reject data URI without comma separator', () => {
    assert.throws(() => {
      fromDataURI('data:hi', false);
    }, (err) => err.code === 'ERR_INVALID_URL');
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import composeSignals from '../../lib/helpers/composeSignals.js';

describe('helpers::composeSignals', () => {
  const runIfAbortController = typeof AbortController === 'function' ? it : it.skip;

  runIfAbortController('should abort when any of the signals abort', () => {
    let called;

    const controllerA = new AbortController();
    const controllerB = new AbortController();

    const signal = composeSignals([controllerA.signal, controllerB.signal]);

    signal.addEventListener('abort', () => {
      called = true;
    });

    controllerA.abort(new Error('test'));

    assert.ok(called);
  });

  runIfAbortController('should abort on timeout', async () => {
    const signal = composeSignals([], 100);

    await new Promise((resolve) => {
      signal.addEventListener('abort', resolve);
    });

    assert.match(String(signal.reason), /timeout of 100ms exceeded/);
  });

  it('should return undefined if signals and timeout are not provided', () => {
    const signal = composeSignals([]);

    assert.strictEqual(signal, undefined);
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import axios, { create } from '../../index.js';

describe('static api', () => {
  it('should have request method helpers', () => {
    assert.strictEqual(typeof axios.request, 'function');
    assert.strictEqual(typeof axios.get, 'function');
    assert.strictEqual(typeof axios.head, 'function');
    assert.strictEqual(typeof axios.options, 'function');
    assert.strictEqual(typeof axios.delete, 'function');
    assert.strictEqual(typeof axios.post, 'function');
    assert.strictEqual(typeof axios.put, 'function');
    assert.strictEqual(typeof axios.patch, 'function');
    assert.strictEqual(typeof axios.query, 'function');
  });

  it('should have promise method helpers', async () => {
    const promise = axios.request({
      url: '/test',
      adapter: (config) =>
        Promise.resolve({
          data: null,
          status: 200,
          statusText: 'OK',
          headers: {},
          config,
          request: {},
        }),
    });

    assert.strictEqual(typeof promise.then, 'function');
    assert.strictEqual(typeof promise.catch, 'function');

    await promise;
  });

  it('should have defaults', () => {
    assert.strictEqual(typeof axios.defaults, 'object');
    assert.strictEqual(typeof axios.defaults.headers, 'object');
  });

  it('should have interceptors', () => {
    assert.strictEqual(typeof axios.interceptors.request, 'object');
    assert.strictEqual(typeof axios.interceptors.response, 'object');
  });

  it('should have all/spread helpers', () => {
    assert.strictEqual(typeof axios.all, 'function');
    assert.strictEqual(typeof axios.spread, 'function');
  });

  it('should have factory method', () => {
    assert.strictEqual(typeof axios.create, 'function');
  });

  it('should expose create as a named export', () => {
    assert.strictEqual(typeof create, 'function');
    assert.strictEqual(create, axios.create);
  });

  it('should have CanceledError, CancelToken, and isCancel properties', () => {
    assert.strictEqual(typeof axios.Cancel, 'function');
    assert.strictEqual(typeof axios.CancelToken, 'function');
    assert.strictEqual(typeof axios.isCancel, 'function');
  });

  it('should have getUri method', () => {
    assert.strictEqual(typeof axios.getUri, 'function');
  });

  it('should ignore inherited data for bodyless method helpers', async () => {
    Object.defineProperty(Object.prototype, 'data', {
      value: 'inherited-body',
      configurable: true,
    });

    try {
      await Promise.all(
        ['delete', 'get', 'head', 'options'].map(async (method) => {
          let seenData = 'unset';

          await axios[method]('/test', {
            adapter(config) {
              seenData = config.data;

              return Promise.resolve({
                data: null,
                status: 200,
                statusText: 'OK',
                headers: {},
                config,
                request: {},
              });
            },
          });

          assert.strictEqual(seenData, undefined);
        })
      );
    } finally {
      delete Object.prototype.data;
    }
  });

  it('should ignore inherited nested serializer fields in getUri', () => {
    let serializeInvoked = false;

    Object.defineProperty(Object.prototype, 'serialize', {
      value() {
        serializeInvoked = true;
        return 'inherited=1';
      },
      configurable: true,
    });

    try {
      assert.strictEqual(
        axios.getUri({
          url: '/foo',
          params: { value: 'a b' },
          paramsSerializer: {},
        }),
        '/foo?value=a+b'
      );
      assert.strictEqual(serializeInvoked, false);
    } finally {
      delete Object.prototype.serialize;
    }
  });

  it('should have isAxiosError properties', () => {
    assert.strictEqual(typeof axios.isAxiosError, 'function');
  });

  it('should have mergeConfig properties', () => {
    assert.strictEqual(typeof axios.mergeConfig, 'function');
  });

  it('should have getAdapter properties', () => {
    assert.strictEqual(typeof axios.getAdapter, 'function');
  });

  it('should pass symbol keys to transformRequest', async () => {
    const symbolKey = Symbol('example');
    let transformedData;

    await axios.post(
      '/test',
      {
        [symbolKey]: 'value',
        stringKey: 'value',
      },
      {
        transformRequest(data) {
          transformedData = data;
          return '';
        },
        adapter: (config) =>
          Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          }),
      }
    );

    assert.strictEqual(transformedData[symbolKey], 'value');
  });
});

describe('instance api', () => {
  const instance = axios.create();

  it('should have request methods', () => {
    assert.strictEqual(typeof instance.request, 'function');
    assert.strictEqual(typeof instance.get, 'function');
    assert.strictEqual(typeof instance.options, 'function');
    assert.strictEqual(typeof instance.head, 'function');
    assert.strictEqual(typeof instance.delete, 'function');
    assert.strictEqual(typeof instance.post, 'function');
    assert.strictEqual(typeof instance.put, 'function');
    assert.strictEqual(typeof instance.patch, 'function');
    assert.strictEqual(typeof instance.query, 'function');
  });

  it('should have interceptors', () => {
    assert.strictEqual(typeof instance.interceptors.request, 'object');
    assert.strictEqual(typeof instance.interceptors.response, 'object');
  });

  it('should pass symbol keys to transformRequest through axios.create', async () => {
    const symbolKey = Symbol('example');
    let transformedData;

    const client = axios.create({
      transformRequest: [
        (data) => {
          transformedData = data;
          return '';
        },
      ],
      adapter: (config) =>
        Promise.resolve({
          data: null,
          status: 200,
          statusText: 'OK',
          headers: {},
          config,
          request: {},
        }),
    });

    await client.post('/test', {
      [symbolKey]: 'value',
      stringKey: 'value',
    });

    assert.strictEqual(transformedData[symbolKey], 'value');
    assert.strictEqual(transformedData.stringKey, 'value');
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import Axios from '../../lib/core/Axios.js';

describe('Axios', () => {
  describe('handle un-writable error stack', () => {
    const testUnwritableErrorStack = async (stackAttributes) => {
      const axios = new Axios({});
      // Mock axios._request to return an Error with an un-writable stack property.
      axios._request = () => {
        const mockError = new Error('test-error');
        Object.defineProperty(mockError, 'stack', stackAttributes);
        throw mockError;
      };

      try {
        await axios.request('test-url', {});
      } catch (e) {
        assert.strictEqual(e.message, 'test-error');
      }
    };

    it('should support errors with a defined but un-writable stack', async () => {
      await testUnwritableErrorStack({ value: {}, writable: false });
    });

    it('should support errors with an undefined and un-writable stack', async () => {
      await testUnwritableErrorStack({ value: undefined, writable: false });
    });

    it('should support errors with a custom getter/setter for the stack property', async () => {
      await testUnwritableErrorStack({
        get: () => ({}),
        set: () => {
          throw new Error('read-only');
        },
      });
    });

    it('should support errors with a custom getter/setter for the stack property (null case)', async () => {
      await testUnwritableErrorStack({
        get: () => null,
        set: () => {
          throw new Error('read-only');
        },
      });
    });
  });

  it('should not throw if the config argument is omitted', () => {
    const axios = new Axios();

    assert.deepStrictEqual(axios.defaults, {});
  });
});

/* eslint-disable no-prototype-builtins */
import { afterEach, describe, it } from 'vitest';
import assert from 'assert';
import http from 'http';
import utils from '../../lib/utils.js';
import mergeConfig from '../../lib/core/mergeConfig.js';
import defaults from '../../lib/defaults/index.js';
import AxiosError from '../../lib/core/AxiosError.js';
import AxiosHeaders from '../../lib/core/AxiosHeaders.js';
import resolveConfig from '../../lib/helpers/resolveConfig.js';
import axios from '../../index.js';

describe('Prototype Pollution Protection', () => {
  afterEach(() => {
    // Clean up any pollution that might have occurred.
    delete Object.prototype.polluted;
    delete Object.prototype.parseReviver;
    delete Object.prototype.transport;
    delete Object.prototype.transformRequest;
    delete Object.prototype.transformResponse;
    delete Object.prototype.formSerializer;
    delete Object.prototype.httpVersion;
    delete Object.prototype.lookup;
    delete Object.prototype.family;
    delete Object.prototype.http2Options;
    delete Object.prototype.validateStatus;
    delete Object.prototype.auth;
    delete Object.prototype.baseURL;
    delete Object.prototype.socketPath;
    delete Object.prototype.beforeRedirect;
    delete Object.prototype.sensitiveHeaders;
    delete Object.prototype.insecureHTTPParser;
    delete Object.prototype.adapter;
    delete Object.prototype.httpAgent;
    delete Object.prototype.httpsAgent;
    delete Object.prototype.proxy;
    delete Object.prototype.maxContentLength;
    delete Object.prototype.maxBodyLength;
    delete Object.prototype.maxRedirects;
    delete Object.prototype.maxRate;
    delete Object.prototype.timeout;
    delete Object.prototype.transitional;
    delete Object.prototype.timeoutErrorMessage;
    delete Object.prototype.env;
    delete Object.prototype.cancelToken;
    delete Object.prototype.signal;
    delete Object.prototype.decompress;
    delete Object.prototype.params;
    delete Object.prototype.paramsSerializer;
    delete Object.prototype.method;
    delete Object.prototype.withCredentials;
    delete Object.prototype.responseType;
    delete Object.prototype.fetchOptions;
    delete Object.prototype.username;
    delete Object.prototype.password;
    delete Object.prototype.hostname;
    delete Object.prototype.host;
    delete Object.prototype.port;
    delete Object.prototype.protocol;
    delete Object.prototype.get;
    delete Object.prototype.set;
    delete Object.prototype.headers;
    delete Object.prototype.customNested;
  });

  describe('utils.merge', () => {
    it('should filter __proto__ key at top level', () => {
      const result = utils.merge({}, { __proto__: { polluted: 'yes' }, safe: 'value' });

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.safe, 'value');
      assert.strictEqual(result.hasOwnProperty('__proto__'), false);
    });

    it('should filter constructor key at top level', () => {
      const result = utils.merge({}, { constructor: { polluted: 'yes' }, safe: 'value' });

      assert.strictEqual(result.safe, 'value');
      assert.strictEqual(result.hasOwnProperty('constructor'), false);
    });

    it('should filter prototype key at top level', () => {
      const result = utils.merge({}, { prototype: { polluted: 'yes' }, safe: 'value' });

      assert.strictEqual(result.safe, 'value');
      assert.strictEqual(result.hasOwnProperty('prototype'), false);
    });

    it('should filter __proto__ key in nested objects', () => {
      const result = utils.merge(
        {},
        {
          headers: {
            __proto__: { polluted: 'nested' },
            'Content-Type': 'application/json',
          },
        }
      );

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.headers['Content-Type'], 'application/json');
      assert.strictEqual(result.headers.hasOwnProperty('__proto__'), false);
    });

    it('should filter constructor key in nested objects', () => {
      const result = utils.merge(
        {},
        {
          headers: {
            constructor: { prototype: { polluted: 'nested' } },
            'Content-Type': 'application/json',
          },
        }
      );

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.headers['Content-Type'], 'application/json');
      assert.strictEqual(result.headers.hasOwnProperty('constructor'), false);
    });

    it('should filter prototype key in nested objects', () => {
      const result = utils.merge(
        {},
        {
          headers: {
            prototype: { polluted: 'nested' },
            'Content-Type': 'application/json',
          },
        }
      );

      assert.strictEqual(result.headers['Content-Type'], 'application/json');
      assert.strictEqual(result.headers.hasOwnProperty('prototype'), false);
    });

    it('should filter dangerous keys in deeply nested objects', () => {
      const result = utils.merge(
        {},
        {
          level1: {
            level2: {
              __proto__: { polluted: 'deep' },
              prototype: { polluted: 'deep' },
              safe: 'value',
            },
          },
        }
      );

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.level1.level2.safe, 'value');
      assert.strictEqual(result.level1.level2.hasOwnProperty('__proto__'), false);
    });

    it('should still merge regular properties correctly', () => {
      const result = utils.merge({ a: 1, b: { c: 2 } }, { b: { d: 3 }, e: 4 });

      assert.strictEqual(result.a, 1);
      assert.strictEqual(result.b.c, 2);
      assert.strictEqual(result.b.d, 3);
      assert.strictEqual(result.e, 4);
    });

    it('should handle JSON.parse payloads safely', () => {
      const malicious = JSON.parse('{"__proto__": {"polluted": "yes"}}');
      const result = utils.merge({}, malicious);

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.hasOwnProperty('__proto__'), false);
    });

    it('should handle nested JSON.parse payloads safely', () => {
      const malicious = JSON.parse(
        '{"headers": {"constructor": {"prototype": {"polluted": "yes"}}}}'
      );
      const result = utils.merge({}, malicious);

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.headers.hasOwnProperty('constructor'), false);
    });
  });

  describe('mergeConfig', () => {
    it('should filter dangerous keys at top level', () => {
      const result = mergeConfig(
        {},
        {
          __proto__: { polluted: 'yes' },
          constructor: { polluted: 'yes' },
          prototype: { polluted: 'yes' },
          url: '/api/test',
        }
      );

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.url, '/api/test');
      assert.strictEqual(result.hasOwnProperty('__proto__'), false);
      assert.strictEqual(result.hasOwnProperty('constructor'), false);
      assert.strictEqual(result.hasOwnProperty('prototype'), false);
    });

    it('should filter dangerous keys in headers', () => {
      const result = mergeConfig(
        {},
        {
          headers: {
            __proto__: { polluted: 'yes' },
            'Content-Type': 'application/json',
          },
        }
      );

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.headers['Content-Type'], 'application/json');
      assert.strictEqual(result.headers.hasOwnProperty('__proto__'), false);
    });

    it('should filter dangerous keys in custom config properties', () => {
      const result = mergeConfig(
        {},
        {
          customProp: {
            __proto__: { polluted: 'yes' },
            safe: 'value',
          },
        }
      );

      assert.strictEqual(Object.prototype.polluted, undefined);
      assert.strictEqual(result.customProp.safe, 'value');
      assert.strictEqual(result.customProp.hasOwnProperty('__proto__'), false);
    });

    it('should still merge configs correctly', () => {
      const config1 = {
        baseURL: 'https://api.example.com',
        timeout: 1000,
        headers: {
          common: {
            Accept: 'application/json',
          },
        },
      };

      const config2 = {
        url: '/users',
        timeout: 5000,
        headers: {
          common: {
            'Content-Type': 'application/json',
          },
        },
      };

      const result = mergeConfig(config1, config2);

      assert.strictEqual(result.baseURL, 'https://api.example.com');
      assert.strictEqual(result.url, '/users');
      assert.strictEqual(result.timeout, 5000);
      assert.strictEqual(result.headers.common.Accept, 'application/json');
      assert.strictEqual(result.headers.common['Content-Type'], 'application/json');
    });

    // Polluted transformRequest/Response must not
    // replace the safe defaults through inherited reads during merge.
    it('should not inherit polluted transformRequest from Object.prototype', () => {
      const polluted = () => 'attacker';
      Object.prototype.transformRequest = polluted;

      const result = mergeConfig({ transformRequest: [(d) => d] }, { url: '/x' });

      assert.notStrictEqual(result.transformRequest, polluted);
      assert.ok(Array.isArray(result.transformRequest));
    });

    it('should not inherit polluted transformResponse from Object.prototype', () => {
      const polluted = () => 'attacker';
      Object.prototype.transformResponse = polluted;

      const result = mergeConfig({ transformResponse: [(d) => d] }, { url: '/x' });

      assert.notStrictEqual(result.transformResponse, polluted);
      assert.ok(Array.isArray(result.transformResponse));
    });
  });

  // parseReviver read via prototype chain.
  describe('defaults.transformResponse parseReviver', () => {
    it('should ignore Object.prototype.parseReviver when parsing JSON', () => {
      let reviverCalled = false;
      Object.prototype.parseReviver = function polluted(k, v) {
        reviverCalled = true;
        if (k === 'role') return 'admin';
        return v;
      };

      const ctx = { transitional: defaults.transitional };
      const result = defaults.transformResponse[0].call(ctx, '{"role":"user","balance":100}');

      assert.strictEqual(reviverCalled, false);
      assert.strictEqual(result.role, 'user');
      assert.strictEqual(result.balance, 100);
    });

    it('should ignore Object.prototype.responseType', () => {
      Object.prototype.responseType = 'json';
      const ctx = { transitional: defaults.transitional };
      // Non-JSON string body must be returned as-is; polluted responseType must
      // not force strict JSON parsing.
      const result = defaults.transformResponse[0].call(ctx, 'plain text');
      assert.strictEqual(result, 'plain text');
      delete Object.prototype.responseType;
    });
  });

  // mergeDirectKeys must not inherit validateStatus from
  // Object.prototype (was using the `in` operator which traverses the chain).
  describe('validateStatus merge', () => {
    it('should not inherit a polluted validateStatus during mergeConfig', () => {
      Object.prototype.validateStatus = () => true;

      const merged = mergeConfig(defaults, { url: '/x' });

      assert.strictEqual(merged.validateStatus, defaults.validateStatus);
    });

    it('should keep 4xx/5xx responses rejected when Object.prototype.validateStatus is polluted', async () => {
      Object.prototype.validateStatus = () => true;

      const server = http.createServer((req, res) => {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end('{"error":"unauthorized"}');
      });

      await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
      const { port } = server.address();

      try {
        let threw = false;
        try {
          await axios.get(`http://127.0.0.1:${port}/`);
        } catch (err) {
          threw = true;
          assert.strictEqual(err.response.status, 401);
        }
        assert.strictEqual(threw, true);
      } finally {
        await new Promise((resolve) => server.close(resolve));
      }
    }, 10000);
  });

  // end-to-end check that a polluted parseReviver does not
  // tamper with JSON response bodies through the full axios.get pipeline.
  describe('parseReviver end-to-end', () => {
    it('should not let Object.prototype.parseReviver tamper with JSON responses', async () => {
      let reviverCalled = false;
      const stolen = {};
      Object.prototype.parseReviver = function polluted(key, value) {
        reviverCalled = true;
        if (key && typeof value !== 'object') stolen[key] = value;
        if (key === 'isAdmin') return true;
        if (key === 'role') return 'admin';
        if (key === 'balance') return 999999;
        return value;
      };

      const payload = {
        user: 'john',
        role: 'viewer',
        isAdmin: false,
        balance: 100,
        apiKey: 'sk-secret-internal-key',
      };

      const server = http.createServer((req, res) => {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(payload));
      });

      await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
      const { port } = server.address();

      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);

        assert.strictEqual(reviverCalled, false);
        assert.deepStrictEqual(res.data, payload);
        assert.deepStrictEqual(stolen, {});
      } finally {
        await new Promise((resolve) => server.close(resolve));
      }
    }, 10000);
  });

  // http adapter must not read config.transport
  // (or related keys) from Object.prototype.
  describe('http adapter prototype reads', () => {
    it('should not invoke Object.prototype.transport on a request', async () => {
      let hijackCalled = false;
      Object.prototype.transport = {
        request(options, handleResponse) {
          hijackCalled = true;
          return http.request(options, handleResponse);
        },
      };

      const server = http.createServer((req, res) => {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"ok":true}');
      });

      await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
      const { port } = server.address();

      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.data.ok, true);
        assert.strictEqual(hijackCalled, false);
      } finally {
        await new Promise((resolve) => server.close(resolve));
      }
    }, 10000);
  });

  // Five config properties were read via direct property
  // access in the http adapter and resolveConfig, bypassing hasOwnProperty and
  // allowing prototype pollution gadgets (auth, baseURL, socketPath,
  // beforeRedirect, insecureHTTPParser).
  describe('http adapter gadgets', () => {
    function startServer(handler) {
      return new Promise((resolve) => {
        const server = http.createServer(
          handler ||
            ((req, res) => {
              res.writeHead(200, { 'Content-Type': 'application/json' });
              res.end(JSON.stringify({ headers: req.headers, url: req.url }));
            })
        );
        server.listen(0, '127.0.0.1', () => resolve(server));
      });
    }

    function stopServer(server) {
      return new Promise((resolve) => server.close(resolve));
    }

    it('should not pick up Object.prototype.auth as an Authorization header', async () => {
      Object.prototype.auth = { username: 'attacker', password: 'exfil' };

      const server = await startServer();
      const { port } = server.address();

      try {
        const res = await axios.get(`http://127.0.0.1:${port}/api`);
        assert.strictEqual(res.data.headers.authorization, undefined);
      } finally {
        await stopServer(server);
      }
    }, 10000);

    it('should not pick up Object.prototype.socketPath and redirect the request', async () => {
      Object.prototype.socketPath = '/tmp/axios-should-never-be-used.sock';

      const server = await startServer();
      const { port } = server.address();

      try {
        const res = await axios.get(`http://127.0.0.1:${port}/api`);
        assert.strictEqual(res.status, 200);
        assert.strictEqual(res.data.url, '/api');
      } finally {
        await stopServer(server);
      }
    }, 10000);

    it('should not invoke Object.prototype.beforeRedirect during redirects', async () => {
      let hijackCalled = false;
      Object.prototype.beforeRedirect = function polluted() {
        hijackCalled = true;
      };

      const target = await startServer();
      const { port: targetPort } = target.address();

      const redirector = await startServer((req, res) => {
        res.writeHead(302, { Location: `http://127.0.0.1:${targetPort}/final` });
        res.end();
      });
      const { port: redirectorPort } = redirector.address();

      try {
        const res = await axios.get(`http://127.0.0.1:${redirectorPort}/start`);
        assert.strictEqual(res.status, 200);
        assert.strictEqual(hijackCalled, false);
      } finally {
        await stopServer(redirector);
        await stopServer(target);
      }
    }, 10000);

    it('should not pick up Object.prototype.sensitiveHeaders during redirects', async () => {
      Object.prototype.sensitiveHeaders = ['X-Secret'];
      let capturedHeaders;

      const target = await startServer((req, res) => {
        capturedHeaders = req.headers;
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"ok":true}');
      });
      const { port: targetPort } = target.address();

      const redirector = await startServer((req, res) => {
        res.writeHead(302, { Location: `http://127.0.0.1:${targetPort}/final` });
        res.end();
      });
      const { port: redirectorPort } = redirector.address();

      try {
        await axios.get(`http://127.0.0.1:${redirectorPort}/start`, {
          headers: { 'X-Secret': 'keep' },
        });
        assert.strictEqual(capturedHeaders['x-secret'], 'keep');
      } finally {
        await stopServer(redirector);
        await stopServer(target);
      }
    }, 10000);

    it('should not enable insecureHTTPParser via Object.prototype', async () => {
      // A raw TCP server emits a response that uses LF-only line terminators
      // instead of CRLF. Node's strict HTTP parser rejects this payload with
      // HPE_CR_EXPECTED; the insecure parser accepts it. Verified: with an
      // explicit `insecureHTTPParser: true` on the request config, this
      // payload is parsed successfully — so if Object.prototype.insecureHTTPParser
      // were picked up, the request would succeed. The request must fail when
      // the gadget is properly blocked.
      Object.prototype.insecureHTTPParser = true;

      const net = await import('net');
      const malformedPayload =
        'HTTP/1.1 200 OK\n' +
        'Content-Type: application/json\n' +
        'Content-Length: 2\n' +
        '\n' +
        '{}';
      const malformed = await new Promise((resolve) => {
        const srv = net.createServer((socket) => {
          socket.once('data', () => socket.end(malformedPayload));
        });
        srv.listen(0, '127.0.0.1', () => resolve(srv));
      });
      const { port } = malformed.address();

      try {
        let threw = false;
        let caughtCode = '';
        try {
          await axios.get(`http://127.0.0.1:${port}/`, {
            transitional: { clarifyTimeoutError: false },
          });
        } catch (err) {
          threw = true;
          caughtCode = String(err && (err.code || err.message));
        }
        assert.strictEqual(
          threw,
          true,
          `request should be rejected by the strict HTTP parser (got: ${caughtCode || 'success'})`
        );
        // The exact llhttp code for LF-only line terminators varies across
        // Node versions (historically HPE_LF_EXPECTED, more recently
        // HPE_CR_EXPECTED). Match any parser error to remain stable across
        // Node releases while still confirming the strict parser rejected
        // the payload.
        assert.match(caughtCode, /^HPE_/, `expected an HPE_* parser error, got: ${caughtCode}`);
      } finally {
        await new Promise((resolve) => malformed.close(resolve));
      }
    }, 10000);

    it('should not inject Proxy-Authorization from polluted Object.prototype.auth', async () => {
      // setProxy reads `proxy.auth` directly. When `proxy` is a
      // URL instance from the environment proxy or a plain object without an own `auth`,
      // a polluted Object.prototype.auth would otherwise be base64-encoded into the
      // Proxy-Authorization header, leaking attacker-controlled credentials.
      Object.prototype.auth = { username: 'attacker', password: 'exfil' };

      const proxy = await startServer();
      const { port: proxyPort } = proxy.address();

      const target = await startServer();
      const { port: targetPort } = target.address();

      try {
        const res = await axios.get(`http://127.0.0.1:${targetPort}/api`, {
          proxy: { host: '127.0.0.1', port: proxyPort, protocol: 'http' },
        });
        assert.strictEqual(res.status, 200);
        assert.strictEqual(
          res.data.headers['proxy-authorization'],
          undefined,
          'polluted Object.prototype.auth must not produce a Proxy-Authorization header'
        );
      } finally {
        await stopServer(target);
        await stopServer(proxy);
      }
    }, 10000);

    it('should not inject Proxy-Authorization from polluted Object.prototype.username', async () => {
      // The setProxy username/password branch builds basic creds from `proxy.username`
      // and `proxy.password`. For a plain object proxy, both reads must be guarded
      // against prototype pollution.
      Object.prototype.username = 'attacker';
      Object.prototype.password = 'exfil';

      const proxy = await startServer();
      const { port: proxyPort } = proxy.address();

      const target = await startServer();
      const { port: targetPort } = target.address();

      try {
        const res = await axios.get(`http://127.0.0.1:${targetPort}/api`, {
          proxy: { host: '127.0.0.1', port: proxyPort, protocol: 'http' },
        });
        assert.strictEqual(res.status, 200);
        assert.strictEqual(
          res.data.headers['proxy-authorization'],
          undefined,
          'polluted Object.prototype.username must not produce a Proxy-Authorization header'
        );
      } finally {
        await stopServer(target);
        await stopServer(proxy);
      }
    }, 10000);
  });

  describe('resolveConfig baseURL gadget', () => {
    // The baseURL branch in buildFullPath only runs when the requested URL is
    // relative (or allowAbsoluteUrls === false). An absolute URL would skip
    // baseURL regardless of pollution and would not exercise the gadget. We
    // therefore issue a relative GET and assert that either:
    //   - the request fails (no host to resolve) because baseURL is correctly
    //     absent from the merged config, OR
    //   - the request is fulfilled without hitting the hijacker.
    // Critically, hijackHit must always be false.
    it('should not hijack relative-URL requests via Object.prototype.baseURL', async () => {
      let hijackHit = false;
      const hijacker = http.createServer((req, res) => {
        hijackHit = true;
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"hijacked":true}');
      });
      await new Promise((resolve) => hijacker.listen(0, '127.0.0.1', resolve));
      const { port: hijackerPort } = hijacker.address();

      Object.prototype.baseURL = `http://127.0.0.1:${hijackerPort}`;

      try {
        let threw = false;
        try {
          await axios.get('/api');
        } catch (_err) {
          threw = true;
        }
        // Either the request fails (desired — no baseURL means no host) or it
        // resolves, but it must NOT hit the polluted hijacker.
        assert.strictEqual(hijackHit, false);
        assert.strictEqual(threw, true);
      } finally {
        await new Promise((resolve) => hijacker.close(resolve));
      }
    }, 10000);

    // Second variant using allowAbsoluteUrls: false to force the baseURL path
    // even for a fully-qualified requested URL.
    it('should not hijack requests via Object.prototype.baseURL with allowAbsoluteUrls:false', async () => {
      let hijackHit = false;
      const hijacker = http.createServer((req, res) => {
        hijackHit = true;
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"hijacked":true}');
      });
      await new Promise((resolve) => hijacker.listen(0, '127.0.0.1', resolve));
      const { port: hijackerPort } = hijacker.address();

      const target = http.createServer((req, res) => {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"ok":true}');
      });
      await new Promise((resolve) => target.listen(0, '127.0.0.1', resolve));
      const { port: targetPort } = target.address();

      Object.prototype.baseURL = `http://127.0.0.1:${hijackerPort}`;

      try {
        // If the gadget were picked up, combineURLs(hijacker, `http://target`)
        // would route to the hijacker. It must not.
        let threw = false;
        try {
          await axios.get(`http://127.0.0.1:${targetPort}/api`, {
            allowAbsoluteUrls: false,
          });
        } catch (_err) {
          threw = true;
        }
        assert.strictEqual(hijackHit, false);
        // allowAbsoluteUrls:false + no baseURL → combineURLs not invoked
        // (baseURL falsy) → returns requested URL as-is → target receives it.
        // If baseURL were inherited from prototype, it would be truthy and
        // combineURLs would be invoked, routing to the hijacker.
        assert.strictEqual(threw, false);
      } finally {
        await new Promise((resolve) => hijacker.close(resolve));
        await new Promise((resolve) => target.close(resolve));
      }
    }, 10000);
  });

  describe('resolveConfig params and paramsSerializer gadget', () => {
    it('should not inherit polluted params via resolveConfig', () => {
      Object.prototype.params = { injected: 'yes' };

      try {
        const resolved = resolveConfig({ url: '/api', method: 'get' });

        assert.ok(resolved.url.indexOf('injected') === -1, 'polluted params must not appear in URL');
        assert.strictEqual(resolved.url, '/api', 'URL must remain unchanged');
      } finally {
        delete Object.prototype.params;
      }
    });

    it('should not invoke polluted paramsSerializer via resolveConfig', () => {
      let serializerInvoked = false;
      Object.prototype.paramsSerializer = function polluted() {
        serializerInvoked = true;
        return 'injected=yes';
      };

      try {
        const resolved = resolveConfig({ url: '/api', method: 'get', params: { legit: 'true' } });

        assert.strictEqual(serializerInvoked, false, 'polluted paramsSerializer must not be called');
        // The URL should have legit param serialized normally
        assert.ok(resolved.url.indexOf('legit=true') !== -1, 'legitimate params must still be serialized');
      } finally {
        delete Object.prototype.paramsSerializer;
      }
    });
  });

  // Structural defense: mergeConfig returns a null-prototype object, so any
  // property read that is not an own property of config cannot inherit from
  // Object.prototype. Adding a new key to Object.prototype must never appear
  // as a property of the merged config.
  describe('mergeConfig null-prototype structural defense', () => {
    it('should return an object whose prototype is null', () => {
      const merged = mergeConfig({ url: '/x' }, { method: 'get' });
      assert.strictEqual(Object.getPrototypeOf(merged), null);
    });

    it('should preserve hasOwnProperty as a callable own slot', () => {
      const merged = mergeConfig({}, { url: '/x', method: 'get' });
      assert.strictEqual(typeof merged.hasOwnProperty, 'function');
      assert.strictEqual(merged.hasOwnProperty('url'), true);
      assert.strictEqual(merged.hasOwnProperty('method'), true);
      assert.strictEqual(merged.hasOwnProperty('bogus'), false);
    });

    it('should not serialize hasOwnProperty slot via Object.keys', () => {
      const merged = mergeConfig({ url: '/x' }, {});
      assert.ok(!Object.keys(merged).includes('hasOwnProperty'));
    });

    it('should not expose arbitrary polluted keys as inherited properties', () => {
      Object.prototype.polluted = 'attacker';
      try {
        const merged = mergeConfig({ url: '/x' }, {});
        assert.strictEqual(merged.polluted, undefined);
      } finally {
        delete Object.prototype.polluted;
      }
    });
  });

  // Verify every gadget enumerated in the audit
  // is neutralized end-to-end by the null-prototype config.
  describe('Full gadget coverage via null-prototype config', () => {
    function startEcho(handler) {
      return new Promise((resolve) => {
        const server = http.createServer(
          handler ||
            ((req, res) => {
              let body = '';
              req.on('data', (c) => (body += c));
              req.on('end', () => {
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(
                  JSON.stringify({
                    url: req.url,
                    method: req.method,
                    headers: req.headers,
                    body,
                  })
                );
              });
            })
        );
        server.listen(0, '127.0.0.1', () => resolve(server));
      });
    }
    const stop = (s) => new Promise((r) => s.close(r));

    it('should ignore polluted transformRequest', async () => {
      let invoked = false;
      Object.prototype.transformRequest = function polluted(data) {
        invoked = true;
        return 'INJECTED';
      };

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.post(`http://127.0.0.1:${port}/`, { hello: 'world' });
        assert.strictEqual(invoked, false);
        assert.notStrictEqual(res.data.body, 'INJECTED');
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted transformResponse', async () => {
      let invoked = false;
      Object.prototype.transformResponse = function polluted() {
        invoked = true;
        return 'HIJACKED';
      };

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(invoked, false);
        assert.notStrictEqual(res.data, 'HIJACKED');
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted adapter', async () => {
      let hijacked = false;
      Object.prototype.adapter = function pollutedAdapter() {
        hijacked = true;
        return Promise.resolve({
          data: 'pwned',
          status: 200,
          statusText: 'OK',
          headers: {},
          config: {},
          request: {},
        });
      };

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/ok`);
        assert.strictEqual(hijacked, false);
        assert.notStrictEqual(res.data, 'pwned');
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted httpAgent', async () => {
      let agentUsed = false;
      Object.prototype.httpAgent = new http.Agent({
        keepAlive: false,
      });
      // Wrap createConnection to detect usage
      const origCreate = Object.prototype.httpAgent.createConnection;
      Object.prototype.httpAgent.createConnection = function (...args) {
        agentUsed = true;
        return origCreate.apply(this, args);
      };

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.status, 200);
        assert.strictEqual(agentUsed, false);
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted proxy', async () => {
      Object.prototype.proxy = {
        protocol: 'http',
        host: '127.0.0.1',
        port: 1, // would fail if actually used
      };

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.status, 200);
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted maxContentLength', async () => {
      // Polluted tiny limit would reject a normal response if applied.
      Object.prototype.maxContentLength = 1;

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.status, 200);
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted maxRedirects', async () => {
      // Pollute with 0 — if picked up, follow-redirects path would be skipped.
      // We make sure regular requests still succeed via the expected path.
      Object.prototype.maxRedirects = 0;

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.status, 200);
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted timeout at the merged config level', () => {
      Object.prototype.timeout = 1;
      const merged = mergeConfig({}, { url: '/x' });
      assert.strictEqual(Object.prototype.hasOwnProperty.call(merged, 'timeout'), false);
      assert.strictEqual(merged.timeout, undefined);
    });

    it('should ignore polluted timeoutErrorMessage', async () => {
      Object.prototype.timeoutErrorMessage = 'INJECTED_TIMEOUT';
      // Not easy to assert without triggering a real timeout; just confirm
      // normal requests still succeed and do not read the polluted key.
      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.status, 200);
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted transitional', async () => {
      Object.prototype.transitional = { forcedJSONParsing: true, silentJSONParsing: false };
      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.status, 200);
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted params and paramsSerializer', async () => {
      let serializerInvoked = false;
      Object.prototype.params = { injected: 'yes' };
      Object.prototype.paramsSerializer = function polluted() {
        serializerInvoked = true;
        return 'injected=yes';
      };

      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/x`);
        assert.strictEqual(serializerInvoked, false);
        assert.strictEqual(res.data.url, '/x');
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted method', async () => {
      Object.prototype.method = 'DELETE';
      const server = await startEcho();
      const { port } = server.address();
      try {
        // axios.get should still send GET, not DELETE.
        const res = await axios.get(`http://127.0.0.1:${port}/ok`);
        assert.strictEqual(res.data.method, 'GET');
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted decompress', async () => {
      Object.prototype.decompress = false;
      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        assert.strictEqual(res.status, 200);
      } finally {
        await stop(server);
      }
    }, 10000);

    it('should ignore polluted responseType', async () => {
      Object.prototype.responseType = 'arraybuffer';
      const server = await startEcho();
      const { port } = server.address();
      try {
        const res = await axios.get(`http://127.0.0.1:${port}/`);
        // When responseType is not set on config, json parsing should apply
        // and res.data should be an object, not an ArrayBuffer/Buffer.
        assert.strictEqual(typeof res.data, 'object');
        assert.ok(!Buffer.isBuffer(res.data));
      } finally {
        await stop(server);
      }
    }, 10000);
  });

  // utils.merge previously read `result[targetKey]` directly, which walks the
  // prototype chain. A polluted Object.prototype.<key> object would surface as
  // the existing value and be merged into the result.
  describe('utils.merge prototype-chain read', () => {
    it('should not pick up polluted Object.prototype.<key> as the existing value', () => {
      Object.prototype.headers = { evil: 'yes' };

      const result = utils.merge({}, { headers: { 'Content-Type': 'application/json' } });

      assert.strictEqual(result.headers.evil, undefined);
      assert.strictEqual(result.headers['Content-Type'], 'application/json');
    });

    it('should not absorb polluted nested objects when the key is absent from inputs', () => {
      // When the source does not carry `customNested`, the merged result should
      // not surface it either, even if Object.prototype carries it.
      Object.prototype.customNested = { evil: 'yes' };

      const result = utils.merge({}, { safe: 'value' });

      assert.strictEqual(result.hasOwnProperty('customNested'), false);
      assert.strictEqual(result.safe, 'value');
    });
  });

  // Object.defineProperty calls a HasProperty check on `get`/`set` of the
  // descriptor. A polluted Object.prototype.get with a non-function value would
  // throw TypeError at every defineProperty site that uses a plain literal
  // descriptor. Each fixed site should be shielded with `__proto__: null`.
  describe('Object.defineProperty descriptor literals', () => {
    it('should construct AxiosError when Object.prototype.get is polluted', () => {
      Object.prototype.get = 'attacker';

      const err = new AxiosError('hello', 'ECODE');

      assert.strictEqual(err.message, 'hello');
      assert.strictEqual(err.code, 'ECODE');
    });

    it('should construct AxiosHeaders accessor methods when Object.prototype.get is polluted', () => {
      Object.prototype.get = 'attacker';

      // AxiosHeaders.accessor uses Object.defineProperty on the prototype.
      // Triggering a fresh accessor definition exercises the descriptor literal.
      AxiosHeaders.accessor('X-Pp-Test');

      const h = new AxiosHeaders();
      h.setXPpTest('value');
      assert.strictEqual(h.getXPpTest(), 'value');
    });

    it('should not throw in mergeConfig when Object.prototype.get is polluted', () => {
      Object.prototype.get = 'attacker';

      const result = mergeConfig({}, { url: '/x', method: 'get' });

      assert.strictEqual(result.url, '/x');
      assert.strictEqual(result.method, 'get');
      assert.strictEqual(typeof result.hasOwnProperty, 'function');
    });

    it('should not throw in utils.extend when Object.prototype.get is polluted', () => {
      Object.prototype.get = 'attacker';

      const a = {};
      const b = { x: 1, fn() {} };
      utils.extend(a, b);

      assert.strictEqual(a.x, 1);
      assert.strictEqual(typeof a.fn, 'function');
    });

    it('should not throw in utils.extend with thisArg when Object.prototype.get is polluted', () => {
      Object.prototype.get = 'attacker';

      const a = {};
      const ctx = { tag: 'ctx' };
      const b = {
        method() {
          return this.tag;
        },
      };
      utils.extend(a, b, ctx);

      assert.strictEqual(a.method(), 'ctx');
    });

    it('should not throw in utils.inherits when Object.prototype.get is polluted', () => {
      Object.prototype.get = 'attacker';

      function Parent() {}
      function Child() {}
      utils.inherits(Child, Parent);

      assert.strictEqual(Child.prototype.constructor, Child);
      assert.strictEqual(Child.super, Parent.prototype);
    });

    it('should also be shielded against a polluted Object.prototype.set', () => {
      Object.prototype.set = 'attacker';

      // Same surface as `get` — ToPropertyDescriptor checks both. One spot-check
      // covers them all since they share the same fix.
      const err = new AxiosError('hello');
      assert.strictEqual(err.message, 'hello');
    });
  });

  // End-to-end regressions covering published advisory PoCs against full axios
  // request flow. Each test mirrors the exploit scenario from the advisory and
  // asserts the attack does not succeed.
  describe('advisory regression — full request flow', () => {
    function startServer(handler) {
      return new Promise((resolve) => {
        const server = http.createServer(handler);
        server.listen(0, '127.0.0.1', () => resolve(server));
      });
    }
    const stop = (s) => new Promise((r) => s.close(r));

    // Full MITM via prototype pollution gadget in
    // `config.proxy`. mergeConfig must not surface a polluted Object.prototype.proxy
    // as the merged config's proxy, otherwise every request would route through
    // an attacker-controlled host.
    it('polluted Object.prototype.proxy must not redirect requests through an attacker proxy', async () => {
      const proxyHits = [];
      const attackerProxy = await startServer((req, res) => {
        proxyHits.push({
          url: req.url,
          authorization: req.headers.authorization,
          host: req.headers.host,
        });
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"hijacked":true}');
      });

      const realHits = [];
      const realServer = await startServer((req, res) => {
        realHits.push({ url: req.url });
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"data":"real"}');
      });

      try {
        Object.prototype.proxy = {
          protocol: 'http',
          host: '127.0.0.1',
          port: attackerProxy.address().port,
        };

        const realPort = realServer.address().port;
        const res = await axios.get(`http://127.0.0.1:${realPort}/api/secrets`, {
          auth: { username: 'admin', password: 'SuperSecret123!' },
        });

        assert.strictEqual(proxyHits.length, 0, 'attacker proxy must not receive any request');
        assert.strictEqual(realHits.length, 1, 'request must reach the real target');
        assert.deepStrictEqual(res.data, { data: 'real' });
      } finally {
        await stop(attackerProxy);
        await stop(realServer);
      }
    }, 10000);

    // Credential theft and response hijacking via
    // prototype pollution gadget in config merge. A polluted
    // Object.prototype.transformResponse function would otherwise execute with
    // `this = config`, exposing `auth.username`/`auth.password` to the attacker.
    it('polluted Object.prototype.transformResponse must not be invoked or leak request credentials', async () => {
      let invoked = false;
      let stolen = null;
      Object.prototype.transformResponse = function pollutedTransform(data) {
        invoked = true;
        stolen = {
          url: this && this.url,
          username: this && this.auth && this.auth.username,
          password: this && this.auth && this.auth.password,
          data,
        };
        return true;
      };

      const server = await startServer((req, res) => {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"secret":"keep-me"}');
      });

      try {
        const { port } = server.address();
        const res = await axios.get(`http://127.0.0.1:${port}/users`, {
          auth: { username: 'svc-account', password: 'prod-secret-key-123!' },
        });

        assert.strictEqual(invoked, false, 'polluted transformResponse must not run');
        assert.strictEqual(stolen, null, 'no request context must be captured');
        assert.deepStrictEqual(
          res.data,
          { secret: 'keep-me' },
          'response data must reach the caller untampered'
        );
      } finally {
        await stop(server);
      }
    }, 10000);
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import utils from '../../lib/utils.js';
import parseProtocol from '../../lib/helpers/parseProtocol.js';

describe('helpers::parseProtocol', () => {
  it('should parse protocol part if it exists', () => {
    utils.forEach(
      {
        'http://username:password@example.com/': 'http',
        'ftp:google.com': 'ftp',
        'sms:+15105550101?body=hello%20there': 'sms',
        'tel:0123456789': 'tel',
        '//google.com': '',
        'google.com': '',
        'admin://etc/default/grub': 'admin',
        'stratum+tcp://server:port': 'stratum+tcp',
        '/api/resource:customVerb': '',
        'https://stackoverflow.com/questions/': 'https',
        'mailto:jsmith@example.com': 'mailto',
        'chrome-extension://1234/<pageName>.html': 'chrome-extension',
      },
      (expectedProtocol, url) => {
        assert.strictEqual(parseProtocol(url), expectedProtocol);
      }
    );
  });

  it('should not match URLs without a colon separator', () => {
    assert.strictEqual(parseProtocol('http//example.com'), '');
  });
});

import { describe, it } from 'vitest';
import defaults from '../../lib/defaults/index.js';
import transformData from '../../lib/core/transformData.js';
import AxiosError from '../../lib/core/AxiosError.js';
import assert from 'assert';

describe('transformResponse', () => {
  describe('200 request', () => {
    it('parses json', () => {
      const data = '{"message": "hello, world"}';
      const result = transformData.call(
        {
          data,
          response: {
            headers: { 'content-type': 'application/json' },
            status: 200,
          },
        },
        defaults.transformResponse
      );
      assert.strictEqual(result.message, 'hello, world');
    });

    it('ignores XML', () => {
      const data = '<message>hello, world</message>';
      const result = transformData.call(
        {
          data,
          response: {
            headers: { 'content-type': 'text/xml' },
            status: 200,
          },
        },
        defaults.transformResponse
      );
      assert.strictEqual(result, data);
    });
  });

  describe('malformed JSON with responseType: json', () => {
    it('throws AxiosError with ERR_BAD_RESPONSE code', () => {
      const response = { status: 200, headers: {}, data: '{bad json' };
      const config = {
        responseType: 'json',
        transitional: { silentJSONParsing: false, forcedJSONParsing: true },
        response,
      };

      assert.throws(
        () => transformData.call(config, defaults.transformResponse, response),
        (e) => e instanceof AxiosError && e.code === AxiosError.ERR_BAD_RESPONSE
      );
    });

    it('attaches response to AxiosError so error.status and error.response are available', () => {
      // Regression test for https://github.com/axios/axios/issues/7224
      // When JSON.parse fails in strict mode, the thrown AxiosError must carry
      // the original response so callers can inspect error.status and
      // error.response without having to re-examine the raw response.
      const response = { status: 200, headers: {}, data: '{bad json' };
      const config = {
        responseType: 'json',
        transitional: { silentJSONParsing: false, forcedJSONParsing: true },
        response,
      };

      let thrown;
      try {
        transformData.call(config, defaults.transformResponse, response);
      } catch (e) {
        thrown = e;
      }

      assert.ok(thrown instanceof AxiosError, 'must be AxiosError');
      assert.strictEqual(thrown.status, 200, 'error.status must equal response status');
      assert.strictEqual(thrown.response, response, 'error.response must be the original response');
    });
  });

  describe('204 request', () => {
    it('does not parse the empty string', () => {
      const data = '';
      const result = transformData.call(
        {
          data,
          response: {
            headers: { 'content-type': undefined },
            status: 204,
          },
        },
        defaults.transformResponse
      );
      assert.strictEqual(result, '');
    });

    it('does not parse undefined', () => {
      const data = undefined;
      const result = transformData.call(
        {
          data,
          response: {
            headers: { 'content-type': undefined },
            status: 200,
          },
        },
        defaults.transformResponse
      );
      assert.strictEqual(result, data);
    });
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import AxiosHeaders from '../../lib/core/AxiosHeaders.js';

const [nodeMajorVersion] = process.versions.node.split('.').map((v) => parseInt(v, 10));

describe('AxiosHeaders', () => {
  it('should support headers argument', () => {
    const headers = new AxiosHeaders({
      x: 1,
      y: 2,
    });

    assert.strictEqual(headers.get('x'), '1');
    assert.strictEqual(headers.get('y'), '2');
  });

  describe('set', () => {
    it('should support adding a single header', () => {
      const headers = new AxiosHeaders();

      headers.set('foo', 'bar');

      assert.strictEqual(headers.get('foo'), 'bar');
    });

    it('should support adding multiple headers', () => {
      const headers = new AxiosHeaders();

      headers.set({
        foo: 'value1',
        bar: 'value2',
      });

      assert.strictEqual(headers.get('foo'), 'value1');
      assert.strictEqual(headers.get('bar'), 'value2');
    });

    it('should support adding multiple headers from raw headers string', () => {
      const headers = new AxiosHeaders();

      headers.set(`foo:value1\nbar:value2`);

      assert.strictEqual(headers.get('foo'), 'value1');
      assert.strictEqual(headers.get('bar'), 'value2');
    });

    it('should not rewrite header the header if the value is false', () => {
      const headers = new AxiosHeaders();

      headers.set('foo', 'value1');

      headers.set('foo', 'value2', false);

      assert.strictEqual(headers.get('foo'), 'value1');

      headers.set('foo', 'value2');

      assert.strictEqual(headers.get('foo'), 'value2');

      headers.set('foo', 'value3', true);

      assert.strictEqual(headers.get('foo'), 'value3');
    });

    it('should not rewrite the header if its value is false, unless rewrite options is set to true', () => {
      const headers = new AxiosHeaders();

      headers.set('foo', false);
      headers.set('foo', 'value2');

      assert.strictEqual(headers.get('foo'), false);

      headers.set('foo', 'value2', true);

      assert.strictEqual(headers.get('foo'), 'value2');
    });

    it('should support iterables as a key-value source object', () => {
      const headers = new AxiosHeaders();

      headers.set(new Map([['x', '123']]));

      assert.strictEqual(headers.get('x'), '123');
    });

    it('should not merge Object.prototype values into iterable headers', () => {
      const descriptor = Object.getOwnPropertyDescriptor(Object.prototype, 'Authorization');
      Object.prototype.Authorization = 'polluted';

      try {
        const headers = new AxiosHeaders(new Map([['Authorization', 'real']]));

        assert.strictEqual(headers.get('authorization'), 'real');
      } finally {
        descriptor
          ? Object.defineProperty(Object.prototype, 'Authorization', descriptor)
          : delete Object.prototype.Authorization;
      }
    });

    it('should support objects with an own iterator as a key-value source object', () => {
      const headers = new AxiosHeaders();

      headers.set({
        *[Symbol.iterator]() {
          yield ['x', '123'];
        },
      });

      assert.strictEqual(headers.get('x'), '123');
    });

    it('should not use inherited Symbol.iterator as a key-value source object', () => {
      try {
        Object.prototype[Symbol.iterator] = function* () {
          yield ['x-app', 'changed'];
          yield ['x-injected', 'yes'];
        };

        const headers = new AxiosHeaders({
          'x-app': 'safe',
        });

        assert.strictEqual(headers.get('x-app'), 'safe');
        assert.strictEqual(headers.get('x-injected'), undefined);
      } finally {
        delete Object.prototype[Symbol.iterator];
      }
    });

    it('should not read polluted Object.prototype Symbol.iterator accessors', () => {
      let accessed = false;

      try {
        Object.defineProperty(Object.prototype, Symbol.iterator, {
          configurable: true,
          get() {
            accessed = true;
            throw new Error('polluted iterator accessor');
          }
        });

        const headers = new AxiosHeaders({
          'x-app': 'safe',
        });

        assert.strictEqual(headers.get('x-app'), 'safe');
        assert.strictEqual(accessed, false);
      } finally {
        delete Object.prototype[Symbol.iterator];
      }
    });

    it('should not consume an inherited Symbol.iterator for non-plain header sources', () => {
      try {
        Object.prototype[Symbol.iterator] = function* () {
          yield ['x-injected', 'yes'];
          yield ['authorization', 'Bearer CHANGED'];
        };

        // A class instance and an Object.create(...) object both have a direct
        // prototype other than Object.prototype, yet their only iterator comes
        // from the polluted Object.prototype — they must not be iterated.
        class HeaderBag {
          constructor() {
            this['authorization'] = 'Bearer VALID';
          }
        }

        const fromClass = new AxiosHeaders(new HeaderBag());
        assert.strictEqual(fromClass.get('x-injected'), undefined);
        assert.notStrictEqual(fromClass.get('authorization'), 'Bearer CHANGED');

        const created = Object.create({ 'x-app': 'safe' });
        created['authorization'] = 'Bearer VALID';
        const fromCreate = new AxiosHeaders(created);
        assert.strictEqual(fromCreate.get('x-injected'), undefined);
        assert.notStrictEqual(fromCreate.get('authorization'), 'Bearer CHANGED');
      } finally {
        delete Object.prototype[Symbol.iterator];
      }
    });

    const runIfNode18OrHigher = nodeMajorVersion >= 18 ? it : it.skip;
    runIfNode18OrHigher(
      'should support setting multiple header values from an iterable source',
      () => {
        const headers = new AxiosHeaders();
        const nativeHeaders = new Headers();

        nativeHeaders.append('set-cookie', 'foo');
        nativeHeaders.append('set-cookie', 'bar');
        nativeHeaders.append('set-cookie', 'baz');
        nativeHeaders.append('y', 'qux');

        headers.set(nativeHeaders);

        assert.deepStrictEqual(headers.get('set-cookie'), ['foo', 'bar', 'baz']);
        assert.strictEqual(headers.get('y'), 'qux');
      }
    );

    it('should sanitize invalid characters in header value', () => {
      const headers = new AxiosHeaders();

      headers.set('x-test', '\t safe\r\nInjected: true \u0000');

      assert.strictEqual(headers.get('x-test'), 'safeInjected: true');
    });

    it('should sanitize invalid characters in any array header value', () => {
      const headers = new AxiosHeaders();

      headers.set('set-cookie', ['safe=1', ' \tunsafe=1\nInjected: true\r\n ']);

      assert.deepStrictEqual(headers.get('set-cookie'), ['safe=1', 'unsafe=1Injected: true']);
    });

    // Regression: https://github.com/axios/axios/issues/10849
    // Non-control Unicode header values must round-trip through set/get so
    // request interceptors can encode them (e.g. encodeURIComponent) before
    // the adapter sanitizes to byte-safe values at send time.
    it('should preserve non-control Unicode characters in header values', () => {
      const headers = new AxiosHeaders();

      headers.set('x-name', '请求用户');

      assert.strictEqual(headers.get('x-name'), '请求用户');
    });

    it('should preserve non-control Unicode characters in array header values', () => {
      const headers = new AxiosHeaders();

      headers.set('x-names', ['请求用户', 'naïve', 'プロジェクト']);

      assert.deepStrictEqual(headers.get('x-names'), ['请求用户', 'naïve', 'プロジェクト']);
    });

    it('should still strip CR/LF from Unicode header values to prevent header injection', () => {
      const headers = new AxiosHeaders();

      headers.set('x-name', '请求\r\nInjected: true用户');

      assert.strictEqual(headers.get('x-name'), '请求Injected: true用户');
    });

    // Regression: https://github.com/axios/axios/issues/6959
    it('should silently skip empty header names', () => {
      const headers = new AxiosHeaders();

      assert.doesNotThrow(() => headers.set('', 'a'));
      assert.doesNotThrow(() => headers.set('   ', 'b'));
      assert.doesNotThrow(() => headers.set({ '': 'c', '   ': 'd', foo: 'bar' }));
      assert.doesNotThrow(() =>
        headers.set(
          new Map([
            ['', 'e'],
            ['   ', 'f'],
            ['x', 'y'],
          ])
        )
      );

      assert.strictEqual(headers.has(''), false);
      assert.strictEqual(headers.get('foo'), 'bar');
      assert.strictEqual(headers.get('x'), 'y');
      assert.strictEqual(Object.keys(headers).length, 2);
    });
  });

  it('should support uppercase name mapping for names overlapped by class methods', () => {
    const headers = new AxiosHeaders({
      set: 'foo',
    });

    headers.set('get', 'bar');

    assert.strictEqual(headers.get('Set'), 'foo');
    assert.strictEqual(headers.get('Get'), 'bar');
  });

  describe('get', () => {
    describe('filter', () => {
      it('should support RegExp', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        assert.strictEqual(headers.get('foo', /^bar=(\w+)/)[1], 'value1');
        assert.strictEqual(headers.get('foo', /^foo=/), null);
      });

      it('should support function', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        assert.strictEqual(
          headers.get('foo', (value, header) => {
            assert.strictEqual(value, 'bar=value1');
            assert.strictEqual(header, 'foo');
            return value;
          }),
          'bar=value1'
        );
        assert.strictEqual(
          headers.get('foo', () => false),
          false
        );
      });
    });
  });

  describe('has', () => {
    it('should return true if the header is defined, otherwise false', () => {
      const headers = new AxiosHeaders();

      headers.set('foo', 'bar=value1');

      assert.strictEqual(headers.has('foo'), true);
      assert.strictEqual(headers.has('bar'), false);
    });

    describe('filter', () => {
      it('should support RegExp', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        assert.strictEqual(headers.has('foo', /^bar=(\w+)/), true);
        assert.strictEqual(headers.has('foo', /^foo=/), false);
      });

      it('should support function', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        assert.strictEqual(
          headers.has('foo', (value, header) => {
            assert.strictEqual(value, 'bar=value1');
            assert.strictEqual(header, 'foo');
            return true;
          }),
          true
        );
        assert.strictEqual(
          headers.has('foo', () => false),
          false
        );
      });

      it('should support string pattern', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        assert.strictEqual(headers.has('foo', 'value1'), true);
        assert.strictEqual(headers.has('foo', 'value2'), false);
      });
    });
  });

  describe('delete', () => {
    it('should delete the header', () => {
      const headers = new AxiosHeaders();

      headers.set('foo', 'bar=value1');

      assert.strictEqual(headers.has('foo'), true);

      headers.delete('foo');

      assert.strictEqual(headers.has('foo'), false);
    });

    it('should return true if the header has been deleted, otherwise false', () => {
      const headers = new AxiosHeaders();

      headers.set('foo', 'bar=value1');

      assert.strictEqual(headers.delete('bar'), false);

      assert.strictEqual(headers.delete('foo'), true);
    });

    it('should support headers array', () => {
      const headers = new AxiosHeaders();

      headers.set('foo', 'x');
      headers.set('bar', 'y');
      headers.set('baz', 'z');

      assert.strictEqual(headers.delete(['foo', 'baz']), true);

      assert.strictEqual(headers.has('foo'), false);
      assert.strictEqual(headers.has('bar'), true);
      assert.strictEqual(headers.has('baa'), false);
    });

    describe('filter', () => {
      it('should support RegExp', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        assert.strictEqual(headers.has('foo'), true);

        headers.delete('foo', /baz=/);

        assert.strictEqual(headers.has('foo'), true);

        headers.delete('foo', /bar=/);

        assert.strictEqual(headers.has('foo'), false);
      });

      it('should support function', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        headers.delete('foo', (value, header) => {
          assert.strictEqual(value, 'bar=value1');
          assert.strictEqual(header, 'foo');
          return false;
        });

        assert.strictEqual(headers.has('foo'), true);

        assert.strictEqual(
          headers.delete('foo', () => true),
          true
        );

        assert.strictEqual(headers.has('foo'), false);
      });

      it('should support string pattern', () => {
        const headers = new AxiosHeaders();

        headers.set('foo', 'bar=value1');

        assert.strictEqual(headers.has('foo'), true);

        headers.delete('foo', 'baz');

        assert.strictEqual(headers.has('foo'), true);

        headers.delete('foo', 'bar');

        assert.strictEqual(headers.has('foo'), false);
      });
    });
  });

  describe('clear', () => {
    it('should clear all headers', () => {
      const headers = new AxiosHeaders({ x: 1, y: 2 });

      headers.clear();

      assert.deepStrictEqual({ ...headers.toJSON() }, {});
    });

    it('should clear matching headers if a matcher was specified', () => {
      const headers = new AxiosHeaders({ foo: 1, 'x-foo': 2, bar: 3 });

      assert.deepStrictEqual({ ...headers.toJSON() }, { foo: '1', 'x-foo': '2', bar: '3' });

      headers.clear(/^x-/);

      assert.deepStrictEqual({ ...headers.toJSON() }, { foo: '1', bar: '3' });
    });
  });

  describe('toJSON', () => {
    it('should return headers object with original headers case', () => {
      const headers = new AxiosHeaders({
        Foo: 'x',
        bAr: 'y',
      });

      assert.deepStrictEqual(
        { ...headers.toJSON() },
        {
          Foo: 'x',
          bAr: 'y',
        }
      );
    });
  });

  describe('accessors', () => {
    it('should support get accessor', () => {
      const headers = new AxiosHeaders({
        foo: 1,
      });

      headers.constructor.accessor('foo');

      assert.strictEqual(typeof headers.getFoo, 'function');
      assert.strictEqual(headers.getFoo(), '1');
    });

    it('should support set accessor', () => {
      const headers = new AxiosHeaders({
        foo: 1,
      });

      headers.constructor.accessor('foo');

      assert.strictEqual(typeof headers.setFoo, 'function');
      headers.setFoo(2);
      assert.strictEqual(headers.getFoo(), '2');
    });

    it('should support has accessor', () => {
      const headers = new AxiosHeaders({
        foo: 1,
      });

      headers.constructor.accessor('foo');

      assert.strictEqual(typeof headers.hasFoo, 'function');
      assert.strictEqual(headers.hasFoo(), true);
    });
  });

  it('should be caseless', () => {
    const headers = new AxiosHeaders({
      fOo: 1,
    });

    assert.strictEqual(headers.get('Foo'), '1');
    assert.strictEqual(headers.get('foo'), '1');

    headers.set('foo', 2);

    assert.strictEqual(headers.get('foO'), '2');
    assert.strictEqual(headers.get('fOo'), '2');

    assert.strictEqual(headers.has('fOo'), true);

    headers.delete('FOO');

    assert.strictEqual(headers.has('fOo'), false);
  });

  describe('normalize()', () => {
    it('should support auto-formatting', () => {
      const headers = new AxiosHeaders({
        fOo: 1,
        'x-foo': 2,
        'y-bar-bAz': 3,
      });

      assert.deepStrictEqual(
        { ...headers.normalize(true).toJSON() },
        {
          Foo: '1',
          'X-Foo': '2',
          'Y-Bar-Baz': '3',
        }
      );
    });

    it('should support external defined values', () => {
      const headers = new AxiosHeaders({
        foo: '1',
      });

      headers.Foo = 2;
      headers.bar = 3;

      assert.deepStrictEqual(
        { ...headers.normalize().toJSON() },
        {
          foo: '2',
          bar: '3',
        }
      );
    });

    it('should support array values', () => {
      const headers = new AxiosHeaders({
        foo: [1, 2, 3],
      });

      assert.deepStrictEqual(
        { ...headers.normalize().toJSON() },
        {
          foo: ['1', '2', '3'],
        }
      );
    });
  });

  describe('AxiosHeaders.concat', () => {
    it('should concatenate plain headers into an AxiosHeader instance', () => {
      const a = { a: 1 };
      const b = { b: 2 };
      const c = { c: 3 };
      const headers = AxiosHeaders.concat(a, b, c);

      assert.deepStrictEqual(
        { ...headers.toJSON() },
        {
          a: '1',
          b: '2',
          c: '3',
        }
      );
    });

    it('should concatenate raw headers into an AxiosHeader instance', () => {
      const a = 'a:1\nb:2';
      const b = 'c:3\nx:4';
      const headers = AxiosHeaders.concat(a, b);

      assert.deepStrictEqual(
        { ...headers.toJSON() },
        {
          a: '1',
          b: '2',
          c: '3',
          x: '4',
        }
      );
    });

    it('should concatenate Axios headers into a new AxiosHeader instance', () => {
      const a = new AxiosHeaders({ x: 1 });
      const b = new AxiosHeaders({ y: 2 });
      const headers = AxiosHeaders.concat(a, b);

      assert.deepStrictEqual(
        { ...headers.toJSON() },
        {
          x: '1',
          y: '2',
        }
      );
    });
  });

  describe('toString', () => {
    it('should serialize AxiosHeader instance to a raw headers string', () => {
      assert.deepStrictEqual(new AxiosHeaders({ x: 1, y: 2 }).toString(), 'x: 1\ny: 2');
    });
  });

  describe('getSetCookie', () => {
    it('should return set-cookie', () => {
      const headers = new AxiosHeaders('Set-Cookie: key=val;\n' + 'Set-Cookie: key2=val2;\n');

      assert.deepStrictEqual(headers.getSetCookie(), ['key=val;', 'key2=val2;']);
    });

    it('should return empty set-cookie', () => {
      assert.deepStrictEqual(new AxiosHeaders().getSetCookie(), []);
    });
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import axios from '../../index.js';
import { startHTTPServer, stopHTTPServer } from '../setup/server.js';

describe('QUERY method', () => {
  describe('static axios.query()', () => {
    it('should make a request with the QUERY HTTP method', async () => {
      const response = await axios.query('/test', null, {
        adapter: (config) => {
          assert.strictEqual(config.method, 'query');
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });

      assert.strictEqual(response.status, 200);
    });

    it('should support a request body', async () => {
      const requestBody = { selector: 'field1, field2', filter: { active: true } };

      await axios.query('/search', requestBody, {
        adapter: (config) => {
          assert.deepStrictEqual(config.data, JSON.stringify(requestBody));
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });
    });

    it('should support custom headers', async () => {
      await axios.query('/test', null, {
        headers: {
          'X-Custom-Header': 'custom-value',
          Authorization: 'Bearer token-abc',
        },
        adapter: (config) => {
          assert.strictEqual(config.headers.get('X-Custom-Header'), 'custom-value');
          assert.strictEqual(config.headers.get('Authorization'), 'Bearer token-abc');
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });
    });

    it('should work with baseURL configuration', async () => {
      const instance = axios.create({ baseURL: 'http://example.com/api' });

      await instance.query('/resources', { fields: ['name'] }, {
        adapter: (config) => {
          assert.strictEqual(config.baseURL, 'http://example.com/api');
          assert.strictEqual(config.url, '/resources');
          assert.strictEqual(config.method, 'query');
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });
    });

    it('should set Content-Type to application/json for object bodies', async () => {
      await axios.query('/test', { key: 'value' }, {
        adapter: (config) => {
          assert.ok(
            config.headers.get('Content-Type').includes('application/json'),
            'Expected Content-Type to include application/json'
          );
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });
    });
  });

  describe('instance.query()', () => {
    it('should make a request with the QUERY HTTP method on an instance', async () => {
      const instance = axios.create();

      const response = await instance.query('/test', null, {
        adapter: (config) => {
          assert.strictEqual(config.method, 'query');
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });

      assert.strictEqual(response.status, 200);
    });

    it('should merge instance defaults with request config', async () => {
      const instance = axios.create({
        headers: { 'X-Instance-Header': 'from-instance' },
      });

      await instance.query('/test', null, {
        headers: { 'X-Request-Header': 'from-request' },
        adapter: (config) => {
          assert.strictEqual(config.headers.get('X-Instance-Header'), 'from-instance');
          assert.strictEqual(config.headers.get('X-Request-Header'), 'from-request');
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });
    });
  });

  describe('axios({ method: "query" })', () => {
    it('should support the generic request form', async () => {
      const response = await axios({
        method: 'query',
        url: '/test',
        data: { selector: '*' },
        adapter: (config) => {
          assert.strictEqual(config.method, 'query');
          assert.deepStrictEqual(config.data, JSON.stringify({ selector: '*' }));
          return Promise.resolve({
            data: { result: 'ok' },
            status: 200,
            statusText: 'OK',
            headers: {},
            config,
            request: {},
          });
        },
      });

      assert.deepStrictEqual(response.data, { result: 'ok' });
    });
  });

  describe('with HTTP server', () => {
    it('should send QUERY requests with a body to a real server', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          let body = '';
          req.on('data', (chunk) => { body += chunk; });
          req.on('end', () => {
            res.setHeader('Content-Type', 'application/json');
            res.end(JSON.stringify({
              method: req.method,
              url: req.url,
              body,
              headers: req.headers,
            }));
          });
        },
        { port: 0 }
      );

      try {
        const { data } = await axios.query(
          `http://localhost:${server.address().port}/search`,
          { selector: 'field1' }
        );

        assert.strictEqual(data.method, 'QUERY');
        assert.strictEqual(data.url, '/search');

        const parsedBody = JSON.parse(data.body);
        assert.deepStrictEqual(parsedBody, { selector: 'field1' });
        assert.ok(
          data.headers['content-type'].includes('application/json'),
          'Expected server to receive application/json content-type'
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should send QUERY requests with custom headers to a real server', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          res.setHeader('Content-Type', 'application/json');
          res.end(JSON.stringify({
            method: req.method,
            headers: req.headers,
          }));
        },
        { port: 0 }
      );

      try {
        const { data } = await axios.query(
          `http://localhost:${server.address().port}/test`,
          null,
          {
            headers: {
              'X-Custom': 'test-value',
            },
          }
        );

        assert.strictEqual(data.method, 'QUERY');
        assert.strictEqual(data.headers['x-custom'], 'test-value');
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should send QUERY requests with baseURL to a real server', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          res.setHeader('Content-Type', 'application/json');
          res.end(JSON.stringify({
            method: req.method,
            url: req.url,
          }));
        },
        { port: 0 }
      );

      try {
        const instance = axios.create({
          baseURL: `http://localhost:${server.address().port}/api`,
        });

        const { data } = await instance.query('/resources', { fields: ['name'] });

        assert.strictEqual(data.method, 'QUERY');
        assert.strictEqual(data.url, '/api/resources');
      } finally {
        await stopHTTPServer(server);
      }
    });
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import utils from '../../lib/utils.js';
import FormData from 'form-data';
import stream from 'stream';

describe('utils', () => {
  it('should validate Stream', () => {
    assert.strictEqual(utils.isStream(new stream.Readable()), true);
    assert.strictEqual(utils.isStream({ foo: 'bar' }), false);
  });

  it('should validate Buffer', () => {
    assert.strictEqual(utils.isBuffer(Buffer.from('a')), true);
    assert.strictEqual(utils.isBuffer(null), false);
    assert.strictEqual(utils.isBuffer(undefined), false);
  });

  describe('utils::isFormData', () => {
    it('should detect the FormData instance provided by the `form-data` package', () => {
      [1, 'str', {}, new RegExp()].forEach((thing) => {
        assert.equal(utils.isFormData(thing), false);
      });
      assert.equal(utils.isFormData(new FormData()), true);
    });

    it('should not call toString method on built-in objects instances', () => {
      const buf = Buffer.from('123');

      buf.toString = () => assert.fail('should not be called');

      assert.equal(utils.isFormData(buf), false);
    });

    it('should not call toString method on built-in objects instances, even if append method exists', () => {
      const buf = Buffer.from('123');

      buf.append = () => {};

      buf.toString = () => assert.fail('should not be called');

      assert.equal(utils.isFormData(buf), false);
    });

    it('should detect custom FormData instances by toStringTag signature and append method presence', () => {
      class FormData {
        append() {}

        get [Symbol.toStringTag]() {
          return 'FormData';
        }
      }
      assert.equal(utils.isFormData(new FormData()), true);
    });
  });

  describe('toJSON', () => {
    it('should convert to a plain object without circular references', () => {
      const obj = { a: [0] };
      const source = { x: 1, y: 2, obj };
      source.circular1 = source;
      obj.a[1] = obj;

      assert.deepStrictEqual(utils.toJSONObject(source), {
        x: 1,
        y: 2,
        obj: { a: [0] },
      });
    });

    it('should use objects with defined toJSON method without rebuilding', () => {
      const objProp = {};
      const obj = {
        objProp,
        toJSON() {
          return { ok: 1 };
        },
      };
      const source = { x: 1, y: 2, obj };

      const jsonObject = utils.toJSONObject(source);

      assert.strictEqual(jsonObject.obj.objProp, objProp);
      assert.strictEqual(
        JSON.stringify(jsonObject),
        JSON.stringify({ x: 1, y: 2, obj: { ok: 1 } })
      );
    });

    describe('cycle / DAG handling', () => {
      it('should serialize a shared sibling object at every occurrence (DAG, not cycle)', () => {
        const shared = { val: 42 };
        const source = { x: shared, y: shared };

        const result = utils.toJSONObject(source);

        // Both branches must serialize — shared reference is not a cycle
        assert.deepStrictEqual(result, { x: { val: 42 }, y: { val: 42 } });
      });

      it('should serialize a shared sibling array at every occurrence (DAG, not cycle)', () => {
        const shared = [1, 2, 3];
        const source = { a: shared, b: shared };

        const result = utils.toJSONObject(source);

        assert.deepStrictEqual(result, { a: [1, 2, 3], b: [1, 2, 3] });
      });

      it('should serialize shared sibling that itself contains a self-cycle', () => {
        const shared = { v: 1 };
        shared.self = shared; // self-cycle inside the shared node
        const source = { x: shared, y: shared };

        const result = utils.toJSONObject(source);

        // The self-cycle is stripped, but both x and y must be serialized
        assert.deepStrictEqual(result, { x: { v: 1 }, y: { v: 1 } });
      });

      it('should serialize non-cyclic structures deeper than the old Array(10) cap', () => {
        // The previous implementation used a fixed-size Array(10) for path tracking.
        // A non-cyclic chain deeper than 10 levels must serialise end-to-end.
        let leaf = { v: 'leaf' };
        let source = leaf;
        for (let i = 0; i < 25; i++) {
          source = { next: source };
        }

        const result = utils.toJSONObject(source);

        let cursor = result;
        for (let i = 0; i < 25; i++) {
          cursor = cursor.next;
        }
        assert.deepStrictEqual(cursor, { v: 'leaf' });
      });
    });
  });

  describe('Buffer RangeError Fix', () => {
    it('should handle large Buffer in isEmptyObject without RangeError', () => {
      const largeBuffer = Buffer.alloc(1024 * 1024 * 200);

      const result = utils.isEmptyObject(largeBuffer);

      assert.strictEqual(result, false);
    });

    it('should handle large Buffer in forEach without RangeError', () => {
      const largeBuffer = Buffer.alloc(1024 * 1024 * 200);
      let count = 0;

      utils.forEach(largeBuffer, () => count++);

      assert.strictEqual(count, 0);
    });

    it('should handle large Buffer in findKey without RangeError', () => {
      const largeBuffer = Buffer.alloc(1024 * 1024 * 200);

      const result = utils.findKey(largeBuffer, 'test');

      assert.strictEqual(result, null);
    });
  });

  describe('utils::isReactNativeBlob', () => {
    it('should return true for objects with uri property', () => {
      assert.strictEqual(utils.isReactNativeBlob({ uri: 'file://path/to/file' }), true);
      assert.strictEqual(utils.isReactNativeBlob({ uri: 'content://media/image' }), true);
    });

    it('should return true for React Native blob-like objects with optional name and type', () => {
      assert.strictEqual(
        utils.isReactNativeBlob({
          uri: 'file://path/to/file',
          name: 'image.png',
          type: 'image/png',
        }),
        true
      );
    });

    it('should return false for objects without uri property', () => {
      assert.strictEqual(utils.isReactNativeBlob({ path: 'file://path' }), false);
      assert.strictEqual(utils.isReactNativeBlob({ url: 'http://example.com' }), false);
      assert.strictEqual(utils.isReactNativeBlob({}), false);
    });

    it('should return false for non-objects', () => {
      assert.strictEqual(utils.isReactNativeBlob(null), false);
      assert.strictEqual(utils.isReactNativeBlob(undefined), false);
      assert.strictEqual(utils.isReactNativeBlob('string'), false);
      assert.strictEqual(utils.isReactNativeBlob(123), false);
      assert.strictEqual(utils.isReactNativeBlob(false), false);
    });

    it('should return true even if uri is empty string', () => {
      assert.strictEqual(utils.isReactNativeBlob({ uri: '' }), true);
    });
  });

  describe('utils::isReactNative', () => {
    it('should return true for FormData with getParts method', () => {
      const mockReactNativeFormData = {
        append: () => {},
        getParts: () => {
          return [];
        },
      };
      assert.strictEqual(utils.isReactNative(mockReactNativeFormData), true);
    });

    it('should return false for standard FormData without getParts method', () => {
      const standardFormData = new FormData();
      assert.strictEqual(utils.isReactNative(standardFormData), false);
    });

    it('should return false for objects without getParts method', () => {
      assert.strictEqual(utils.isReactNative({ append: () => {} }), false);
      assert.strictEqual(utils.isReactNative({}), false);
    });
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import FormData from 'form-data';
import toFormData from '../../lib/helpers/toFormData.js';
import AxiosError from '../../lib/core/AxiosError.js';
import AxiosURLSearchParams from '../../lib/helpers/AxiosURLSearchParams.js';

describe('helpers::toFormData', () => {
  const createRNFormDataSpy = () => {
    const calls = [];
    return {
      calls,
      append: (key, value) => {
        calls.push([key, value]);
      },
      getParts: () => {
        return [];
      },
    };
  };

  it('should convert a flat object to FormData', () => {
    const data = {
      foo: 'bar',
      baz: 123,
    };

    const formData = toFormData(data, new FormData());

    assert.ok(formData instanceof FormData);
    assert.ok(formData._streams.length > 0);
  });

  it('should convert a nested object to FormData', () => {
    const data = {
      foo: {
        bar: 'baz',
      },
    };

    const formData = toFormData(data, new FormData());

    assert.ok(formData instanceof FormData);
  });

  it('should throw Error on circular reference', () => {
    const data = {
      foo: 'bar',
    };
    data.self = data;

    try {
      toFormData(data, new FormData());
      assert.fail('Should have thrown an error');
    } catch (err) {
      assert.strictEqual(err.message, 'Circular reference detected in self');
    }
  });

  it('should handle arrays', () => {
    const data = {
      arr: [1, 2, 3],
    };

    const formData = toFormData(data, new FormData());
    assert.ok(formData instanceof FormData);
  });

  it('should append root-level React Native blob without recursion', () => {
    const formData = createRNFormDataSpy();

    const blob = {
      uri: 'file://test.png',
      type: 'image/png',
      name: 'test.png',
    };

    toFormData({ file: blob }, formData);

    assert.strictEqual(formData.calls.length, 1);
    assert.strictEqual(formData.calls[0][0], 'file');
    assert.strictEqual(formData.calls[0][1], blob);
  });

  it('should append nested React Native blob without recursion', () => {
    const formData = createRNFormDataSpy();

    const blob = {
      uri: 'file://nested.png',
      type: 'image/png',
      name: 'nested.png',
    };

    toFormData({ nested: { file: blob } }, formData);

    assert.strictEqual(formData.calls.length, 1);
    assert.strictEqual(formData.calls[0][0], 'nested[file]');
    assert.strictEqual(formData.calls[0][1], blob);
  });

  it('should append deeply nested React Native blob without recursion', () => {
    const formData = createRNFormDataSpy();

    const blob = {
      uri: 'file://deep.png',
      name: 'deep.png',
    };

    toFormData({ a: { b: { c: blob } } }, formData);

    assert.strictEqual(formData.calls.length, 1);
    assert.strictEqual(formData.calls[0][0], 'a[b][c]');
    assert.strictEqual(formData.calls[0][1], blob);
  });

  // --- Depth limit tests ---

  function nest(depth) {
    let o = { leaf: 1 };
    for (let i = 0; i < depth; i++) o = { a: o };
    return o;
  }

  describe('maxDepth option', () => {
    it('should throw AxiosError when payload exceeds default depth limit (100)', () => {
      try {
        toFormData(nest(101), new FormData());
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(err instanceof AxiosError, 'error must be AxiosError, not RangeError');
        assert.strictEqual(err.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
        assert.ok(!(err instanceof RangeError));
      }
    });

    it('should succeed when payload is exactly at the default depth limit (100)', () => {
      const formData = toFormData(nest(100), new FormData());
      assert.ok(formData instanceof FormData);
    });

    it('should succeed for a shallow payload (no regression)', () => {
      const formData = toFormData(nest(5), new FormData());
      assert.ok(formData instanceof FormData);
    });

    it('should allow deeper payloads when maxDepth is raised', () => {
      const formData = toFormData(nest(150), new FormData(), { maxDepth: 200 });
      assert.ok(formData instanceof FormData);
    });

    it('should reject shallower payloads when maxDepth is lowered', () => {
      try {
        toFormData(nest(10), new FormData(), { maxDepth: 5 });
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(err instanceof AxiosError);
        assert.strictEqual(err.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
      }
    });

    it('should not throw for depth guard when maxDepth is Infinity (guard disabled)', () => {
      // Use 500 levels — deep enough to prove the guard is off, shallow enough not to overflow V8
      const formData = toFormData(nest(500), new FormData(), { maxDepth: Infinity });
      assert.ok(formData instanceof FormData);
    });

    it('should still detect circular references when depth guard is active', () => {
      const data = { foo: 'bar' };
      data.self = data;
      try {
        toFormData(data, new FormData());
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(
          err.message.includes('Circular reference detected'),
          'must be circular-ref error'
        );
        assert.ok(!(err instanceof AxiosError) || err.code !== 'ERR_FORM_DATA_DEPTH_EXCEEDED');
      }
    });

    it('depth limit error is catchable as AxiosError with correct code', () => {
      let caught;
      try {
        toFormData(nest(101), new FormData());
      } catch (err) {
        caught = err;
      }
      assert.ok(caught instanceof AxiosError);
      assert.strictEqual(caught.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
      assert.ok(!(caught instanceof RangeError));
    });

    it('should reject deeply nested {} metatoken values before JSON.stringify overflows', () => {
      try {
        toFormData({ 'evil{}': nest(10000) }, new FormData());
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(err instanceof AxiosError, 'error must be AxiosError, not RangeError');
        assert.strictEqual(err.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
        assert.ok(!(err instanceof RangeError));
      }
    });

    it('should allow {} metatoken values at the same boundary as normal top-level properties', () => {
      const formData = toFormData({ 'safe{}': nest(99) }, new FormData());
      assert.ok(formData instanceof FormData);
    });

    it('should reject {} metatoken values beyond the normal top-level property boundary', () => {
      try {
        toFormData({ 'evil{}': nest(100) }, new FormData());
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(err instanceof AxiosError);
        assert.strictEqual(err.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
      }
    });
  });

  describe('maxDepth — params serialization via AxiosURLSearchParams', () => {
    it('should throw AxiosError for deeply nested params object (default limit)', () => {
      try {
        new AxiosURLSearchParams(nest(101));
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(err instanceof AxiosError);
        assert.strictEqual(err.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
      }
    });

    it('should build query string for deep params when maxDepth is raised', () => {
      const params = new AxiosURLSearchParams(nest(150), { maxDepth: 200 });
      const qs = params.toString();
      assert.ok(typeof qs === 'string' && qs.length > 0);
    });

    it('should reject deeply nested {} metatoken params before JSON.stringify overflows', () => {
      try {
        new AxiosURLSearchParams({ 'evil{}': nest(10000) });
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(err instanceof AxiosError, 'error must be AxiosError, not RangeError');
        assert.strictEqual(err.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
        assert.ok(!(err instanceof RangeError));
      }
    });

    it('should reject {} metatoken params beyond the normal property boundary', () => {
      try {
        new AxiosURLSearchParams({ 'evil{}': nest(100) });
        assert.fail('Should have thrown');
      } catch (err) {
        assert.ok(err instanceof AxiosError);
        assert.strictEqual(err.code, 'ERR_FORM_DATA_DEPTH_EXCEEDED');
      }
    });
  });

  it('should NOT recurse into React Native blob properties', () => {
    const formData = createRNFormDataSpy();

    const blob = {
      uri: 'file://nope.png',
      type: 'image/png',
      name: 'nope.png',
    };

    toFormData({ file: blob }, formData);

    const keys = formData.calls.map((call) => call[0]);

    assert.deepStrictEqual(keys, ['file']);
    assert.ok(!keys.some((key) => key.includes('uri')));
    assert.ok(!keys.some((key) => key.includes('type')));
    assert.ok(!keys.some((key) => key.includes('name')));
  });
});

import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Parser } from 'acorn';

const LIB_DIR = fileURLToPath(new URL('../../lib/', import.meta.url));
const ECMA_VERSION = 2018;

function walk(dir) {
  const out = [];
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) out.push(...walk(full));
    else if (full.endsWith('.js')) out.push(full);
  }
  return out;
}

describe('lib/ source files parse as ES2018', () => {
  for (const file of walk(LIB_DIR)) {
    const rel = file.slice(LIB_DIR.length);
    it(rel, () => {
      const src = readFileSync(file, 'utf8');
      expect(() =>
        Parser.parse(src, { ecmaVersion: ECMA_VERSION, sourceType: 'module' })
      ).not.toThrow();
    });
  }
});

