import { describe, it, expect } from 'vitest';
import transformData from '../../../lib/core/transformData.js';

describe('core::transformData', () => {
  it('supports a single transformer', () => {
    const data = transformData.call({}, (value) => {
      value = 'foo';
      return value;
    });

    expect(data).toBe('foo');
  });

  it('supports an array of transformers', () => {
    const data = transformData.call({ data: '' }, [
      (value) => value + 'f',
      (value) => value + 'o',
      (value) => value + 'o',
    ]);

    expect(data).toBe('foo');
  });

  it('passes headers through to transformers', () => {
    const headers = {
      'content-type': 'foo/bar',
    };

    const data = transformData.call(
      {
        data: '',
        headers,
      },
      [(value, currentHeaders) => value + currentHeaders['content-type']]
    );

    expect(data).toBe('foo/bar');
  });

  it('passes status code through to transformers', () => {
    const data = transformData.call(
      {},
      [(value, _headers, status) => value + status],
      { data: '', status: 200 }
    );

    expect(data).toBe('200');
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import dispatchRequest from '../../../lib/core/dispatchRequest.js';
import AxiosError from '../../../lib/core/AxiosError.js';
import defaults from '../../../lib/defaults/index.js';
import resolveConfig from '../../../lib/helpers/resolveConfig.js';

class ReactNativeFormData {
  append() {}

  getParts() {
    return [];
  }

  get [Symbol.toStringTag]() {
    return 'FormData';
  }
}

function baseConfig(overrides = {}) {
  return {
    method: 'get',
    url: '/test',
    headers: {},
    transformRequest: defaults.transformRequest,
    transformResponse: defaults.transformResponse,
    transitional: { silentJSONParsing: false, forcedJSONParsing: true },
    responseType: 'json',
    ...overrides,
  };
}

describe('core::dispatchRequest', () => {
  describe('JSON FormData transform', () => {
    it('rejects deeply nested field paths before adapter dispatch', async () => {
      const data = new FormData();
      let adapterCalled = false;

      data.append('foo' + '[bar]'.repeat(101), '123');

      const config = baseConfig({
        data,
        headers: { 'Content-Type': 'application/json' },
        method: 'post',
        adapter(adapterConfig) {
          adapterCalled = true;
          return Promise.resolve({
            data: null,
            status: 200,
            statusText: 'OK',
            headers: {},
            config: adapterConfig,
            request: {},
          });
        },
      });

      let thrown;
      try {
        await dispatchRequest(config);
      } catch (e) {
        thrown = e;
      }

      assert.ok(thrown instanceof AxiosError, 'must be AxiosError');
      assert.strictEqual(thrown.code, AxiosError.ERR_FORM_DATA_DEPTH_EXCEEDED);
      assert.strictEqual(adapterCalled, false);
    });
  });

  describe('JSON parse failure on adapter resolution', () => {
    it('rejects with AxiosError carrying response and status', async () => {
      const response = {
        data: '{bad json',
        status: 418,
        statusText: "I'm a teapot",
        headers: {},
        config: null,
        request: {},
      };
      const config = baseConfig({ adapter: () => Promise.resolve(response) });

      let thrown;
      try {
        await dispatchRequest(config);
      } catch (e) {
        thrown = e;
      }

      assert.ok(thrown instanceof AxiosError, 'must be AxiosError');
      assert.strictEqual(thrown.code, AxiosError.ERR_BAD_RESPONSE);
      assert.strictEqual(thrown.response, response, 'error.response must be the original response');
      assert.strictEqual(thrown.status, 418, 'error.status must equal response status');
    });

    it('cleans up config.response after the transform throws', async () => {
      const response = {
        data: '{bad json',
        status: 200,
        statusText: 'OK',
        headers: {},
        config: null,
        request: {},
      };
      const config = baseConfig({ adapter: () => Promise.resolve(response) });

      try {
        await dispatchRequest(config);
      } catch (_) {
        // expected
      }

      assert.strictEqual(
        Object.prototype.hasOwnProperty.call(config, 'response'),
        false,
        'config.response must be deleted in finally'
      );
    });
  });

  describe('JSON parse failure on adapter rejection', () => {
    it('rejects with AxiosError carrying response and status (rejection path)', async () => {
      const response = {
        data: '{bad json',
        status: 500,
        statusText: 'Internal Server Error',
        headers: {},
        config: null,
        request: {},
      };
      const reason = new AxiosError('Request failed', AxiosError.ERR_BAD_RESPONSE);
      reason.response = response;
      const config = baseConfig({ adapter: () => Promise.reject(reason) });

      let thrown;
      try {
        await dispatchRequest(config);
      } catch (e) {
        thrown = e;
      }

      assert.ok(thrown instanceof AxiosError, 'must be AxiosError');
      assert.strictEqual(thrown.response, response, 'error.response must be the original response');
      assert.strictEqual(thrown.status, 500, 'error.status must equal response status');
    });

    it('cleans up config.response after the rejection-path transform', async () => {
      const response = {
        data: '{bad json',
        status: 500,
        statusText: 'Internal Server Error',
        headers: {},
        config: null,
        request: {},
      };
      const reason = new AxiosError('Request failed', AxiosError.ERR_BAD_RESPONSE);
      reason.response = response;
      const config = baseConfig({ adapter: () => Promise.reject(reason) });

      try {
        await dispatchRequest(config);
      } catch (_) {
        // expected
      }

      assert.strictEqual(
        Object.prototype.hasOwnProperty.call(config, 'response'),
        false,
        'config.response must be deleted in finally on the rejection path'
      );
    });
  });

  describe('happy path', () => {
    it('clears default Content-Type for React Native FormData before adapter headers are sent', async () => {
      const data = new ReactNativeFormData();
      const response = {
        data: '{"ok":true}',
        status: 200,
        statusText: 'OK',
        headers: {},
        config: null,
        request: {},
      };
      const config = baseConfig({
        method: 'post',
        data,
        adapter: (adapterConfig) => {
          assert.strictEqual(
            adapterConfig.headers.getContentType(),
            'application/x-www-form-urlencoded',
            'dispatchRequest should apply the default POST Content-Type first'
          );

          const resolvedConfig = resolveConfig(adapterConfig);

          assert.strictEqual(resolvedConfig.data, data);
          assert.strictEqual(resolvedConfig.headers.getContentType(), undefined);
          assert.strictEqual(
            Object.prototype.hasOwnProperty.call(resolvedConfig.headers.toJSON(), 'Content-Type'),
            false,
            'resolved adapter headers must omit Content-Type for React Native FormData'
          );

          return Promise.resolve(response);
        },
      });

      const result = await dispatchRequest(config);

      assert.deepStrictEqual(result.data, { ok: true });
    });

    it('cleans up config.response after a successful resolution', async () => {
      const response = {
        data: '{"ok":true}',
        status: 200,
        statusText: 'OK',
        headers: {},
        config: null,
        request: {},
      };
      const config = baseConfig({ adapter: () => Promise.resolve(response) });

      const result = await dispatchRequest(config);

      assert.deepStrictEqual(result.data, { ok: true });
      assert.strictEqual(
        Object.prototype.hasOwnProperty.call(config, 'response'),
        false,
        'config.response must not be left set after a successful request'
      );
    });
  });
});

import { describe, it, expect } from 'vitest';
import buildFullPath from '../../../lib/core/buildFullPath.js';
import AxiosError from '../../../lib/core/AxiosError.js';

describe('core::buildFullPath', () => {
  it('combines URLs when the requested URL is relative', () => {
    expect(buildFullPath('https://api.github.com', '/users')).toBe('https://api.github.com/users');
  });

  it('does not combine URLs when the requested URL is absolute', () => {
    expect(buildFullPath('https://api.github.com', 'https://api.example.com/users')).toBe(
      'https://api.example.com/users'
    );
  });

  it('combines URLs when requested URL is absolute and allowAbsoluteUrls is false', () => {
    expect(buildFullPath('https://api.github.com', 'https://api.example.com/users', false)).toBe(
      'https://api.github.com/https://api.example.com/users'
    );
  });

  it('does not combine URLs when baseURL is missing and allowAbsoluteUrls is false', () => {
    expect(buildFullPath(undefined, 'https://api.example.com/users', false)).toBe(
      'https://api.example.com/users'
    );
  });

  it('does not combine URLs when baseURL is not configured', () => {
    expect(buildFullPath(undefined, '/users')).toBe('/users');
  });

  it('combines URLs when baseURL and requested URL are both relative', () => {
    expect(buildFullPath('/api', '/users')).toBe('/api/users');
  });

  it('rejects HTTP URLs missing slashes after the protocol', () => {
    for (const call of [
      () => buildFullPath(undefined, 'https:example.com/users'),
      () => buildFullPath(undefined, '\thttps:example.com/users'),
      () => buildFullPath(undefined, '\u0000https:example.com/users'),
      () => buildFullPath(undefined, 'h\nttp:example.com/users'),
      () => buildFullPath(undefined, 'ht\ttp:example.com/users'),
      () => buildFullPath(undefined, 'htt\rp:example.com/users'),
      () => buildFullPath(undefined, 'http:/example.com/users'),
      () => buildFullPath('http:example.com/api', '/users'),
    ]) {
      let error;
      try {
        call();
      } catch (err) {
        error = err;
      }

      expect(error).toBeInstanceOf(AxiosError);
      expect(error.code).toBe(AxiosError.ERR_INVALID_URL);
      expect(error.message).toBe('Invalid URL: missing "//" after protocol');
    }
  });

  it('does not reject an unused malformed baseURL for absolute requests', () => {
    expect(buildFullPath('http:example.com/api', 'https://api.example.com/users')).toBe(
      'https://api.example.com/users'
    );
  });

  it('rejects a malformed baseURL when absolute requests are forced through baseURL', () => {
    let error;

    try {
      buildFullPath('http:example.com/api', 'https://api.example.com/users', false);
    } catch (err) {
      error = err;
    }

    expect(error).toBeInstanceOf(AxiosError);
    expect(error.code).toBe(AxiosError.ERR_INVALID_URL);
    expect(error.message).toBe('Invalid URL: missing "//" after protocol');
  });
});

import { describe, it, expect } from 'vitest';
import { isNativeError } from 'node:util/types';
import AxiosError from '../../../lib/core/AxiosError.js';
import AxiosHeaders from '../../../lib/core/AxiosHeaders.js';

describe('core::AxiosError', () => {
  it('creates an error with message, config, code, request, response, stack and isAxiosError', () => {
    const request = { path: '/foo' };
    const response = { status: 200, data: { foo: 'bar' } };
    const error = new AxiosError('Boom!', 'ESOMETHING', { foo: 'bar' }, request, response);

    expect(error).toBeInstanceOf(Error);
    expect(error.message).toBe('Boom!');
    expect(error.config).toEqual({ foo: 'bar' });
    expect(error.code).toBe('ESOMETHING');
    expect(error.request).toBe(request);
    expect(error.response).toBe(response);
    expect(error.isAxiosError).toBe(true);
    expect(error.stack).toBeDefined();
  });

  it('serializes to JSON safely', () => {
    // request/response are intentionally omitted from the serialized shape
    // to avoid circular-reference problems.
    const request = { path: '/foo' };
    const response = { status: 200, data: { foo: 'bar' } };
    const error = new AxiosError('Boom!', 'ESOMETHING', { foo: 'bar' }, request, response);
    const json = error.toJSON();

    expect(json.message).toBe('Boom!');
    expect(json.config).toEqual({ foo: 'bar' });
    expect(json.code).toBe('ESOMETHING');
    expect(json.status).toBe(200);
    expect(json.request).toBeUndefined();
    expect(json.response).toBeUndefined();
  });

  describe('AxiosError.from', () => {
    it('adds config, code, request and response to the wrapped error', () => {
      const error = new Error('Boom!');
      const request = { path: '/foo' };
      const response = { status: 200, data: { foo: 'bar' } };

      const axiosError = AxiosError.from(error, 'ESOMETHING', { foo: 'bar' }, request, response);

      expect(axiosError.config).toEqual({ foo: 'bar' });
      expect(axiosError.code).toBe('ESOMETHING');
      expect(axiosError.request).toBe(request);
      expect(axiosError.response).toBe(response);
      expect(axiosError.isAxiosError).toBe(true);
    });

    it('returns an AxiosError instance', () => {
      const axiosError = AxiosError.from(new Error('Boom!'), 'ESOMETHING', { foo: 'bar' });

      expect(axiosError).toBeInstanceOf(AxiosError);
    });

    it('preserves status from the original error when response is not provided', () => {
      const error = new Error('Network Error');
      error.status = 404;

      const axiosError = AxiosError.from(error, 'ERR_NETWORK', { foo: 'bar' });

      expect(axiosError.status).toBe(404);
    });

    it('prefers response.status over error.status when response is provided', () => {
      const error = new Error('Error');
      error.status = 500;
      const response = { status: 404 };

      const axiosError = AxiosError.from(error, 'ERR_BAD_REQUEST', {}, null, response);

      expect(axiosError.status).toBe(404);
    });
  });

  it('is recognized as a native error by Node util/types', () => {
    expect(isNativeError(new AxiosError('My Axios Error'))).toBe(true);
  });

  it('supports static error-code properties', () => {
    const error = new AxiosError('My Axios Error', AxiosError.ECONNABORTED);

    expect(error.code).toBe(AxiosError.ECONNABORTED);
  });

  it('sets status when response is passed to constructor', () => {
    const error = new AxiosError('test', 'foo', {}, {}, { status: 400 });

    expect(error.status).toBe(400);
  });

  describe('status field behaviour (issue #5330)', () => {
    it('error.status equals response.status for 4xx errors', () => {
      // Regression test: error.status must be directly accessible without
      // going through error.response.status.
      const error = new AxiosError(
        'Request failed with status code 404',
        AxiosError.ERR_BAD_REQUEST,
        {},
        {},
        { status: 404, statusText: 'Not Found' }
      );

      expect(error.status).toBe(404);
      expect(error.status).toBe(error.response.status);
    });

    it('error.status equals response.status for 5xx errors', () => {
      const error = new AxiosError(
        'Request failed with status code 503',
        AxiosError.ERR_BAD_RESPONSE,
        {},
        {},
        { status: 503, statusText: 'Service Unavailable' }
      );

      expect(error.status).toBe(503);
    });

    it('error.status is undefined when no response is provided (network errors)', () => {
      // Network errors (ECONNREFUSED, ETIMEDOUT, etc.) have no HTTP response,
      // so error.status must be undefined — not 0 or null.
      const error = new AxiosError('Network Error', AxiosError.ERR_NETWORK, {}, {});

      expect(error.status).toBeUndefined();
      expect(error.response).toBeUndefined();
    });

    it('error.status is included in toJSON output', () => {
      const error = new AxiosError('test', 'ERR_BAD_REQUEST', {}, {}, { status: 401 });

      expect(error.toJSON().status).toBe(401);
    });
  });

  it('keeps message enumerable for backward compatibility', () => {
    const error = new AxiosError('Test error message', 'ERR_TEST', { foo: 'bar' });

    expect(Object.keys(error)).toContain('message');
    expect(Object.entries(error).find(([key]) => key === 'message')?.[1]).toBe('Test error message');
    expect({ ...error }.message).toBe('Test error message');
    expect(Object.getOwnPropertyDescriptor(error, 'message')?.enumerable).toBe(true);
  });

  // Opt-in redaction: when `config.redact` is an array of key names, every
  // matching key (case-insensitive, at any depth) has its value replaced with
  // the redaction marker in the toJSON snapshot. Undefined leaves the legacy
  // serialization untouched so existing consumers see no behavior change.
  describe('toJSON redaction via config.redact', () => {
    it('leaves config untouched when redact is undefined', () => {
      const config = {
        url: '/api',
        auth: { username: 'alice', password: 'secret' },
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      const json = error.toJSON();

      expect(json.config.auth.username).toBe('alice');
      expect(json.config.auth.password).toBe('secret');
    });

    it('ignores inherited redact accessors', () => {
      const prototype = {};
      Object.defineProperty(prototype, 'redact', {
        get() {
          throw new Error('inherited redact getter should not run');
        },
      });

      const config = Object.create(prototype);
      config.auth = { username: 'alice', password: 'secret' };
      const error = new AxiosError('Boom', 'ECODE', config);

      const json = error.toJSON();

      expect(json.config.auth.username).toBe('alice');
      expect(json.config.auth.password).toBe('secret');
    });

    it('leaves config untouched when redact is an empty array', () => {
      const config = {
        auth: { username: 'alice', password: 'secret' },
        redact: [],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      expect(error.toJSON().config.auth.password).toBe('secret');
    });

    it('replaces top-level matching keys with the redaction marker', () => {
      const config = {
        url: '/api',
        auth: { username: 'alice', password: 'secret' },
        redact: ['auth'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      const json = error.toJSON();

      expect(json.config.url).toBe('/api');
      expect(json.config.auth).toBe('[REDACTED ****]');
    });

    it('replaces matching keys at any nesting depth', () => {
      const config = {
        auth: { username: 'alice', password: 'secret' },
        proxy: { auth: { username: 'pu', password: 'pp' } },
        redact: ['password'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      const json = error.toJSON();

      expect(json.config.auth.username).toBe('alice');
      expect(json.config.auth.password).toBe('[REDACTED ****]');
      expect(json.config.proxy.auth.password).toBe('[REDACTED ****]');
      expect(json.config.proxy.auth.username).toBe('pu');
    });

    it('matches case-insensitively', () => {
      const config = {
        headers: { Authorization: 'Bearer abc' },
        redact: ['authorization'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      expect(error.toJSON().config.headers.Authorization).toBe('[REDACTED ****]');
    });

    it('redacts headers stored in an AxiosHeaders instance', () => {
      const headers = new AxiosHeaders();
      headers.set('Authorization', 'Bearer abc');
      headers.set('X-Trace', 'trace-id');

      const config = { headers, redact: ['Authorization'] };
      const error = new AxiosError('Boom', 'ECODE', config);

      const serialized = error.toJSON().config.headers;
      expect(serialized.Authorization).toBe('[REDACTED ****]');
      expect(serialized['X-Trace']).toBe('trace-id');
    });

    it('redacts inside arrays of objects', () => {
      const config = {
        items: [{ token: 't1' }, { token: 't2', name: 'keep' }],
        redact: ['token'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      const json = error.toJSON();
      expect(json.config.items[0].token).toBe('[REDACTED ****]');
      expect(json.config.items[1].token).toBe('[REDACTED ****]');
      expect(json.config.items[1].name).toBe('keep');
    });

    it('does not crash on circular config references', () => {
      const config = { auth: { password: 'secret' }, redact: ['password'] };
      config.self = config;

      const error = new AxiosError('Boom', 'ECODE', config);

      const json = error.toJSON();
      expect(json.config.auth.password).toBe('[REDACTED ****]');
      expect(Object.prototype.hasOwnProperty.call(json.config, 'self')).toBe(false);
    });

    it('preserves legacy toJSONObject handling for values with toJSON', () => {
      const issuedAt = new Date('2026-01-01T00:00:00.000Z');
      const endpoint = new URL('https://example.com/users');
      const config = {
        issuedAt,
        endpoint,
        auth: { password: 'secret' },
        redact: ['password'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      const json = error.toJSON();

      expect(json.config.issuedAt).toBe(issuedAt);
      expect(json.config.endpoint).toBe(endpoint);
      expect(json.config.auth.password).toBe('[REDACTED ****]');
    });

    it('does not let a polluted Object.prototype.toJSON bypass redaction', () => {
      class Credentials {
        constructor() {
          this.password = 'secret';
        }
      }

      Object.prototype.toJSON = function () {
        return this;
      };

      const config = {
        auth: { password: 'secret' },
        credentials: new Credentials(),
        items: [{ token: 't1' }],
        redact: ['password', 'token'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      try {
        const json = error.toJSON();

        expect(json.config.auth.password).toBe('[REDACTED ****]');
        expect(json.config.credentials.password).toBe('[REDACTED ****]');
        expect(json.config.items[0].token).toBe('[REDACTED ****]');
      } finally {
        delete Object.prototype.toJSON;
      }
    });

    it('copies __proto__ as data without changing the redaction output prototype', () => {
      const config = { redact: ['password'] };
      Object.defineProperty(config, '__proto__', {
        value: { password: 'secret' },
        enumerable: true,
        configurable: true,
      });

      const error = new AxiosError('Boom', 'ECODE', config);
      const json = error.toJSON();

      expect(Object.getPrototypeOf(json.config)).toBe(null);
      expect(Object.prototype.hasOwnProperty.call(json.config, '__proto__')).toBe(true);
      expect(json.config.__proto__.password).toBe('[REDACTED ****]');
    });

    it('does not mutate the original config or AxiosHeaders', () => {
      const headers = new AxiosHeaders();
      headers.set('Authorization', 'Bearer abc');

      const config = {
        auth: { username: 'alice', password: 'secret' },
        headers,
        redact: ['password', 'Authorization'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      error.toJSON();

      expect(config.auth.password).toBe('secret');
      expect(headers.get('Authorization')).toBe('Bearer abc');
    });

    it('keeps the redact array itself visible in the snapshot', () => {
      const config = {
        auth: { password: 'secret' },
        redact: ['password'],
      };
      const error = new AxiosError('Boom', 'ECODE', config);

      // Useful for debugging — operators can see what was being redacted.
      expect(error.toJSON().config.redact).toEqual(['password']);
    });
  });
});

import { describe, it, expect } from 'vitest';
import defaults from '../../../lib/defaults/index.js';
import mergeConfig from '../../../lib/core/mergeConfig.js';
import { AxiosHeaders } from '../../../index.js';

describe('core::mergeConfig', () => {
  it('accepts undefined for second argument', () => {
    expect(mergeConfig(defaults, undefined)).toEqual(defaults);
  });

  it('accepts an object for second argument', () => {
    expect(mergeConfig(defaults, {})).toEqual(defaults);
  });

  it('does not leave references', () => {
    const merged = mergeConfig(defaults, {});

    expect(merged).not.toBe(defaults);
    expect(merged.headers).not.toBe(defaults.headers);
  });

  it('allows setting request options', () => {
    const config = {
      url: '__sample url__',
      method: '__sample method__',
      params: '__sample params__',
      data: { foo: true },
    };
    const merged = mergeConfig(defaults, config);

    expect(merged.url).toBe(config.url);
    expect(merged.method).toBe(config.method);
    expect(merged.params).toBe(config.params);
    expect(merged.data).toEqual(config.data);
  });

  it('does not inherit request options', () => {
    const localDefaults = {
      method: '__sample method__',
      data: { foo: true },
    };
    const merged = mergeConfig(localDefaults, {});

    expect(merged.method).toBeUndefined();
    expect(merged.data).toBeUndefined();
  });

  for (const key of ['auth', 'headers', 'params', 'proxy']) {
    it(`sets new config for ${key} without default`, () => {
      const config1 = { [key]: undefined };
      const config2 = { [key]: { user: 'foo', pass: 'test' } };
      const expected = { [key]: { user: 'foo', pass: 'test' } };

      expect(mergeConfig(config1, config2)).toEqual(expected);
    });

    it(`merges ${key} with defaults`, () => {
      const config1 = { [key]: { user: 'foo', pass: 'bar' } };
      const config2 = { [key]: { pass: 'test' } };
      const expected = { [key]: { user: 'foo', pass: 'test' } };

      expect(mergeConfig(config1, config2)).toEqual(expected);
    });

    it.each([false, null, 123])(`overwrites default ${key} with %p`, (value) => {
      const config1 = { [key]: { user: 'foo', pass: 'test' } };
      const config2 = { [key]: value };
      const expected = { [key]: value };

      expect(mergeConfig(config1, config2)).toEqual(expected);
    });
  }

  it('allows setting other options', () => {
    const merged = mergeConfig(defaults, { timeout: 123 });

    expect(merged.timeout).toBe(123);
  });

  it('allows setting custom options', () => {
    const merged = mergeConfig(defaults, { foo: 'bar' });

    expect(merged.foo).toBe('bar');
  });

  it('allows setting custom default options', () => {
    const merged = mergeConfig({ foo: 'bar' }, {});

    expect(merged.foo).toBe('bar');
  });

  it('allows merging custom objects in config', () => {
    const merged = mergeConfig(
      {
        nestedConfig: {
          propertyOnDefaultConfig: true,
        },
      },
      {
        nestedConfig: {
          propertyOnRequestConfig: true,
        },
      }
    );

    expect(merged.nestedConfig.propertyOnDefaultConfig).toBe(true);
    expect(merged.nestedConfig.propertyOnRequestConfig).toBe(true);
  });

  describe('headers', () => {
    it('allows merging with AxiosHeaders instances', () => {
      const merged = mergeConfig(
        {
          headers: new AxiosHeaders({
            x: 1,
            y: 2,
          }),
        },
        {
          headers: new AxiosHeaders({
            X: 1,
            Y: 2,
          }),
        }
      );

      expect(merged.headers).toEqual({
        x: '1',
        y: '2',
      });
    });
  });

  describe('valueFromConfig2Keys', () => {
    const config1 = { url: '/foo', method: 'post', data: { a: 3 } };

    it('skips if config2 does not define the key', () => {
      expect(mergeConfig(config1, {})).toEqual({});
    });

    it('clones config2 when it is a plain object', () => {
      const data = { a: 1, b: 2 };
      const merged = mergeConfig(config1, { data });

      expect(merged.data).toEqual(data);
      expect(merged.data).not.toBe(data);
    });

    it('clones config2 when it is an array', () => {
      const data = [1, 2, 3];
      const merged = mergeConfig(config1, { data });

      expect(merged.data).toEqual(data);
      expect(merged.data).not.toBe(data);
    });

    it('sets config2 value directly for non-mergeable values', () => {
      const obj = Object.create({});

      expect(mergeConfig(config1, { data: 1 }).data).toBe(1);
      expect(mergeConfig(config1, { data: 'str' }).data).toBe('str');
      expect(mergeConfig(config1, { data: obj }).data).toBe(obj);
      expect(mergeConfig(config1, { data: null }).data).toBe(null);
    });
  });

  describe('mergeDeepPropertiesKeys', () => {
    it('skips when both config1 and config2 values are undefined', () => {
      expect(mergeConfig({ headers: undefined }, { headers: undefined })).toEqual({});
    });

    it('merges when both values are plain objects', () => {
      expect(mergeConfig({ headers: { a: 1, b: 1 } }, { headers: { b: 2, c: 2 } })).toEqual({
        headers: { a: 1, b: 2, c: 2 },
      });
    });

    it('clones config2 when it is a plain object', () => {
      const config1 = { headers: [1, 2, 3] };
      const config2 = { headers: { a: 1, b: 2 } };
      const merged = mergeConfig(config1, config2);

      expect(merged.headers).toEqual(config2.headers);
      expect(merged.headers).not.toBe(config2.headers);
    });

    it('clones config2 when it is an array', () => {
      const config1 = { headers: { a: 1, b: 1 } };
      const config2 = { headers: [1, 2, 3] };
      const merged = mergeConfig(config1, config2);

      expect(merged.headers).toEqual(config2.headers);
      expect(merged.headers).not.toBe(config2.headers);
    });

    it('sets config2 value directly for non-mergeable values', () => {
      const config1 = { headers: { a: 1, b: 1 } };
      const obj = Object.create({});

      expect(mergeConfig(config1, { headers: 1 }).headers).toBe(1);
      expect(mergeConfig(config1, { headers: 'str' }).headers).toBe('str');
      expect(mergeConfig(config1, { headers: obj }).headers).toBe(obj);
      expect(mergeConfig(config1, { headers: null }).headers).toBe(null);
    });

    it('clones config1 when it is a plain object', () => {
      const config1 = { headers: { a: 1, b: 2 } };
      const merged = mergeConfig(config1, {});

      expect(merged.headers).toEqual(config1.headers);
      expect(merged.headers).not.toBe(config1.headers);
    });

    it('clones config1 when it is an array', () => {
      const config1 = { headers: [1, 2, 3] };
      const merged = mergeConfig(config1, {});

      expect(merged.headers).toEqual(config1.headers);
      expect(merged.headers).not.toBe(config1.headers);
    });

    it('sets config1 value directly for non-mergeable values', () => {
      const obj = Object.create({});

      expect(mergeConfig({ headers: 1 }, {}).headers).toBe(1);
      expect(mergeConfig({ headers: 'str' }, {}).headers).toBe('str');
      expect(mergeConfig({ headers: obj }, {}).headers).toBe(obj);
      expect(mergeConfig({ headers: null }, {}).headers).toBe(null);
    });
  });

  describe('defaultToConfig2Keys', () => {
    it('skips when both config1 and config2 values are undefined', () => {
      expect(mergeConfig({ transformRequest: undefined }, { transformRequest: undefined })).toEqual(
        {}
      );
    });

    it('clones config2 when both values are plain objects', () => {
      const config1 = { transformRequest: { a: 1, b: 1 } };
      const config2 = { transformRequest: { b: 2, c: 2 } };
      const merged = mergeConfig(config1, config2);

      expect(merged.transformRequest).toEqual(config2.transformRequest);
      expect(merged.transformRequest).not.toBe(config2.transformRequest);
    });

    it('clones config2 when it is an array', () => {
      const config1 = { transformRequest: { a: 1, b: 1 } };
      const config2 = { transformRequest: [1, 2, 3] };
      const merged = mergeConfig(config1, config2);

      expect(merged.transformRequest).toEqual(config2.transformRequest);
      expect(merged.transformRequest).not.toBe(config2.transformRequest);
    });

    it('sets config2 value directly for non-mergeable values', () => {
      const config1 = { transformRequest: { a: 1, b: 1 } };
      const obj = Object.create({});

      expect(mergeConfig(config1, { transformRequest: 1 }).transformRequest).toBe(1);
      expect(mergeConfig(config1, { transformRequest: 'str' }).transformRequest).toBe('str');
      expect(mergeConfig(config1, { transformRequest: obj }).transformRequest).toBe(obj);
      expect(mergeConfig(config1, { transformRequest: null }).transformRequest).toBe(null);
    });

    it('clones config1 when it is a plain object', () => {
      const config1 = { transformRequest: { a: 1, b: 2 } };
      const merged = mergeConfig(config1, {});

      expect(merged.transformRequest).toEqual(config1.transformRequest);
      expect(merged.transformRequest).not.toBe(config1.transformRequest);
    });

    it('clones config1 when it is an array', () => {
      const config1 = { transformRequest: [1, 2, 3] };
      const merged = mergeConfig(config1, {});

      expect(merged.transformRequest).toEqual(config1.transformRequest);
      expect(merged.transformRequest).not.toBe(config1.transformRequest);
    });

    it('sets config1 value directly for non-mergeable values', () => {
      const obj = Object.create({});

      expect(mergeConfig({ transformRequest: 1 }, {}).transformRequest).toBe(1);
      expect(mergeConfig({ transformRequest: 'str' }, {}).transformRequest).toBe('str');
      expect(mergeConfig({ transformRequest: obj }, {}).transformRequest).toBe(obj);
      expect(mergeConfig({ transformRequest: null }, {}).transformRequest).toBe(null);
    });
  });

  describe('directMergeKeys', () => {
    it('merges when config2 defines the key', () => {
      expect(mergeConfig({}, { validateStatus: undefined })).toEqual({ validateStatus: undefined });
    });

    it('merges when both values are plain objects', () => {
      expect(
        mergeConfig({ validateStatus: { a: 1, b: 1 } }, { validateStatus: { b: 2, c: 2 } })
      ).toEqual({ validateStatus: { a: 1, b: 2, c: 2 } });
    });

    it('clones config2 when it is a plain object', () => {
      const config1 = { validateStatus: [1, 2, 3] };
      const config2 = { validateStatus: { a: 1, b: 2 } };
      const merged = mergeConfig(config1, config2);

      expect(merged.validateStatus).toEqual(config2.validateStatus);
      expect(merged.validateStatus).not.toBe(config2.validateStatus);
    });

    it('clones config2 when it is an array', () => {
      const config1 = { validateStatus: { a: 1, b: 2 } };
      const config2 = { validateStatus: [1, 2, 3] };
      const merged = mergeConfig(config1, config2);

      expect(merged.validateStatus).toEqual(config2.validateStatus);
      expect(merged.validateStatus).not.toBe(config2.validateStatus);
    });

    it('sets config2 value directly for non-mergeable values', () => {
      const config1 = { validateStatus: { a: 1, b: 2 } };
      const obj = Object.create({});

      expect(mergeConfig(config1, { validateStatus: 1 }).validateStatus).toBe(1);
      expect(mergeConfig(config1, { validateStatus: 'str' }).validateStatus).toBe('str');
      expect(mergeConfig(config1, { validateStatus: obj }).validateStatus).toBe(obj);
      expect(mergeConfig(config1, { validateStatus: null }).validateStatus).toBe(null);
    });

    it('clones config1 when it is a plain object', () => {
      const config1 = { validateStatus: { a: 1, b: 2 } };
      const merged = mergeConfig(config1, {});

      expect(merged.validateStatus).toEqual(config1.validateStatus);
      expect(merged.validateStatus).not.toBe(config1.validateStatus);
    });

    it('clones config1 when it is an array', () => {
      const config1 = { validateStatus: [1, 2, 3] };
      const merged = mergeConfig(config1, {});

      expect(merged.validateStatus).toEqual(config1.validateStatus);
      expect(merged.validateStatus).not.toBe(config1.validateStatus);
    });

    it('sets config1 value directly for non-mergeable values', () => {
      const obj = Object.create({});

      expect(mergeConfig({ validateStatus: 1 }, {}).validateStatus).toBe(1);
      expect(mergeConfig({ validateStatus: 'str' }, {}).validateStatus).toBe('str');
      expect(mergeConfig({ validateStatus: obj }, {}).validateStatus).toBe(obj);
      expect(mergeConfig({ validateStatus: null }, {}).validateStatus).toBe(null);
    });

    it('keeps legacy undefined behavior by default', () => {
      expect(mergeConfig(defaults, { validateStatus: undefined }).validateStatus).toBeUndefined();
    });

    it('keeps config1 value when the transitional option is disabled (issue #6688)', () => {
      const validateStatus = () => false;

      expect(
        mergeConfig(
          { validateStatus },
          {
            validateStatus: undefined,
            transitional: { validateStatusUndefinedResolves: false },
          }
        ).validateStatus
      ).toBe(validateStatus);

      expect(mergeConfig(defaults, { validateStatus: null }).validateStatus).toBe(null);
    });
  });
});

import { describe, it, expect, vi } from 'vitest';
import settle from '../../../lib/core/settle.js';
import AxiosError from '../../../lib/core/AxiosError.js';

/**
 * Builds a minimal response object that settle() expects.
 * @param {number} status - HTTP status code
 * @param {Function} [validateStatus] - optional custom validator
 */
function makeResponse(status, validateStatus = (s) => s >= 200 && s < 300) {
  return {
    status,
    config: { validateStatus },
    request: {},
    data: null,
    headers: {},
  };
}

describe('core::settle', () => {
  describe('resolves the promise', () => {
    it('resolves for a 200 status by default', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(200));
      expect(resolve).toHaveBeenCalledTimes(1);
      expect(reject).not.toHaveBeenCalled();
    });

    it('resolves when validateStatus is not provided', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      const response = makeResponse(500);
      response.config.validateStatus = null;
      settle(resolve, reject, response);
      expect(resolve).toHaveBeenCalledTimes(1);
    });

    it('resolves when status is 0 (no response, e.g. network error)', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      const response = makeResponse(0);
      settle(resolve, reject, response);
      expect(resolve).toHaveBeenCalledTimes(1);
    });
  });

  describe('error code assignment', () => {
    it('assigns ERR_BAD_REQUEST for a 400 status', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(400, () => false));
      expect(reject).toHaveBeenCalledTimes(1);
      const error = reject.mock.calls[0][0];
      expect(error).toBeInstanceOf(AxiosError);
      expect(error.code).toBe(AxiosError.ERR_BAD_REQUEST);
    });

    it('assigns ERR_BAD_REQUEST for a 404 status', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(404, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.code).toBe(AxiosError.ERR_BAD_REQUEST);
    });

    it('assigns ERR_BAD_REQUEST for a 499 status (top of 4xx range)', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(499, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.code).toBe(AxiosError.ERR_BAD_REQUEST);
    });

    it('assigns ERR_BAD_RESPONSE for a 500 status', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(500, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.code).toBe(AxiosError.ERR_BAD_RESPONSE);
    });

    it('assigns ERR_BAD_RESPONSE for a 503 status', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(503, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.code).toBe(AxiosError.ERR_BAD_RESPONSE);
    });

    // A custom validateStatus can reject any status — including 1xx, 2xx, 3xx,
    // or ≥ 600 — and the resulting AxiosError must always have a defined code.
    it('assigns ERR_BAD_RESPONSE for a 3xx status rejected via custom validateStatus', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(301, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.code).toBeDefined();
      expect(error.code).toBe(AxiosError.ERR_BAD_RESPONSE);
    });

    it('assigns ERR_BAD_RESPONSE for a 2xx status rejected via custom validateStatus', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(200, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.code).toBeDefined();
      expect(error.code).toBe(AxiosError.ERR_BAD_RESPONSE);
    });

    it('assigns ERR_BAD_RESPONSE for a 6xx status rejected via custom validateStatus', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(600, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.code).toBeDefined();
      expect(error.code).toBe(AxiosError.ERR_BAD_RESPONSE);
    });
  });

  describe('error message', () => {
    it('includes the status code in the error message', () => {
      const resolve = vi.fn();
      const reject = vi.fn();
      settle(resolve, reject, makeResponse(404, () => false));
      const error = reject.mock.calls[0][0];
      expect(error.message).toBe('Request failed with status code 404');
    });
  });
});

