import { describe, it, expect } from 'vitest';
import utils from '../../../lib/utils.js';

const { merge } = utils;

describe('utils::merge', () => {
  it('should be immutable', () => {
    const a = {};
    const b = { foo: 123 };
    const c = { bar: 456 };

    merge(a, b, c);

    expect(typeof a.foo).toEqual('undefined');
    expect(typeof a.bar).toEqual('undefined');
    expect(typeof b.bar).toEqual('undefined');
    expect(typeof c.foo).toEqual('undefined');
  });

  it('should merge properties', () => {
    const a = { foo: 123 };
    const b = { bar: 456 };
    const c = { foo: 789 };
    const d = merge(a, b, c);

    expect(d.foo).toEqual(789);
    expect(d.bar).toEqual(456);
  });

  it('should merge recursively', () => {
    const a = { foo: { bar: 123 } };
    const b = { foo: { baz: 456 }, bar: { qux: 789 } };

    expect(merge(a, b)).toEqual({
      foo: {
        bar: 123,
        baz: 456,
      },
      bar: {
        qux: 789,
      },
    });
  });

  it('should remove all references from nested objects', () => {
    const a = { foo: { bar: 123 } };
    const b = {};
    const d = merge(a, b);

    expect(d).toEqual({
      foo: {
        bar: 123,
      },
    });

    expect(d.foo).not.toBe(a.foo);
  });

  it('handles null and undefined arguments', () => {
    expect(merge(undefined, undefined)).toEqual({});
    expect(merge(undefined, { foo: 123 })).toEqual({ foo: 123 });
    expect(merge({ foo: 123 }, undefined)).toEqual({ foo: 123 });

    expect(merge(null, null)).toEqual({});
    expect(merge(null, { foo: 123 })).toEqual({ foo: 123 });
    expect(merge({ foo: 123 }, null)).toEqual({ foo: 123 });
  });

  it('should replace properties with null', () => {
    expect(merge({}, { a: null })).toEqual({ a: null });
    expect(merge({ a: null }, {})).toEqual({ a: null });
  });

  it('should replace properties with arrays', () => {
    expect(merge({}, { a: [1, 2, 3] })).toEqual({ a: [1, 2, 3] });
    expect(merge({ a: 2 }, { a: [1, 2, 3] })).toEqual({ a: [1, 2, 3] });
    expect(merge({ a: { b: 2 } }, { a: [1, 2, 3] })).toEqual({ a: [1, 2, 3] });
  });

  it('should replace properties with cloned arrays', () => {
    const a = [1, 2, 3];
    const d = merge({}, { a });

    expect(d).toEqual({ a: [1, 2, 3] });
    expect(d.a).not.toBe(a);
  });

  it('should support caseless option', () => {
    const a = { x: 1 };
    const b = { X: 2 };
    const merged = merge.call({ caseless: true }, a, b);

    expect(merged).toEqual({
      x: 2,
    });
  });

  it('should merge enumerable symbol keys', () => {
    const key = Symbol('key');
    const nestedKey = Symbol('nested');
    const first = { [key]: { first: true } };
    const second = {
      [key]: { second: true },
      nested: {
        [nestedKey]: 'value',
      },
    };
    const merged = merge(first, second);

    expect(merged[key]).toEqual({ first: true, second: true });
    expect(merged[key]).not.toBe(first[key]);
    expect(merged.nested[nestedKey]).toBe('value');
    expect(merged.nested).not.toBe(second.nested);
  });

  it('should skip non-enumerable symbol keys', () => {
    const key = Symbol('key');
    const source = {};

    Object.defineProperty(source, key, {
      value: 'hidden',
      enumerable: false,
    });

    const merged = merge(source);

    expect(merged[key]).toBeUndefined();
    expect(Object.getOwnPropertySymbols(merged)).toEqual([]);
  });

  it('should support caseless string keys with symbol keys', () => {
    const key = Symbol('key');
    const merged = merge.call(
      { caseless: true },
      { x: 1, [key]: 'first' },
      { X: 2, [key]: 'second' }
    );

    expect(merged.x).toBe(2);
    expect(merged.X).toBeUndefined();
    expect(merged[key]).toBe('second');
  });

  it('should ignore symbol keys on buffers', () => {
    const key = Symbol('key');
    const buffer = Buffer.from('value');
    buffer[key] = 'symbol value';

    const merged = merge({ x: 1 }, buffer);

    expect(merged).toEqual({ x: 1 });
  });

  it('should ignore symbol keys on arrays', () => {
    const key = Symbol('key');
    const array = ['value'];
    array[key] = 'symbol value';

    const merged = merge({ x: 1 }, array);

    expect(merged).toEqual({ 0: 'value', x: 1 });
    expect(merged[key]).toBeUndefined();
  });

  it('should honor skipUndefined for symbol keys', () => {
    const key = Symbol('key');
    const merged = merge.call({ skipUndefined: true }, { [key]: 'first' }, { [key]: undefined });

    expect(merged[key]).toBe('first');
  });
});

import { describe, it, expect } from 'vitest';
import utils from '../../../lib/utils.js';

const { extend } = utils;

describe('utils::extend', () => {
  it('should be mutable', () => {
    const a = {};
    const b = { foo: 123 };

    extend(a, b);

    expect(a.foo).toEqual(b.foo);
  });

  it('should extend properties', () => {
    let a = { foo: 123, bar: 456 };
    const b = { bar: 789 };

    a = extend(a, b);

    expect(a.foo).toEqual(123);
    expect(a.bar).toEqual(789);
  });

  it('should bind to thisArg', () => {
    const a = {};
    const b = {
      getFoo: function getFoo() {
        return this.foo;
      },
    };
    const thisArg = { foo: 'barbaz' };

    extend(a, b, thisArg);

    expect(typeof a.getFoo).toEqual('function');
    expect(a.getFoo()).toEqual(thisArg.foo);
  });
});

import { describe, it, expect } from 'vitest';
import utils from '../../../lib/utils.js';

const { forEach } = utils;

describe('utils::forEach', () => {
  it('should loop over an array', () => {
    let sum = 0;

    forEach([1, 2, 3, 4, 5], (val) => {
      sum += val;
    });

    expect(sum).toEqual(15);
  });

  it('should loop over object keys', () => {
    let keys = '';
    let vals = 0;
    const obj = {
      b: 1,
      a: 2,
      r: 3,
    };

    forEach(obj, (v, k) => {
      keys += k;
      vals += v;
    });

    expect(keys).toEqual('bar');
    expect(vals).toEqual(6);
  });

  it('should handle undefined gracefully', () => {
    let count = 0;

    forEach(undefined, () => {
      count++;
    });

    expect(count).toEqual(0);
  });

  it('should make an array out of non-array argument', () => {
    let count = 0;

    forEach(
      () => {},
      () => {
        count++;
      }
    );

    expect(count).toEqual(1);
  });

  it('should handle non object prototype gracefully', () => {
    let count = 0;
    const data = Object.create(null);
    data.foo = 'bar';

    forEach(data, () => {
      count++;
    });

    expect(count).toEqual(1);
  });
});

import { describe, it, expect } from 'vitest';
import utils from '../../../lib/utils.js';

describe('utils::isX', () => {
  it('should validate Array', () => {
    expect(utils.isArray([])).toEqual(true);
    expect(utils.isArray({ length: 5 })).toEqual(false);
  });

  it('should validate ArrayBuffer', () => {
    expect(utils.isArrayBuffer(new ArrayBuffer(2))).toEqual(true);
    expect(utils.isArrayBuffer({})).toEqual(false);
  });

  it('should validate ArrayBufferView', () => {
    expect(utils.isArrayBufferView(new DataView(new ArrayBuffer(2)))).toEqual(true);
  });

  it('should validate FormData', () => {
    expect(utils.isFormData(new FormData())).toEqual(true);
  });

  it('should validate Blob', () => {
    expect(utils.isBlob(new Blob())).toEqual(true);
  });

  it('should validate String', () => {
    expect(utils.isString('')).toEqual(true);
    expect(
      utils.isString({
        toString: function () {
          return '';
        },
      })
    ).toEqual(false);
  });

  it('should validate Number', () => {
    expect(utils.isNumber(123)).toEqual(true);
    expect(utils.isNumber('123')).toEqual(false);
  });

  it('should validate Undefined', () => {
    expect(utils.isUndefined()).toEqual(true);
    expect(utils.isUndefined(null)).toEqual(false);
  });

  it('should validate Object', () => {
    expect(utils.isObject({})).toEqual(true);
    expect(utils.isObject([])).toEqual(true);
    expect(utils.isObject(null)).toEqual(false);
  });

  it('should validate plain Object', () => {
    expect(utils.isPlainObject({})).toEqual(true);
    expect(utils.isPlainObject([])).toEqual(false);
    expect(utils.isPlainObject(null)).toEqual(false);
    expect(utils.isPlainObject(Object.create({}))).toEqual(false);
  });

  it('should ignore inherited symbol properties when validating plain Object', () => {
    try {
      Object.prototype[Symbol.iterator] = function* () {
        yield ['x-injected', 'yes'];
      };
      Object.prototype[Symbol.toStringTag] = 'Custom';

      expect(utils.isPlainObject({})).toEqual(true);
      expect(utils.isPlainObject([])).toEqual(false);
      expect(
        utils.isPlainObject({
          [Symbol.iterator]: function* () {
            yield ['x-own', 'yes'];
          },
        })
      ).toEqual(false);
      expect(
        utils.isPlainObject({
          [Symbol.toStringTag]: 'Custom',
        })
      ).toEqual(false);
    } finally {
      delete Object.prototype[Symbol.iterator];
      delete Object.prototype[Symbol.toStringTag];
    }
  });

  it('should treat an object with a genuinely inherited iterator as non-plain', () => {
    // Iterator inherited from a custom (non-Object.prototype) source: this is a
    // real iterable, not prototype pollution, so it must not be classified plain.
    const proto = Object.create(null);
    proto[Symbol.iterator] = function* () {
      yield ['x', '1'];
    };

    expect(utils.isPlainObject(Object.create(proto))).toEqual(false);
  });

  it('should not read polluted Object.prototype iterator accessors for safe iterable checks', () => {
    let accessed = false;

    try {
      Object.defineProperty(Object.prototype, Symbol.iterator, {
        configurable: true,
        get() {
          accessed = true;
          throw new Error('polluted iterator accessor');
        }
      });

      expect(utils.isSafeIterable({})).toEqual(false);
      expect(accessed).toEqual(false);
    } finally {
      delete Object.prototype[Symbol.iterator];
    }
  });

  it('should stop safe prototype-chain reads on cyclic Proxy prototypes', () => {
    let calls = 0;
    let proxy;
    proxy = new Proxy({}, {
      getPrototypeOf() {
        calls += 1;
        if (calls > 5) {
          throw new Error('cycled');
        }
        return proxy;
      }
    });

    expect(utils.hasOwnInPrototypeChain(proxy, 'missing')).toEqual(false);
    expect(utils.getSafeProp(proxy, 'missing')).toEqual(undefined);
    expect(calls).toBeLessThanOrEqual(2);
  });

  it('should validate Date', () => {
    expect(utils.isDate(new Date())).toEqual(true);
    expect(utils.isDate(Date.now())).toEqual(false);
  });

  it('should validate Function', () => {
    expect(utils.isFunction(function () {})).toEqual(true);
    expect(utils.isFunction('function')).toEqual(false);
  });

  it('should validate URLSearchParams', () => {
    expect(utils.isURLSearchParams(new URLSearchParams())).toEqual(true);
    expect(utils.isURLSearchParams('foo=1&bar=2')).toEqual(false);
  });

  it('should validate TypedArray instance', () => {
    expect(utils.isTypedArray(new Uint8Array([1, 2, 3]))).toEqual(true);
    expect(utils.isTypedArray([1, 2, 3])).toEqual(false);
  });
});

import { describe, it } from 'vitest';
import assert from 'assert';
import https from 'https';
import net from 'net';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import axios from '../../../index.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const getClosedPort = async () => {
  return await new Promise((resolve) => {
    const srv = net.createServer();
    srv.listen(0, '127.0.0.1', () => {
      const { port } = srv.address();
      srv.close(() => resolve(port));
    });
  });
};

describe('adapters - network-error details', () => {
  it('should expose ECONNREFUSED and set error.cause on connection refusal', async () => {
    const port = await getClosedPort();

    try {
      await axios.get(`http://127.0.0.1:${port}`, { timeout: 500 });
      assert.fail('request unexpectedly succeeded');
    } catch (err) {
      assert.ok(err instanceof Error, 'should be an Error');
      assert.strictEqual(err.isAxiosError, true, 'isAxiosError should be true');

      assert.strictEqual(err.code, 'ECONNREFUSED');
      assert.ok('cause' in err, 'error.cause should exist');
      assert.ok(err.cause instanceof Error, 'cause should be an Error');
      assert.strictEqual(err.cause && err.cause.code, 'ECONNREFUSED');

      assert.strictEqual(typeof err.message, 'string');
    }
  });

  it('should expose self-signed TLS error and set error.cause', async () => {
    const certsDir = path.resolve(__dirname, '../../../tests/unit/adapters/');
    const keyPath = path.join(certsDir, 'key.pem');
    const certPath = path.join(certsDir, 'cert.pem');

    const key = fs.readFileSync(keyPath);
    const cert = fs.readFileSync(certPath);

    const httpsServer = https.createServer({ key, cert }, (req, res) => res.end('ok'));

    await new Promise((resolve) => httpsServer.listen(0, '127.0.0.1', resolve));
    const { port } = httpsServer.address();

    try {
      await axios.get(`https://127.0.0.1:${port}`, {
        timeout: 500,
        httpsAgent: new https.Agent({ rejectUnauthorized: true }),
      });
      assert.fail('request unexpectedly succeeded');
    } catch (err) {
      const codeStr = String(err.code);
      assert.ok(
        /SELF_SIGNED|UNABLE_TO_VERIFY_LEAF_SIGNATURE|DEPTH_ZERO/.test(codeStr),
        `unexpected TLS code: ${codeStr}`
      );

      assert.ok('cause' in err, 'error.cause should exist');
      assert.ok(err.cause instanceof Error, 'cause should be an Error');

      const causeCode = String(err.cause && err.cause.code);
      assert.ok(
        /SELF_SIGNED|UNABLE_TO_VERIFY_LEAF_SIGNATURE|DEPTH_ZERO/.test(causeCode),
        `unexpected cause code: ${causeCode}`
      );

      assert.strictEqual(typeof err.message, 'string');
    } finally {
      await new Promise((resolve) => httpsServer.close(resolve));
    }
  });
});

import { describe, it, vi } from 'vitest';
import assert from 'assert';
import {
  startHTTPServer,
  stopHTTPServer,
  setTimeoutAsync,
  makeReadableStream,
  generateReadable,
  makeEchoStream,
} from '../../setup/server.js';
import axios from '../../../index.js';
import AxiosError from '../../../lib/core/AxiosError.js';
import utils from '../../../lib/utils.js';
import { getFetch } from '../../../lib/adapters/fetch.js';
import stream from 'stream';
import { AbortController } from 'abortcontroller-polyfill/dist/cjs-ponyfill.js';
import util from 'util';
import NodeFormData from 'form-data';
import { VERSION } from '../../../lib/env/data.js';

const SERVER_PORT = 8010;
const LOCAL_SERVER_URL = `http://localhost:${SERVER_PORT}`;

const pipelineAsync = util.promisify(stream.pipeline);

const fetchAxios = axios.create({
  baseURL: LOCAL_SERVER_URL,
  adapter: 'fetch',
});

const getFetchSignal = (input, init) => (init && init.signal) || (input && input.signal);

const createBrokenDOMExceptionLikeError = () =>
  Object.defineProperties(
    {},
    {
      name: {
        get() {
          throw new TypeError(
            'The DOMException.name getter can only be used on instances of DOMException'
          );
        },
      },
      message: {
        get() {
          throw new TypeError(
            'The DOMException.message getter can only be used on instances of DOMException'
          );
        },
      },
    }
  );

describe.runIf(typeof fetch === 'function')('supports fetch with nodejs', () => {
  it('rejects malformed HTTP URLs before fetch normalization and preserves config', async () => {
    for (const url of ['\u0000https:example.com/users', 'h\nttp:example.com/users']) {
      await assert.rejects(
        () =>
          axios.get(url, {
            adapter: 'fetch',
            headers: {
              'X-Test': 'yes',
            },
          }),
        (error) => {
          assert.ok(error instanceof AxiosError);
          assert.strictEqual(error.code, AxiosError.ERR_INVALID_URL);
          assert.strictEqual(error.message, 'Invalid URL: missing "//" after protocol');
          assert.strictEqual(error.config.url, url);
          assert.strictEqual(error.config.headers.get('X-Test'), 'yes');
          return true;
        }
      );
    }
  });

  it('should sanitize request headers containing CRLF characters', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.setHeader('Content-Type', 'application/json');
        res.end(
          JSON.stringify({
            xTest: req.headers['x-test'],
            injected: req.headers.injected ?? null,
          })
        );
      },
      {
        port: SERVER_PORT,
      }
    );

    try {
      const { data } = await fetchAxios.get(`${LOCAL_SERVER_URL}/`, {
        headers: {
          'x-test': '\tok\r\nInjected: yes ',
        },
      });

      assert.strictEqual(data.xTest, 'okInjected: yes');
      assert.strictEqual(data.injected, null);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should not use inherited Symbol.iterator for request headers', async () => {
    const server = await startHTTPServer((req, res) => {
      res.setHeader('Content-Type', 'application/json');
      res.end(
        JSON.stringify({
          authorization: req.headers.authorization,
          xApp: req.headers['x-app'],
          xInjected: req.headers['x-injected'] ?? null,
        })
      );
    });

    try {
      Object.prototype[Symbol.iterator] = function* () {
        yield ['X-Injected', 'yes'];
        yield ['Authorization', 'Bearer CHANGED'];
      };

      const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
        headers: {
          Authorization: 'Bearer VALID_USER_TOKEN',
          'X-App': 'safe',
        },
      });

      assert.strictEqual(data.authorization, 'Bearer VALID_USER_TOKEN');
      assert.strictEqual(data.xApp, 'safe');
      assert.strictEqual(data.xInjected, null);
    } finally {
      delete Object.prototype[Symbol.iterator];
      await stopHTTPServer(server);
    }
  });

  it('should allow request interceptors to encode Unicode header values before fetch sends them', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.setHeader('Content-Type', 'application/json');
        res.end(
          JSON.stringify({
            oprtName: req.headers.oprtname,
          })
        );
      },
      {
        port: SERVER_PORT,
      }
    );

    const instance = axios.create({
      baseURL: LOCAL_SERVER_URL,
      adapter: 'fetch',
    });

    instance.interceptors.request.use((config) => {
      config.headers.oprtName = encodeURIComponent(config.headers.oprtName);
      return config;
    });

    try {
      const { data } = await instance.get('/', {
        headers: {
          oprtName: '请求用户',
        },
      });

      assert.strictEqual(data.oprtName, encodeURIComponent('请求用户'));
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should sanitize unencoded Unicode headers before passing them to fetch', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.setHeader('Content-Type', 'application/json');
        res.end(
          JSON.stringify({
            xTest: req.headers['x-test'],
          })
        );
      },
      {
        port: SERVER_PORT,
      }
    );

    try {
      const { data } = await fetchAxios.get(`${LOCAL_SERVER_URL}/`, {
        headers: {
          'x-test': '请求用户',
        },
      });

      assert.strictEqual(data.xTest, '');
    } finally {
      await stopHTTPServer(server);
    }
  });

  describe('responses', () => {
    it('should support text response type', async () => {
      const originalData = 'my data';

      const server = await startHTTPServer((req, res) => res.end(originalData), {
        port: SERVER_PORT,
      });

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          responseType: 'text',
        });

        assert.deepStrictEqual(data, originalData);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should support arraybuffer response type', async () => {
      const originalData = 'my data';

      const server = await startHTTPServer((req, res) => res.end(originalData), {
        port: SERVER_PORT,
      });

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          responseType: 'arraybuffer',
        });

        assert.deepStrictEqual(
          data,
          Uint8Array.from(await new TextEncoder().encode(originalData)).buffer
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should support blob response type', async () => {
      const originalData = 'my data';

      const server = await startHTTPServer((req, res) => res.end(originalData), {
        port: SERVER_PORT,
      });

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          responseType: 'blob',
        });

        assert.deepStrictEqual(data, new Blob([originalData]));
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should support stream response type', async () => {
      const originalData = 'my data';

      const server = await startHTTPServer((req, res) => res.end(originalData), {
        port: SERVER_PORT,
      });

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          responseType: 'stream',
        });

        assert.ok(data instanceof ReadableStream, 'data is not instanceof ReadableStream');

        const response = new Response(data);

        assert.deepStrictEqual(await response.text(), originalData);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should support formData response type', async () => {
      const originalData = new FormData();

      originalData.append('x', '123');

      const server = await startHTTPServer(
        async (req, res) => {
          const response = await new Response(originalData);

          res.setHeader('Content-Type', response.headers.get('Content-Type'));

          res.end(await response.text());
        },
        { port: SERVER_PORT }
      );

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          responseType: 'formdata',
        });

        assert.ok(data instanceof FormData, 'data is not instanceof FormData');

        assert.deepStrictEqual(
          Object.fromEntries(data.entries()),
          Object.fromEntries(originalData.entries())
        );
      } finally {
        await stopHTTPServer(server);
      }
    }, 5000);

    it('should support json response type', async () => {
      const originalData = { x: 'my data' };

      const server = await startHTTPServer((req, res) => res.end(JSON.stringify(originalData)), {
        port: SERVER_PORT,
      });

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          responseType: 'json',
        });

        assert.deepStrictEqual(data, originalData);
      } finally {
        await stopHTTPServer(server);
      }
    });
  });

  describe('progress', () => {
    describe('upload', () => {
      it('should support upload progress capturing', async () => {
        const server = await startHTTPServer(
          {
            rate: 100 * 1024,
          },
          { port: SERVER_PORT }
        );

        try {
          let content = '';
          const count = 10;
          const chunk = 'test';
          const chunkLength = Buffer.byteLength(chunk);
          const contentLength = count * chunkLength;

          const readable = stream.Readable.from(
            (async function* () {
              let i = count;

              while (i-- > 0) {
                await setTimeoutAsync(1100);
                content += chunk;
                yield chunk;
              }
            })()
          );

          const samples = [];

          const { data } = await fetchAxios.post(
            `http://localhost:${server.address().port}/`,
            readable,
            {
              onUploadProgress: ({ loaded, total, progress, bytes, upload }) => {
                console.log(
                  `Upload Progress ${loaded} from ${total} bytes (${(progress * 100).toFixed(1)}%)`
                );

                samples.push({
                  loaded,
                  total,
                  progress,
                  bytes,
                  upload,
                });
              },
              headers: {
                'Content-Length': contentLength,
              },
              responseType: 'text',
            }
          );

          await setTimeoutAsync(500);

          assert.strictEqual(data, content);

          assert.deepStrictEqual(
            samples,
            Array.from(
              (function* () {
                for (let i = 1; i <= 10; i++) {
                  yield {
                    loaded: chunkLength * i,
                    total: contentLength,
                    progress: (chunkLength * i) / contentLength,
                    bytes: 4,
                    upload: true,
                  };
                }
              })()
            )
          );
        } finally {
          await stopHTTPServer(server);
        }
      }, 15000);

      it('should not fail with get method', async () => {
        const server = await startHTTPServer((req, res) => res.end('OK'), { port: SERVER_PORT });

        try {
          const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
            onUploadProgress() {},
          });

          assert.strictEqual(data, 'OK');
        } finally {
          await stopHTTPServer(server);
        }
      });
    });

    describe('download', () => {
      it('should support download progress capturing', async () => {
        const server = await startHTTPServer(
          {
            rate: 100 * 1024,
          },
          {
            port: SERVER_PORT,
          }
        );

        try {
          let content = '';
          const count = 10;
          const chunk = 'test';
          const chunkLength = Buffer.byteLength(chunk);
          const contentLength = count * chunkLength;

          const readable = stream.Readable.from(
            (async function* () {
              let i = count;

              while (i-- > 0) {
                await setTimeoutAsync(1100);
                content += chunk;
                yield chunk;
              }
            })()
          );

          const samples = [];

          const { data } = await fetchAxios.post(
            `http://localhost:${server.address().port}/`,
            readable,
            {
              onDownloadProgress: ({ loaded, total, progress, bytes, download }) => {
                console.log(
                  `Download Progress ${loaded} from ${total} bytes (${(progress * 100).toFixed(1)}%)`
                );

                samples.push({
                  loaded,
                  total,
                  progress,
                  bytes,
                  download,
                });
              },
              headers: {
                'Content-Length': contentLength,
              },
              responseType: 'text',
              maxRedirects: 0,
            }
          );

          await setTimeoutAsync(500);

          assert.strictEqual(data, content);

          assert.deepStrictEqual(
            samples,
            Array.from(
              (function* () {
                for (let i = 1; i <= 10; i++) {
                  yield {
                    loaded: chunkLength * i,
                    total: contentLength,
                    progress: (chunkLength * i) / contentLength,
                    bytes: 4,
                    download: true,
                  };
                }
              })()
            )
          );
        } finally {
          await stopHTTPServer(server);
        }
      }, 15000);
    });
  });

  it('should support basic auth', async () => {
    const server = await startHTTPServer((req, res) => res.end(req.headers.authorization), {
      port: SERVER_PORT,
    });

    try {
      const user = 'foo';
      const headers = { Authorization: 'Bearer 1234' };
      const res = await fetchAxios.get(`http://${user}@localhost:${server.address().port}/`, {
        headers,
      });

      const base64 = Buffer.from(`${user}:`, 'utf8').toString('base64');
      assert.equal(res.data, `Basic ${base64}`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should decode basic auth credentials from the request URL', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.end(req.headers.authorization);
      },
      { port: SERVER_PORT }
    );

    try {
      const response = await fetchAxios.get(
        `http://my%40email.com:pa%24ss@localhost:${server.address().port}/`
      );
      const base64 = Buffer.from('my@email.com:pa$ss', 'utf8').toString('base64');
      assert.strictEqual(response.data, `Basic ${base64}`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should UTF-8 encode basic auth credentials from the request URL', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.end(req.headers.authorization);
      },
      { port: SERVER_PORT }
    );

    try {
      const response = await fetchAxios.get(
        `http://%E7%94%A8%E6%88%B7:pa%C3%9F@localhost:${server.address().port}/`
      );
      const base64 = Buffer.from('\u7528\u6237:pa\u00df', 'utf8').toString('base64');
      assert.strictEqual(response.data, `Basic ${base64}`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('keeps malformed URL credentials percent-encoding and does not throw', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.end(req.headers.authorization);
      },
      { port: SERVER_PORT }
    );

    try {
      const response = await fetchAxios.get(`http://user%:foo%zz@localhost:${server.address().port}/`);
      const base64 = Buffer.from('user%:foo%zz', 'utf8').toString('base64');
      assert.strictEqual(response.data, `Basic ${base64}`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should support password-only basic auth credentials from the request URL', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.end(req.headers.authorization);
      },
      { port: SERVER_PORT }
    );

    try {
      const response = await fetchAxios.get(`http://:secret@localhost:${server.address().port}/`);
      const base64 = Buffer.from(':secret', 'utf8').toString('base64');
      assert.strictEqual(response.data, `Basic ${base64}`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should prefer config auth over basic auth credentials from the request URL', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.end(req.headers.authorization);
      },
      { port: SERVER_PORT }
    );

    try {
      const auth = { username: 'config-user', password: 'config-pass' };
      const response = await fetchAxios.get(
        `http://url-user:url-pass@localhost:${server.address().port}/`,
        { auth }
      );
      const base64 = Buffer.from('config-user:config-pass', 'utf8').toString('base64');
      assert.strictEqual(response.data, `Basic ${base64}`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should support basic auth with a header', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.end(req.headers.authorization);
      },
      { port: SERVER_PORT }
    );

    try {
      const auth = { username: 'foo', password: 'bar' };
      const headers = { AuThOrIzAtIoN: 'Bearer 1234' }; // wonky casing to ensure caseless comparison
      const response = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
        auth,
        headers,
      });
      const base64 = Buffer.from('foo:bar', 'utf8').toString('base64');
      assert.strictEqual(response.data, `Basic ${base64}`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should ignore inherited nested auth fields', async () => {
    const server = await startHTTPServer((req, res) => res.end(req.headers.authorization), {
      port: SERVER_PORT,
    });

    Object.defineProperty(Object.prototype, 'username', {
      value: 'inherited-user',
      configurable: true,
    });
    Object.defineProperty(Object.prototype, 'password', {
      value: 'inherited-pass',
      configurable: true,
    });

    try {
      const response = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
        auth: {},
      });

      assert.strictEqual(response.data, 'Basic Og==');
    } finally {
      delete Object.prototype.username;
      delete Object.prototype.password;
      await stopHTTPServer(server);
    }
  });

  it('should support stream.Readable as a payload', async () => {
    const server = await startHTTPServer(async (req, res) => res.end('OK'), { port: SERVER_PORT });

    try {
      const { data } = await fetchAxios.post(
        `http://localhost:${server.address().port}/`,
        stream.Readable.from('OK')
      );

      assert.strictEqual(data, 'OK');
    } finally {
      await stopHTTPServer(server);
    }
  });

  describe('request aborting', () => {
    it('should be able to abort the request stream', async () => {
      const server = await startHTTPServer(
        {
          rate: 100000,
          useBuffering: true,
        },
        { port: SERVER_PORT }
      );

      try {
        const controller = new AbortController();

        setTimeout(() => {
          controller.abort();
        }, 500);

        await assert.rejects(async () => {
          await fetchAxios.post(
            `http://localhost:${server.address().port}/`,
            makeReadableStream(),
            {
              responseType: 'stream',
              signal: controller.signal,
            }
          );
        }, /CanceledError/);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should be able to abort the response stream', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          pipelineAsync(generateReadable(10000, 10), res).catch(() => {
            // Client-side abort intentionally closes the stream early in this test.
          });
        },
        { port: SERVER_PORT }
      );

      try {
        const controller = new AbortController();

        setTimeout(() => {
          controller.abort(new Error('test'));
        }, 800);

        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          responseType: 'stream',
          signal: controller.signal,
        });

        await assert.rejects(async () => {
          await data.pipeTo(makeEchoStream());
        }, /^(AbortError|CanceledError):/);
      } finally {
        await stopHTTPServer(server);
      }
    });
  });

  it('should support a timeout', async () => {
    const server = await startHTTPServer(
      async (req, res) => {
        await setTimeoutAsync(1000);
        res.end('OK');
      },
      { port: 0 }
    );

    try {
      const timeout = 500;

      const ts = Date.now();

      await assert.rejects(async () => {
        await fetchAxios(`http://localhost:${server.address().port}/`, {
          timeout,
        });
      }, /timeout/);

      const passed = Date.now() - ts;

      assert.ok(passed >= timeout - 5, `early cancellation detected (${passed} ms)`);
    } finally {
      await stopHTTPServer(server);
    }
  });

  describe('fetch adapter - timeout normalization', () => {
    it('should reject with an AxiosError(ETIMEDOUT) on timeout', async () => {
      const server = await startHTTPServer(
        async (req, res) => {
          await setTimeoutAsync(1000);
          res.end('OK');
        },
        { port: 0 }
      );

      try {
        await assert.rejects(
          () =>
            fetchAxios(`http://localhost:${server.address().port}/`, {
              timeout: 200,
            }),
          (err) => {
            assert.strictEqual(err.name, 'AxiosError');
            assert.strictEqual(err.code, 'ETIMEDOUT');
            assert.match(err.message, /timeout of 200ms exceeded/);
            return true;
          }
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should not classify a user-initiated abort as a timeout', async () => {
      const safariFetch = (url, init) => {
        const signal = getFetchSignal(url, init);

        return new Promise((_resolve, reject) => {
          const onAbort = () => {
            signal.removeEventListener('abort', onAbort);
            reject(createBrokenDOMExceptionLikeError());
          };

          if (signal.aborted) return onAbort();
          signal.addEventListener('abort', onAbort);
        });
      };

      const controller = new AbortController();

      const request = fetchAxios.get('/', {
        signal: controller.signal,
        env: { fetch: safariFetch },
      });

      controller.abort();

      await assert.rejects(
        () => request,
        (err) => {
          assert.strictEqual(err.name, 'CanceledError');
          assert.strictEqual(err.code, 'ERR_CANCELED');
          assert.strictEqual(axios.isCancel(err), true);
          return true;
        }
      );
    });

    // Timing-sensitive: a 50ms abort race observed by a fake fetch can flake
    // under CI runner load even though the production code is fine. Retry as
    // a backstop.
    it(
      'should surface ETIMEDOUT when fetch rejects with a broken DOMException on abort (Safari)',
      { retry: 2 },
      async () => {
        const safariFetch = (url, init) => {
          const signal = getFetchSignal(url, init);

          return new Promise((_resolve, reject) => {
            const onAbort = () => {
              signal.removeEventListener('abort', onAbort);
              reject(createBrokenDOMExceptionLikeError());
            };

            if (signal.aborted) return onAbort();
            signal.addEventListener('abort', onAbort);
          });
        };

        await assert.rejects(
          () =>
            fetchAxios.get('/', {
              timeout: 50,
              env: { fetch: safariFetch },
            }),
          (err) => {
            assert.strictEqual(err.name, 'AxiosError');
            assert.strictEqual(err.code, 'ETIMEDOUT');
            assert.match(err.message, /timeout of 50ms exceeded/);
            return true;
          }
        );
      }
    );
  });

  it('should combine baseURL and url', async () => {
    const server = await startHTTPServer(async (req, res) => res.end('OK'), { port: SERVER_PORT });
    try {
      const res = await fetchAxios('/foo');

      assert.equal(res.config.baseURL, LOCAL_SERVER_URL);
      assert.equal(res.config.url, '/foo');
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should send QUERY requests with a body through the fetch adapter', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        let body = '';
        req.on('data', (chunk) => {
          body += chunk;
        });
        req.on('end', () => {
          res.setHeader('Content-Type', 'application/json');
          res.end(JSON.stringify({ method: req.method, url: req.url, body }));
        });
      },
      { port: 0 }
    );

    try {
      const { data } = await fetchAxios.query(`http://localhost:${server.address().port}/search`, {
        selector: 'field1',
      });

      assert.strictEqual(data.method, 'QUERY');
      assert.strictEqual(data.url, '/search');
      assert.deepStrictEqual(JSON.parse(data.body), { selector: 'field1' });
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should support params', async () => {
    const server = await startHTTPServer((req, res) => res.end(req.url), { port: SERVER_PORT });
    try {
      const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/?test=1`, {
        params: {
          foo: 1,
          bar: 2,
        },
      });

      assert.strictEqual(data, '/?test=1&foo=1&bar=2');
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should handle fetch failed error as an AxiosError with ERR_NETWORK code', async () => {
    try {
      await fetchAxios('http://notExistsUrl.in.nowhere');
      assert.fail('should fail');
    } catch (err) {
      assert.strictEqual(String(err), 'AxiosError: Network Error');
      assert.strictEqual(err.cause && err.cause.code, 'ENOTFOUND');
    }
  });

  it('should get response headers', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.setHeader('foo', 'bar');
        res.end(req.url);
      },
      { port: SERVER_PORT }
    );

    try {
      const { headers } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
        responseType: 'stream',
      });

      assert.strictEqual(headers.get('foo'), 'bar');
    } finally {
      await stopHTTPServer(server);
    }
  });

  describe('fetch adapter - Content-Type handling', () => {
    it('should set correct Content-Type for FormData automatically', async () => {
      const form = new NodeFormData();
      form.append('foo', 'bar');

      const server = await startHTTPServer(
        (req, res) => {
          const contentType = req.headers['content-type'];
          assert.match(contentType, /^multipart\/form-data; boundary=/i);
          res.end('OK');
        },
        { port: SERVER_PORT }
      );

      try {
        await fetchAxios.post(`http://localhost:${server.address().port}/form`, form);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should remove manually set Content-Type without boundary for FormData', async () => {
      const form = new FormData();
      form.append('foo', 'bar');

      const server = await startHTTPServer(
        (req, res) => {
          const contentType = req.headers['content-type'];
          assert.match(contentType, /^multipart\/form-data; boundary=/i);
          res.end('OK');
        },
        { port: SERVER_PORT }
      );

      try {
        await fetchAxios.post(`http://localhost:${server.address().port}/form`, form, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should preserve Content-Type if it already has boundary', async () => {
      const form = new FormData();
      form.append('foo', 'bar');

      const customBoundary = '----CustomBoundary123';

      const server = await startHTTPServer(
        (req, res) => {
          const contentType = req.headers['content-type'];
          assert.ok(contentType.includes(customBoundary));
          res.end('OK');
        },
        { port: SERVER_PORT }
      );

      try {
        await fetchAxios.post(`http://localhost:${server.address().port}/form`, form, {
          headers: {
            'Content-Type': `multipart/form-data; boundary=${customBoundary}`,
          },
        });
      } finally {
        await stopHTTPServer(server);
      }
    });
  });

  describe('fetch adapter - User-Agent header', () => {
    it('should set User-Agent header to axios/<version> by default', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          res.setHeader('Content-Type', 'application/json');
          res.end(JSON.stringify({ userAgent: req.headers['user-agent'] }));
        },
        { port: SERVER_PORT }
      );

      try {
        const { data } = await fetchAxios.post(`http://localhost:${server.address().port}/`, {
          payload: 'test',
        });

        assert.strictEqual(data.userAgent, `axios/${VERSION}`);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should not override a user-provided User-Agent header', async () => {
      const customUA = 'my-custom-agent/1.0';

      const server = await startHTTPServer(
        (req, res) => {
          res.setHeader('Content-Type', 'application/json');
          res.end(JSON.stringify({ userAgent: req.headers['user-agent'] }));
        },
        { port: SERVER_PORT }
      );

      try {
        const { data } = await fetchAxios.post(
          `http://localhost:${server.address().port}/`,
          { payload: 'test' },
          { headers: { 'User-Agent': customUA } }
        );

        assert.strictEqual(data.userAgent, customUA);
      } finally {
        await stopHTTPServer(server);
      }
    });
  });

  describe('env config', () => {
    it('should fallback to globalThis when utils.global is temporarily undefined', () => {
      const originalGlobal = utils.global;

      try {
        utils.global = undefined;

        assert.doesNotThrow(() =>
          getFetch({
            env: {
              fetch() {},
            },
          })
        );
      } finally {
        utils.global = originalGlobal;
      }
    });

    it('should respect env fetch API configuration', async () => {
      const { data, headers } = await fetchAxios.get('/', {
        env: {
          fetch() {
            return {
              headers: {
                foo: '1',
              },
              text: async () => 'test',
            };
          },
        },
      });

      assert.strictEqual(headers.get('foo'), '1');
      assert.strictEqual(data, 'test');
    });

    it('should be able to request with lack of Request object', async () => {
      const form = new FormData();

      form.append('x', '1');

      const { data, headers } = await fetchAxios.post('/', form, {
        onUploadProgress() {
          // dummy listener to activate streaming
        },
        env: {
          Request: null,
          fetch() {
            return {
              headers: {
                foo: '1',
              },
              text: async () => 'test',
            };
          },
        },
      });

      assert.strictEqual(headers.get('foo'), '1');
      assert.strictEqual(data, 'test');
    });

    it('should be able to handle response with lack of Response object', async () => {
      const { data, headers } = await fetchAxios.get('/', {
        onDownloadProgress() {
          // dummy listener to activate streaming
        },
        env: {
          Request: null,
          Response: null,
          fetch() {
            return {
              headers: {
                foo: '1',
              },
              text: async () => 'test',
            };
          },
        },
      });

      assert.strictEqual(headers.get('foo'), '1');
      assert.strictEqual(data, 'test');
    });

    it('should fallback to the global on undefined env value', async () => {
      const server = await startHTTPServer((req, res) => res.end('OK'), { port: SERVER_PORT });

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          env: {
            fetch: undefined,
          },
        });

        assert.strictEqual(data, 'OK');
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should use current global fetch when env fetch is not specified', async () => {
      const globalFetch = global.fetch;

      vi.stubGlobal('fetch', async () => {
        return {
          headers: {
            foo: '1',
          },
          text: async () => 'global',
        };
      });

      const server = await startHTTPServer((req, res) => res.end('OK'), { port: SERVER_PORT });

      try {
        const { data } = await fetchAxios.get(`http://localhost:${server.address().port}/`, {
          env: {
            fetch: undefined,
          },
        });

        assert.strictEqual(data, 'global');
      } finally {
        vi.stubGlobal('fetch', globalFetch);
        await stopHTTPServer(server);
      }
    });
  });

  describe('size limits', () => {
    const makeUploadStream = (totalBytes, chunkSize = 512) => {
      let remaining = totalBytes;

      return new ReadableStream({
        pull(controller) {
          if (remaining <= 0) {
            controller.close();
            return;
          }

          const size = Math.min(chunkSize, remaining);
          remaining -= size;
          controller.enqueue(new Uint8Array(size));
        },
      });
    };

    it('should reject an outbound body that exceeds maxBodyLength with ERR_BAD_REQUEST', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          res.end('ok');
        },
        { port: SERVER_PORT }
      );

      try {
        await assert.rejects(
          fetchAxios.post(`${LOCAL_SERVER_URL}/`, 'A'.repeat(2048), {
            maxBodyLength: 1024,
          }),
          (err) => {
            assert.strictEqual(err.code, 'ERR_BAD_REQUEST');
            assert.match(err.message, /Request body larger than maxBodyLength limit/);
            return true;
          }
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should reject a streamed outbound body that exceeds maxBodyLength during upload', async () => {
      let bytesReceived = 0;
      const server = await startHTTPServer(
        (req, res) => {
          req.on('data', (chunk) => {
            bytesReceived += chunk.length;
          });
          req.on('error', () => {});
          req.on('end', () => {
            res.end('ok');
          });
        },
        { port: SERVER_PORT }
      );

      try {
        await assert.rejects(
          fetchAxios.post(`${LOCAL_SERVER_URL}/`, makeUploadStream(2048), {
            maxBodyLength: 1024,
            headers: { 'Content-Type': 'application/octet-stream' },
          }),
          (err) => {
            assert.strictEqual(err.code, 'ERR_BAD_REQUEST');
            assert.strictEqual(err.message, 'Request body larger than maxBodyLength limit');
            return true;
          }
        );

        assert.ok(
          bytesReceived <= 1024,
          `server should not receive more than maxBodyLength; got ${bytesReceived}`
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should enforce maxBodyLength on a stream even when a smaller Content-Length is declared', async () => {
      let bytesReceived = 0;
      const server = await startHTTPServer(
        (req, res) => {
          req.on('data', (chunk) => {
            bytesReceived += chunk.length;
          });
          req.on('error', () => {});
          req.on('end', () => {
            res.end('ok');
          });
        },
        { port: SERVER_PORT }
      );

      try {
        await assert.rejects(
          // A caller-declared Content-Length that under-reports the real body
          // must not let an oversized stream slip past the limit.
          fetchAxios.post(`${LOCAL_SERVER_URL}/`, makeUploadStream(8192), {
            maxBodyLength: 1024,
            headers: {
              'Content-Type': 'application/octet-stream',
              'Content-Length': '500',
            },
          }),
          (err) => {
            assert.strictEqual(err.code, 'ERR_BAD_REQUEST');
            assert.strictEqual(err.message, 'Request body larger than maxBodyLength limit');
            return true;
          }
        );

        assert.ok(
          bytesReceived <= 1024,
          `server should not receive more than maxBodyLength; got ${bytesReceived}`
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should enforce maxBodyLength with custom fetch when Request is unavailable', async () => {
      let bytesRead = 0;

      await assert.rejects(
        fetchAxios.post('/', makeUploadStream(2048), {
          maxBodyLength: 1024,
          headers: {
            'Content-Type': 'application/octet-stream',
            'Content-Length': '1',
          },
          env: {
            Request: null,
            async fetch(_url, options) {
              for await (const chunk of options.body) {
                bytesRead += chunk.byteLength;
              }
              return {
                headers: {},
                status: 200,
                statusText: 'OK',
                text: async () => 'ok',
              };
            },
          },
        }),
        (err) => {
          assert.strictEqual(err.code, 'ERR_BAD_REQUEST');
          assert.strictEqual(err.message, 'Request body larger than maxBodyLength limit');
          return true;
        }
      );

      assert.ok(bytesRead <= 1024, `custom fetch read too many bytes; got ${bytesRead}`);
    });

    it('should not force ReadableStream bodies when Request does not support request streams', async () => {
      let fetchCalled = false;

      class NoStreamRequest {
        constructor(_url, init) {
          if (init && utils.isReadableStream(init.body)) {
            throw new TypeError('ReadableStream request bodies are unsupported');
          }
        }
      }

      await assert.rejects(
        fetchAxios.post('/', stream.Readable.from([Buffer.alloc(2048)]), {
          maxBodyLength: 1024,
          headers: {
            'Content-Type': 'application/octet-stream',
          },
          env: {
            Request: NoStreamRequest,
            Response: null,
            async fetch() {
              fetchCalled = true;
              return {
                headers: {},
                status: 200,
                statusText: 'OK',
                text: async () => 'ok',
              };
            },
          },
        }),
        (err) => {
          assert.strictEqual(err.code, 'ERR_NOT_SUPPORT');
          assert.strictEqual(
            err.message,
            'Stream request bodies are not supported by the current fetch implementation'
          );
          return true;
        }
      );

      assert.strictEqual(fetchCalled, false, 'fetch must not receive a forced ReadableStream body');
    });

    it('should reject a response whose Content-Length exceeds maxContentLength with ERR_BAD_RESPONSE', async () => {
      const payload = 'A'.repeat(8 * 1024);
      const server = await startHTTPServer(
        (req, res) => {
          res.setHeader('Content-Length', Buffer.byteLength(payload));
          res.end(payload);
        },
        { port: SERVER_PORT }
      );

      try {
        await assert.rejects(
          fetchAxios.get(`${LOCAL_SERVER_URL}/`, {
            maxContentLength: 1024,
          }),
          (err) => {
            assert.strictEqual(err.code, 'ERR_BAD_RESPONSE');
            assert.match(err.message, /maxContentLength size of 1024 exceeded/);
            return true;
          }
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should handle plain object response headers while enforcing maxContentLength', async () => {
      const { data, headers } = await fetchAxios.get('/', {
        maxContentLength: 10,
        env: {
          async fetch() {
            return {
              status: 200,
              statusText: 'OK',
              headers: {
                'content-length': '4',
                foo: 'bar',
              },
              body: new ReadableStream({
                start(controller) {
                  controller.enqueue(new Uint8Array([116, 101, 115, 116]));
                  controller.close();
                },
              }),
            };
          },
        },
      });

      assert.strictEqual(data, 'test');
      assert.strictEqual(headers.get('foo'), 'bar');
    });

    it('should reject a chunked response that exceeds maxContentLength during streaming', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          // Omit content-length so the cheap pre-check cannot fire; force
          // the stream-based enforcement path.
          res.setHeader('Transfer-Encoding', 'chunked');
          const chunk = 'B'.repeat(1024);
          let sent = 0;
          const writeNext = () => {
            if (sent >= 8) {
              return res.end();
            }
            sent++;
            res.write(chunk, writeNext);
          };
          writeNext();
        },
        { port: SERVER_PORT }
      );

      try {
        await assert.rejects(
          fetchAxios.get(`${LOCAL_SERVER_URL}/`, {
            maxContentLength: 512,
          }),
          (err) => {
            assert.strictEqual(err.code, 'ERR_BAD_RESPONSE');
            assert.match(err.message, /maxContentLength size of 512 exceeded/);
            return true;
          }
        );
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should reject a data: URL whose decoded size exceeds maxContentLength (base64)', async () => {
      const payload = 'A'.repeat(4096);
      const dataUrl =
        'data:application/octet-stream;base64,' + Buffer.from(payload).toString('base64');

      // Use a dedicated instance without baseURL — combineURLs would otherwise
      // prepend baseURL to a data: URL and neutralise the pre-check.
      const bareAxios = axios.create({ adapter: 'fetch' });

      await assert.rejects(bareAxios.get(dataUrl, { maxContentLength: 16 }), (err) => {
        assert.strictEqual(err.code, 'ERR_BAD_RESPONSE');
        assert.match(err.message, /maxContentLength size of 16 exceeded/);
        return true;
      });
    });

    it('should reject a data: URL whose body size exceeds maxContentLength (non-base64)', async () => {
      const dataUrl = 'data:text/plain,' + 'X'.repeat(4096);

      const bareAxios = axios.create({ adapter: 'fetch' });

      await assert.rejects(bareAxios.get(dataUrl, { maxContentLength: 16 }), (err) => {
        assert.strictEqual(err.code, 'ERR_BAD_RESPONSE');
        assert.match(err.message, /maxContentLength size of 16 exceeded/);
        return true;
      });
    });

    it('should allow a percent-encoded data: URL within decoded maxContentLength', async () => {
      const bareAxios = axios.create({ adapter: 'fetch' });
      const { data } = await bareAxios.get('data:text/plain,%E2%82%AC', {
        maxContentLength: 4,
      });

      assert.strictEqual(data, '\u20ac');
    });

    it('should allow a response at or below maxContentLength', async () => {
      const payload = 'ok';
      const server = await startHTTPServer(
        (req, res) => {
          res.end(payload);
        },
        { port: SERVER_PORT }
      );

      try {
        const { data } = await fetchAxios.get(`${LOCAL_SERVER_URL}/`, {
          maxContentLength: 1024,
        });
        assert.strictEqual(data, payload);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should allow a streamed outbound body at or below maxBodyLength', async () => {
      const payloadLength = 1024;
      let bytesReceived = 0;
      const server = await startHTTPServer(
        (req, res) => {
          req.on('data', (chunk) => {
            bytesReceived += chunk.length;
          });
          req.on('end', () => {
            res.setHeader('Content-Type', 'application/json');
            res.end(JSON.stringify({ received: bytesReceived }));
          });
        },
        { port: SERVER_PORT }
      );

      try {
        const { data } = await fetchAxios.post(
          `${LOCAL_SERVER_URL}/`,
          makeUploadStream(payloadLength),
          {
            maxBodyLength: 1024,
            headers: { 'Content-Type': 'application/octet-stream' },
          }
        );

        assert.strictEqual(data.received, payloadLength);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should allow a body at or below maxBodyLength', async () => {
      const payload = 'hello';
      let received;
      const server = await startHTTPServer(
        (req, res) => {
          const chunks = [];
          req.on('data', (c) => chunks.push(c));
          req.on('end', () => {
            received = Buffer.concat(chunks).toString();
            res.end('ok');
          });
        },
        { port: SERVER_PORT }
      );

      try {
        await fetchAxios.post(`${LOCAL_SERVER_URL}/`, payload, {
          maxBodyLength: 1024,
        });
        assert.strictEqual(received, payload);
      } finally {
        await stopHTTPServer(server);
      }
    });
  });

  describe('capability probe cleanup', () => {
    it('should cancel the ReadableStream created during the request stream probe', () => {
      // The fetch adapter factory probes for request-stream support by creating
      // a ReadableStream as a Request body.  Previously the stream was never
      // cancelled, leaving a dangling pull-algorithm promise (async resource leak
      // visible via `--detect-async-leaks` or Node.js async_hooks).
      //
      // Calling getFetch with a unique env triggers a fresh factory() execution
      // (including the probe).  We spy on ReadableStream.prototype.cancel to
      // verify it is invoked during the probe.

      const cancelSpy = vi.spyOn(ReadableStream.prototype, 'cancel');

      try {
        // Unique fetch function ensures cache miss → factory() re-runs the probe.
        const uniqueFetch = async () => new Response('ok');
        getFetch({ env: { fetch: uniqueFetch } });

        assert.ok(
          cancelSpy.mock.calls.length > 0,
          'ReadableStream.prototype.cancel should be called during the capability probe'
        );
      } finally {
        cancelSpy.mockRestore();
      }
    });
  });
});

import { beforeEach, describe, it } from 'vitest';
import assert from 'assert';
import adapters from '../../../lib/adapters/adapters.js';

describe('adapters', () => {
  const store = { ...adapters.adapters };

  beforeEach(() => {
    Object.keys(adapters.adapters).forEach((name) => {
      delete adapters.adapters[name];
    });

    Object.assign(adapters.adapters, store);
  });

  it('should support loading by fn handle', () => {
    const adapter = () => {};
    assert.strictEqual(adapters.getAdapter(adapter), adapter);
  });

  it('should support loading by name', () => {
    const adapter = () => {};
    adapters.adapters.testadapter = adapter;
    assert.strictEqual(adapters.getAdapter('testAdapter'), adapter);
  });

  it('should detect adapter unavailable status', () => {
    adapters.adapters.testadapter = null;
    assert.throws(() => adapters.getAdapter('testAdapter'), /is not available in the build/);
  });

  it('should detect adapter unsupported status', () => {
    adapters.adapters.testadapter = false;
    assert.throws(() => adapters.getAdapter('testAdapter'), /is not supported by the environment/);
  });

  it('should pick suitable adapter from the list', () => {
    const adapter = () => {};

    Object.assign(adapters.adapters, {
      foo: false,
      bar: null,
      baz: adapter,
    });

    assert.strictEqual(adapters.getAdapter(['foo', 'bar', 'baz']), adapter);
  });
});

import { describe, it, expect } from 'vitest';
import AxiosError from '../../../lib/core/AxiosError.js';
import validator from '../../../lib/helpers/validator.js';

describe('validator::assertOptions', () => {
  it('should throw only if unknown an option was passed', () => {
    let error;
    try {
      validator.assertOptions(
        {
          x: true,
        },
        {
          y: validator.validators.boolean,
        }
      );
    } catch (err) {
      error = err;
    }
    expect(error).toBeInstanceOf(AxiosError);
    expect(error.message).toBe('Unknown option x');
    expect(error.code).toBe(AxiosError.ERR_BAD_OPTION);

    expect(() => {
      validator.assertOptions(
        {
          x: true,
        },
        {
          x: validator.validators.boolean,
          y: validator.validators.boolean,
        }
      );
    }).not.toThrow(new Error('Unknown option x'));
  });

  it("should throw TypeError only if option type doesn't match", () => {
    let error;
    try {
      validator.assertOptions(
        {
          x: 123,
        },
        {
          x: validator.validators.boolean,
        }
      );
    } catch (err) {
      error = err;
    }
    expect(error).toBeInstanceOf(AxiosError);
    expect(error.message).toBe('option x must be a boolean');
    expect(error.code).toBe(AxiosError.ERR_BAD_OPTION_VALUE);

    expect(() => {
      validator.assertOptions(
        {
          x: true,
        },
        {
          x: validator.validators.boolean,
          y: validator.validators.boolean,
        }
      );
    }).not.toThrow();
  });
});

import { describe, it, expect, vi } from 'vitest';
import buildURL, { encode } from '../../../lib/helpers/buildURL.js';

describe('helpers::buildURL', () => {
  it('should support null params', () => {
    expect(buildURL('/foo')).toEqual('/foo');
  });

  it('should support params', () => {
    expect(
      buildURL('/foo', {
        foo: 'bar',
        isUndefined: undefined,
        isNull: null,
      })
    ).toEqual('/foo?foo=bar');
  });

  it('should support sending raw params to custom serializer func', () => {
    const serializer = vi.fn().mockReturnValue('foo=bar');
    const params = { foo: 'bar' };
    const options = {
      serialize: serializer,
    };
    expect(
      buildURL(
        '/foo',
        {
          foo: 'bar',
        },
        options
      )
    ).toEqual('/foo?foo=bar');
    expect(serializer).toHaveBeenCalledTimes(1);
    expect(serializer).toHaveBeenCalledWith(params, options);
  });

  it('should support object params', () => {
    expect(
      buildURL('/foo', {
        foo: {
          bar: 'baz',
        },
      })
    ).toEqual('/foo?foo%5Bbar%5D=baz');
  });

  it('should support date params', () => {
    const date = new Date();

    expect(
      buildURL('/foo', {
        date,
      })
    ).toEqual('/foo?date=' + date.toISOString());
  });

  it('should support array params with encode', () => {
    expect(
      buildURL('/foo', {
        foo: ['bar', 'baz'],
      })
    ).toEqual('/foo?foo%5B%5D=bar&foo%5B%5D=baz');
  });

  it('should support special char params', () => {
    expect(
      buildURL('/foo', {
        foo: ':$, ',
      })
    ).toEqual('/foo?foo=:$,+');
  });

  it('should support existing params', () => {
    expect(
      buildURL('/foo?foo=bar', {
        bar: 'baz',
      })
    ).toEqual('/foo?foo=bar&bar=baz');
  });

  it('should support "length" parameter', () => {
    expect(
      buildURL('/foo', {
        query: 'bar',
        start: 0,
        length: 5,
      })
    ).toEqual('/foo?query=bar&start=0&length=5');
  });

  it('should correct discard url hash mark', () => {
    expect(
      buildURL('/foo?foo=bar#hash', {
        query: 'baz',
      })
    ).toEqual('/foo?foo=bar&query=baz');
  });

  it('should support URLSearchParams', () => {
    expect(buildURL('/foo', new URLSearchParams('bar=baz'))).toEqual('/foo?bar=baz');
  });

  it('should support custom serialize function', () => {
    const params = {
      x: 1,
    };

    const options = {
      serialize: (thisParams, thisOptions) => {
        expect(thisParams).toEqual(params);
        expect(thisOptions).toEqual(options);
        return 'rendered';
      },
    };

    expect(buildURL('/foo', params, options)).toEqual('/foo?rendered');

    const customSerializer = (thisParams) => {
      expect(thisParams).toEqual(params);
      return 'rendered';
    };

    expect(buildURL('/foo', params, customSerializer)).toEqual('/foo?rendered');
  });

  it('should ignore inherited serializer options', () => {
    let serializeInvoked = false;
    let encodeInvoked = false;

    Object.defineProperty(Object.prototype, 'serialize', {
      value() {
        serializeInvoked = true;
        return 'inherited=1';
      },
      configurable: true,
    });
    Object.defineProperty(Object.prototype, 'encode', {
      value() {
        encodeInvoked = true;
        return 'inherited';
      },
      configurable: true,
    });

    try {
      expect(buildURL('/foo', { value: 'a b' }, {})).toEqual('/foo?value=a+b');
      expect(serializeInvoked).toBe(false);
      expect(encodeInvoked).toBe(false);
    } finally {
      delete Object.prototype.serialize;
      delete Object.prototype.encode;
    }
  });
});

describe('helpers::encode', () => {
  it('should be exported as a named export', () => {
    expect(typeof encode).toBe('function');
  });

  it('should leave plain ASCII unchanged', () => {
    expect(encode('foo')).toEqual('foo');
  });

  it('should preserve `:` rather than percent-encoding it', () => {
    expect(encode(':')).toEqual(':');
  });

  it('should preserve `$` rather than percent-encoding it', () => {
    expect(encode('$')).toEqual('$');
  });

  it('should preserve `,` rather than percent-encoding it', () => {
    expect(encode(',')).toEqual(',');
  });

  it('should encode space as `+` (form-style) rather than `%20`', () => {
    expect(encode(' ')).toEqual('+');
  });

  it('should still percent-encode characters outside the preserved set', () => {
    expect(encode('a/b')).toEqual('a%2Fb');
    expect(encode('a&b')).toEqual('a%26b');
    expect(encode('a=b')).toEqual('a%3Db');
  });

  it('should apply all substitutions together', () => {
    expect(encode('a:b$c,d e')).toEqual('a:b$c,d+e');
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import shouldBypassProxy from '../../../lib/helpers/shouldBypassProxy.js';

const originalNoProxy = process.env.no_proxy;
const originalNOProxy = process.env.NO_PROXY;

const setNoProxy = (value) => {
  process.env.no_proxy = value;
  process.env.NO_PROXY = value;
};

afterEach(() => {
  if (originalNoProxy === undefined) {
    delete process.env.no_proxy;
  } else {
    process.env.no_proxy = originalNoProxy;
  }

  if (originalNOProxy === undefined) {
    delete process.env.NO_PROXY;
  } else {
    process.env.NO_PROXY = originalNOProxy;
  }
});

describe('helpers::shouldBypassProxy', () => {
  it('should bypass proxy for localhost with a trailing dot', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://localhost.:8080/')).toBe(true);
  });

  it('should bypass proxy for bracketed ipv6 loopback', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
  });

  it('should support bracketed ipv6 entries in no_proxy', () => {
    setNoProxy('[::1]');

    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
  });

  it('should bypass proxy for 127.0.0.1 when no_proxy contains localhost', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://127.0.0.1:7777/')).toBe(true);
  });

  it('should bypass proxy for [::1] when no_proxy contains localhost', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://[::1]:7777/')).toBe(true);
  });

  it('should bypass proxy for localhost when no_proxy contains 127.0.0.1', () => {
    setNoProxy('127.0.0.1');

    expect(shouldBypassProxy('http://localhost:7777/')).toBe(true);
  });

  it('should bypass proxy for localhost when no_proxy contains ::1', () => {
    setNoProxy('::1');

    expect(shouldBypassProxy('http://localhost:7777/')).toBe(true);
  });

  it('should bypass proxy for 0.0.0.0 when no_proxy contains a local entry', () => {
    for (const entry of ['localhost', '127.0.0.1', '::1']) {
      setNoProxy(entry);

      expect(shouldBypassProxy('http://0.0.0.0:7777/')).toBe(true);
    }
  });

  it('should respect explicit ports for 0.0.0.0 local matching', () => {
    setNoProxy('localhost:8080');

    expect(shouldBypassProxy('http://0.0.0.0:8080/')).toBe(true);
    expect(shouldBypassProxy('http://0.0.0.0:9090/')).toBe(false);
  });

  it('should bypass proxy for the IPv6 unspecified address symmetrically with 0.0.0.0', () => {
    for (const entry of ['localhost', '127.0.0.1', '::1']) {
      setNoProxy(entry);

      expect(shouldBypassProxy('http://[::]:7777/')).toBe(true);
      expect(shouldBypassProxy('http://[0:0:0:0:0:0:0:0]:7777/')).toBe(true);
    }
  });

  it('should bypass proxy for compressed IPv6 unspecified request forms', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    for (const host of ['0::', '::0', '0:0::', '::0:0', '0::0']) {
      expect(shouldBypassProxy(`http://[${host}]:7777/`)).toBe(true);
    }
  });

  it('should bypass proxy for compressed IPv6 unspecified no_proxy entries', () => {
    for (const entry of ['0::', '::0', '0:0::', '::0:0', '0::0']) {
      setNoProxy(entry);

      expect(shouldBypassProxy('http://[::]:7777/')).toBe(true);
      expect(shouldBypassProxy('http://[0:0:0:0:0:0:0:0]:7777/')).toBe(true);
    }
  });

  it('should respect explicit ports on compressed IPv6 unspecified no_proxy entries', () => {
    setNoProxy('[0::]:8080');

    expect(shouldBypassProxy('http://[::]:8080/')).toBe(true);
    expect(shouldBypassProxy('http://[::]:9090/')).toBe(false);
  });

  it('should not treat nonzero compressed IPv6 addresses as unspecified', () => {
    setNoProxy('0::2');

    expect(shouldBypassProxy('http://[::]:7777/')).toBe(false);
  });

  it('should still route a real public IPv6 host through the proxy', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://[2001:db8::1]:7777/')).toBe(false);
  });

  it('should match wildcard and explicit ports', () => {
    setNoProxy('*.example.com,localhost:8080');

    expect(shouldBypassProxy('http://api.example.com/')).toBe(true);
    expect(shouldBypassProxy('http://localhost:8080/')).toBe(true);
    expect(shouldBypassProxy('http://localhost:8081/')).toBe(false);
  });

  it('should bypass proxy for any host when no_proxy is *', () => {
    setNoProxy('*');

    expect(shouldBypassProxy('http://example.com/')).toBe(true);
    expect(shouldBypassProxy('http://localhost:1234/')).toBe(true);
    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
  });

  it('should support bracketed ipv6 with explicit port in no_proxy', () => {
    setNoProxy('[::1]:8080');

    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
    expect(shouldBypassProxy('http://[::1]:8081/')).toBe(false);
  });

  it('should not bypass when no_proxy is empty', () => {
    setNoProxy('');

    expect(shouldBypassProxy('http://localhost:8080/')).toBe(false);
  });

  it('should not bypass for malformed URLs', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('not a url')).toBe(false);
  });

  it('should bypass proxy for 127.0.0.0/8 subnet when no_proxy contains 127.0.0.1', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://127.0.0.2:9191/secret')).toBe(true);
    expect(shouldBypassProxy('http://127.0.0.100:9191/secret')).toBe(true);
    expect(shouldBypassProxy('http://127.1.2.3:9191/secret')).toBe(true);
    expect(shouldBypassProxy('http://127.255.255.254:9191/secret')).toBe(true);
  });

  it('should bypass proxy for 127.0.0.0/8 subnet when no_proxy contains localhost', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://127.0.0.2:7777/')).toBe(true);
    expect(shouldBypassProxy('http://127.1.2.3:7777/')).toBe(true);
  });

  it('should NOT bypass for non-loopback IPv4 addresses', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://128.0.0.1:9191/')).toBe(false);
    expect(shouldBypassProxy('http://126.255.255.255:9191/')).toBe(false);
    expect(shouldBypassProxy('http://10.0.0.1:9191/')).toBe(false);
    expect(shouldBypassProxy('http://192.168.1.1:9191/')).toBe(false);
  });

  it('should NOT treat malformed 127-prefixed values as loopback', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    // bracketed IPv6 that happens to contain 127 dotted-form must not match IPv4 loopback
    expect(shouldBypassProxy('http://example.com/')).toBe(false);
  });

  it('should bypass proxy for full-form IPv6 loopback 0:0:0:0:0:0:0:1', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://[0:0:0:0:0:0:0:1]:8080/')).toBe(true);
  });

  it('should bypass proxy for IPv4-mapped IPv6 loopback ::ffff:127.0.0.1', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://[::ffff:127.0.0.1]:8080/')).toBe(true);
  });

  it('should treat 127.x.x.x as cross-equivalent to localhost and ::1', () => {
    setNoProxy('::1');

    expect(shouldBypassProxy('http://127.0.0.5:7777/')).toBe(true);
  });

  it('should still respect explicit port mismatch on no_proxy entries', () => {
    setNoProxy('127.0.0.1:8080');

    // same-port → bypass via cross-loopback equivalence
    expect(shouldBypassProxy('http://127.0.0.2:8080/')).toBe(true);
    // different port → no bypass
    expect(shouldBypassProxy('http://127.0.0.2:9090/')).toBe(false);
  });

  it('should not bypass for hosts that merely contain 127 in other octets', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://10.0.0.127:8080/')).toBe(false);
    expect(shouldBypassProxy('http://200.127.0.1:8080/')).toBe(false);
  });

  // IPv4-mapped IPv6 normalization: an attacker (or naive caller) can use the
  // IPv4-mapped IPv6 representation of an address (e.g. ::ffff:192.168.1.5)
  // to dodge a NO_PROXY policy expressed in IPv4 form, or vice-versa. After
  // canonicalising both sides, equivalent addresses compare equal.
  describe('IPv4-mapped IPv6 normalization', () => {
    it('should bypass via IPv4-mapped IPv6 request when NO_PROXY uses the IPv4 form', () => {
      setNoProxy('192.168.1.5');

      expect(shouldBypassProxy('http://[::ffff:192.168.1.5]/')).toBe(true);
    });

    it('should bypass via Node-normalised IPv4-mapped hex request against an IPv4 NO_PROXY', () => {
      // Node's URL parser canonicalises [::ffff:192.168.1.5] → [::ffff:c0a8:105].
      // The hex form must unmap to 192.168.1.5 to match the entry.
      setNoProxy('192.168.1.5');

      expect(shouldBypassProxy('http://[::ffff:c0a8:105]/')).toBe(true);
    });

    it('should bypass via plain IPv4 request when NO_PROXY uses the IPv4-mapped IPv6 dotted form', () => {
      setNoProxy('::ffff:192.168.1.5');

      expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
    });

    it('should bypass via plain IPv4 request when NO_PROXY uses the IPv4-mapped IPv6 hex form', () => {
      setNoProxy('::ffff:a00:1');

      expect(shouldBypassProxy('http://10.0.0.1/')).toBe(true);
    });

    it('should bypass via plain IPv4 request when NO_PROXY uses a bracketed IPv4-mapped IPv6 entry', () => {
      setNoProxy('[::ffff:192.168.1.5]');

      expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
    });

    it('should treat the uncompressed 0:0:0:0:0:ffff:<v4> form as equivalent', () => {
      setNoProxy('0:0:0:0:0:ffff:10.0.0.1');

      expect(shouldBypassProxy('http://10.0.0.1/')).toBe(true);
      expect(shouldBypassProxy('http://[::ffff:10.0.0.1]/')).toBe(true);
    });

    it('should treat compressed zero-prefix IPv4-mapped IPv6 dotted forms as equivalent', () => {
      for (const entry of [
        '0::ffff:192.168.1.5',
        '0:0::ffff:192.168.1.5',
        '0:0:0::ffff:192.168.1.5',
        '0:0:0:0::ffff:192.168.1.5',
      ]) {
        setNoProxy(entry);

        expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
      }
    });

    it('should treat compressed zero-prefix IPv4-mapped IPv6 hex forms as equivalent', () => {
      for (const entry of [
        '0::ffff:c0a8:105',
        '0:0::ffff:c0a8:105',
        '0:0:0::ffff:c0a8:105',
        '0:0:0:0::ffff:c0a8:105',
      ]) {
        setNoProxy(entry);

        expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
      }
    });

    it('should support compressed bracketed IPv4-mapped IPv6 entries with explicit ports', () => {
      setNoProxy('[0:0::ffff:192.168.1.5]:8080');

      expect(shouldBypassProxy('http://192.168.1.5:8080/')).toBe(true);
      expect(shouldBypassProxy('http://192.168.1.5:9090/')).toBe(false);
    });

    it('should NOT cross-match unrelated addresses', () => {
      setNoProxy('192.168.1.5');

      // Different IPv4 address inside an IPv4-mapped form must not bypass.
      expect(shouldBypassProxy('http://[::ffff:192.168.1.6]/')).toBe(false);
      // Non-mapped IPv6 must not be treated as IPv4.
      expect(shouldBypassProxy('http://[2001:db8::1]/')).toBe(false);
    });

    it('should leave non-mapped IPv6 addresses comparing as IPv6', () => {
      setNoProxy('2001:db8::1');

      expect(shouldBypassProxy('http://[2001:db8::1]/')).toBe(true);
      expect(shouldBypassProxy('http://[2001:db8::2]/')).toBe(false);
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { EventEmitter } from 'events';
import http2 from 'http2';
import Http2Sessions from '../../../lib/helpers/Http2Sessions.js';

function createFakeSession() {
  const session = new EventEmitter();
  session.destroyed = false;
  session.closed = false;
  session.close = vi.fn(() => {
    session.closed = true;
    session.emit('close');
  });
  const originalRequest = vi.fn(() => {
    const stream = new EventEmitter();
    stream.endStream = vi.fn();
    return stream;
  });
  session.request = originalRequest;
  session._originalRequest = originalRequest;
  return session;
}

describe('helpers::Http2Sessions', () => {
  let connectSpy;
  let pool;

  beforeEach(() => {
    connectSpy = vi.spyOn(http2, 'connect').mockImplementation(() => createFakeSession());
    pool = new Http2Sessions();
  });

  afterEach(() => {
    connectSpy.mockRestore();
    vi.useRealTimers();
  });

  it('reuses a cached session for the same authority and options', () => {
    const a = pool.getSession('https://example.test', { sessionTimeout: 1000 });
    const b = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    expect(a).toBe(b);
    expect(connectSpy).toHaveBeenCalledTimes(1);
  });

  it('creates a separate session for a different authority', () => {
    pool.getSession('https://example.test');
    pool.getSession('https://other.test');

    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('creates a new session when options differ for the same authority', () => {
    pool.getSession('https://example.test', { sessionTimeout: 1000 });
    pool.getSession('https://example.test', { sessionTimeout: 5000 });

    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('does not reuse a destroyed session', () => {
    const first = pool.getSession('https://example.test');
    first.destroyed = true;

    const second = pool.getSession('https://example.test');

    expect(second).not.toBe(first);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('does not reuse a closed session', () => {
    const first = pool.getSession('https://example.test');
    first.closed = true;

    const second = pool.getSession('https://example.test');

    expect(second).not.toBe(first);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('drops a session from the pool when its close event fires', () => {
    const first = pool.getSession('https://example.test');
    first.emit('close');

    const second = pool.getSession('https://example.test');

    expect(second).not.toBe(first);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('keeps unrelated authorities cached when one session closes', () => {
    const first = pool.getSession('https://example.test');
    const other = pool.getSession('https://other.test');
    first.emit('close');

    const otherAgain = pool.getSession('https://other.test');

    expect(otherAgain).toBe(other);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('closes and removes the session after sessionTimeout once the last stream ends', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const stream = session.request();
    stream.emit('close');

    expect(session.closed).toBe(false);

    vi.advanceTimersByTime(1000);

    expect(session.close).toHaveBeenCalledTimes(1);

    const next = pool.getSession('https://example.test', { sessionTimeout: 1000 });
    expect(next).not.toBe(session);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('cancels the pending sessionTimeout when a new stream opens', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const first = session.request();
    first.emit('close');

    session.request();
    vi.advanceTimersByTime(5000);

    expect(session.close).not.toHaveBeenCalled();
  });

  it('keeps the session alive while streams are still open', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const a = session.request();
    const b = session.request();
    a.emit('close');

    vi.advanceTimersByTime(5000);

    expect(session.close).not.toHaveBeenCalled();

    b.emit('close');
    vi.advanceTimersByTime(1000);

    expect(session.close).toHaveBeenCalledTimes(1);
  });

  it('defaults sessionTimeout to 1000ms when no options are passed', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test');

    const stream = session.request();
    stream.emit('close');

    vi.advanceTimersByTime(999);
    expect(session.close).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1);
    expect(session.close).toHaveBeenCalledTimes(1);
  });

  it('installs a request wrapper when sessionTimeout is set', () => {
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    expect(session.request).not.toBe(session._originalRequest);
  });

  it('does not install the request wrapper when sessionTimeout is null', () => {
    const session = pool.getSession('https://example.test', { sessionTimeout: null });

    expect(session.request).toBe(session._originalRequest);
  });

  it('cancels the pending idle timer when the session itself closes', () => {
    vi.useFakeTimers();
    const clearTimeoutSpy = vi.spyOn(globalThis, 'clearTimeout');

    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const stream = session.request();
    stream.emit('close');
    // An idle-removal timer is now pending.

    clearTimeoutSpy.mockClear();
    session.emit('close');

    // Closing the session must cancel the pending idle timer; otherwise it
    // keeps Node's event loop refed for up to sessionTimeout ms past close.
    expect(clearTimeoutSpy).toHaveBeenCalled();
  });
});

import { describe, it, expect } from 'vitest';
import parseHeaders from '../../../lib/helpers/parseHeaders.js';

describe('helpers::parseHeaders', () => {
  it('should parse headers', () => {
    const date = new Date();
    const parsed = parseHeaders(
      'Date: ' +
        date.toISOString() +
        '\n' +
        'Content-Type: application/json\n' +
        'Connection: keep-alive\n' +
        'Transfer-Encoding: chunked'
    );

    expect(parsed.date).toEqual(date.toISOString());
    expect(parsed['content-type']).toEqual('application/json');
    expect(parsed.connection).toEqual('keep-alive');
    expect(parsed['transfer-encoding']).toEqual('chunked');
  });

  it('should use array for set-cookie', () => {
    const parsedZero = parseHeaders('');
    const parsedSingle = parseHeaders('Set-Cookie: key=val;');
    const parsedMulti = parseHeaders('Set-Cookie: key=val;\n' + 'Set-Cookie: key2=val2;\n');

    expect(parsedZero['set-cookie']).toBeUndefined();
    expect(parsedSingle['set-cookie']).toEqual(['key=val;']);
    expect(parsedMulti['set-cookie']).toEqual(['key=val;', 'key2=val2;']);
  });

  it('should handle duplicates', () => {
    const parsed = parseHeaders(
      'Age: age-a\n' +
        'Age: age-b\n' +
        'Foo: foo-a\n' +
        'Foo: foo-b\n'
    );

    expect(parsed.age).toEqual('age-a');
    expect(parsed.foo).toEqual('foo-a, foo-b');
  });
});

import { describe, it, expect } from 'vitest';
import isAbsoluteURL from '../../../lib/helpers/isAbsoluteURL.js';

describe('helpers::isAbsoluteURL', () => {
  it('should return true if URL begins with valid scheme name', () => {
    expect(isAbsoluteURL('https://api.github.com/users')).toBe(true);
    expect(isAbsoluteURL('custom-scheme-v1.0://example.com/')).toBe(true);
    expect(isAbsoluteURL('HTTP://example.com/')).toBe(true);
  });

  it('should return false if URL begins with invalid scheme name', () => {
    expect(isAbsoluteURL('123://example.com/')).toBe(false);
    expect(isAbsoluteURL('!valid://example.com/')).toBe(false);
  });

  it('should return true if URL is protocol-relative', () => {
    expect(isAbsoluteURL('//example.com/')).toBe(true);
  });

  it('should return false if URL is relative', () => {
    expect(isAbsoluteURL('/foo')).toBe(false);
    expect(isAbsoluteURL('foo')).toBe(false);
  });
});

